[2892] = {name = "Смертельный яд", additional_info = "Классы: Разбойник\nТребуется 30-й ур.\n[q2]Использование: Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, наносящим 36 ед. урона от сил природы в течение 12 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 60 раз. (Вероятность срабатывания: 30%)"},
[2893] = {name = "Смертельный яд II", additional_info = "Классы: Разбойник\nТребуется 38-й ур.\n[q2]Использование: Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, наносящим 52 ед. урона от сил природы в течение 12 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 75 раз. (Вероятность срабатывания: 30%)"},
