[6038] = {name = "Гигантский жареный моллюск", additional_info = "Требуется 25-й ур.\n[q2]Использование: Восполняет 874.8 ед. здоровья за 27 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 8 на 15 мин."},
[6039] = {name = "Рецепт: гигантский жареный моллюск", additional_info = "Требует Кулинария (175)\n[q2]Использование: Обучение приготовлению огромного жареного моллюска.\nГигантский жареный моллюск\nТребуется 25-й ур.\n[q2]Использование: Восполняет 874.8 ед. здоровья за 27 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 8 на 15 мин.\nТребуется: Мясо гигантского моллюска , Острые специи"},
[6040] = {name = "Золотые чешуйчатые наручи", additional_info = "{Запястья} {Кольчуга}\nБроня: 91\nПрочность: 35 / 35\nТребуется 32-й ур."},
[6041] = {name = "Стальная цепь для оружия", additional_info = "Требует Кузнечное дело (190)\n[q2]Использование: Оснащение оружия цепью, не позволяющей вас обезоружить."},
[6042] = {name = "Железный шип для щита", additional_info = "Требует Кузнечное дело (150)\n[q2]Использование: Оснащение щита железным умбоном, позволяющим наносить урон при каждом блокировании щитом."},
[6043] = {name = "Железный противовес", additional_info = "Требует Кузнечное дело (165)\n[q2]Использование: Оснащает двуручное оружие противовесом, повышающим рейтинг скорости на 3%."},
[6044] = {name = "[q2]Чертеж: железный шип для щита", additional_info = "Требует Кузнечное дело (150)\n[q2]Использование: Обучение изготовлению железного шипа для щита.\nЖелезный шип для щита\nТребует Кузнечное дело (150)\n[q2]Использование: Оснащение щита железным умбоном, позволяющим наносить урон при каждом блокировании щитом.\nТребуется: Железный слиток (6), Зернистый шлифовальный камень (4)"},
[6045] = {name = "[q2]Чертеж: железный противовес", additional_info = "Требует Кузнечное дело (165)\n[q2]Использование: Обучение изготовлению железного противовеса для баансировки двуручного оружия.\nЖелезный противовес\nТребует Кузнечное дело (165)\n[q2]Использование: Оснащает двуручное оружие противовесом, повышающим рейтинг скорости на 3%.\nТребуется: Железный слиток (4), Зернистый шлифовальный камень (2), Малый лунный камень"},
[6046] = {name = "[q2]Чертеж: стальная цепь для оружия", additional_info = "Требует Кузнечное дело (190)\n[q2]Использование: Обучение изготовлению стальной цепи для оружия, которая не дает вас разоружить.\nСтальная цепь для оружия\nТребует Кузнечное дело (190)\n[q2]Использование: Оснащение оружия цепью, не позволяющей вас обезоружить.\nТребуется: Стальной слиток (8), Тяжелый шлифовальный камень (2), Толстая кожа (4)"},
[6047] = {name = "Чертеж: золотой чешуйчатый капюшон", additional_info = "Требует Кузнечное дело (190)\n[q2]Использование: Обучение изготовлению золотого чешуйчатого капюшона.\n[q2]Золотой чешуйчатый капюшон\nСтановится персональным при надевании\n{Голова} {Кольчуга}\nБроня: 181\n+10 к силе\n+10 к духу\nПрочность: 60 / 60\nТребуется 33-й ур.\nТребуется: Стальной слиток (8), Золотой слиток (2), Тяжелый шлифовальный камень (2)"},
[6048] = {name = "Зелье защиты от темной магии", additional_info = "Требуется 17-й ур.\n[q2]Использование: Поглощение 675 в 1125 ед. урона от темной магии. Время действия – 1 ч. (2 Мин Восстановление)"},
