[10577] = {name = "Гоблинская мортира", additional_info = "Становится персональным при надевании\nАксессуар\nТребует Инженерное дело (205)\n[q2]Использование: Нанесение 383 в 517 ед. урона от огня и оглушение целей в радиусе 5 м. на 3 сек. (10 Мин Восстановление)\n6 зарядов"},
[10578] = {name = "[q3]Сапоги Оброненной мысли", additional_info = "Становится персональным при надевании\n{Ступни} {Ткань}\nБроня: 38\n+3 к выносливости\n+6 к интеллекту\n+13 к духу\nПрочность: 40 / 40\nТребуется 33-й ур."},
