[10716] = {name = "Уменьшающий луч гномов", additional_info = "Становится персональным при надевании\nАксессуар\nТребует Инженерное дело (205)\n[q2]Использование: Уменьшение цели и снижение силы ее атаки на 250 ед. По крайней мере, так обычно бывает... (5 Мин Восстановление)"},
[10717] = {name = "Компас Ким'джаеля", additional_info = "Предмет, необходимый для задания\nУникальный"},
[10718] = {name = "Центробежный растягиватель Ким'джаеля", additional_info = "Предмет, необходимый для задания\nУникальный"},
[10719] = {name = "Передвижная сирена", additional_info = "Требует Инженерное дело (205)\n[q2]Использование: Призывает взрывоопасную овцу, которая взрывает ближайшего противника, нанося 135 в 165 ед. урона. Существует 3 мин., затем взрывается. (1 Мин Восстановление)"},
[10720] = {name = "Сетемет гномов", additional_info = "Становится персональным при надевании\nАксессуар\nТребует Инженерное дело (210)\n[q2]Использование: Цель запутывается в сети на 10 сек. Однако у этой сети много крючков, и порой она может зацепиться за одежду пользователя. (10 Мин Восстановление)"},
[10721] = {name = "[q2]Пояс гномов, хранящий от вреда", additional_info = "Становится персональным при надевании\n{Пояс} {Кожа}\nБроня: 66\n+6 к выносливости\nПрочность: 30 / 30\nТребует Инженерное дело (215)\n[q2]Использование: Защита силовым щитом, в течение 10 мин позволяющим поглотить 500 ед. урона. ВНИМАНИЕ: силовое поле может перегрузиться от удара, на время лишив носящего защиты. (Вероятность срабатывания: 5%) (1 Час Восстановление)"},
[10722] = {name = "Плюшевый цыпленок Ким'джаеля", additional_info = "Предмет, необходимый для задания\nУникальный"},
[10723] = {name = "Любительское радио гномов", additional_info = "Аксессуар"},
[10724] = {name = "[q2]Гномьи реактивные сапоги", additional_info = "Становится персональным при надевании\n{Ступни} {Ткань}\nБроня: 41\nПрочность: 35 / 35\nТребует Инженерное дело (225)\n[q2]Использование: Эти сапоги значительно увеличат скорость вашего бега на 20 сек. ВНИМАНИЕ! Источник энергии и гироскоп не всегда функционируют как полагается. (30 Мин Восстановление)"},
[10725] = {name = "Боевой цыпленок гномов", additional_info = "Становится персональным при поднятии\nАксессуар\nТребует Инженерное дело (230)\n[q2]Использование: Создание боевого цыпленка, который будет сражаться на вашей стороне в течение 1.50 мин., либо пока не будет уничтожен. (30 Мин Восстановление)"},
[10726] = {name = "[q2]Гномья шапка контроля над разумом", additional_info = "Становится персональным при надевании\n{Голова} {Ткань}\nБроня: 50\n+14 к духу\nПрочность: 45 / 45\nТребует Инженерное дело (215)\n[q2]Использование: Вступление в ментальное сражение с целью-гуманоидом в попытке получить над ней контроль. В случае успеха контроль над созданием длится 20 сек. (30 Мин Восстановление)"},
[10727] = {name = "Гоблинское драконье ружье", additional_info = "Становится персональным при поднятии\nАксессуар\n[q2]Использование: Нанесение 61 в 69 ед. урона от огня в течение 10 сек. всем целям в конусе поражения впереди инженера, использующего это оружие. Если оно, конечно, не взорвется... (5 Мин Восстановление)"},
[10728] = {name = "Выкройка: черная рубашка Щитолома", additional_info = "Требует Портняжное дело (200)\n[q2]Использование: Обучение изготовлению черной рубашки Щитолома.\nЧерная рубашка Щитолома\nРубашка\nТребуется: Рулон шелка (5), Черная краска , Шелковая нить"},
[10738] = {name = "Партия товара Гальвану", additional_info = "Предмет, необходимый для задания\nУникальный\n[q]\"Большая коробка оказывается неожиданно легкой.\""},
