[10841] = {name = "Чай из златошипа", additional_info = "Требуется 25-й ур.\n[q2]Использование: Восполнение 1344.6 ед. маны за 27 сек. Действие эффекта прерывается, если персонаж встает с места."},
[10842] = {name = "[q3]Ветрочешуйчатый саронг", additional_info = "Становится персональным при поднятии\n{Ноги} {Кожа}\nБроня: 136\n+7 к ловкости\n+10 к выносливости\n+10 к интеллекту\n+20 к духу\nПрочность: 75 / 75\nТребуется 49-й ур."},
[10843] = {name = "[q3]Перистая накидка", additional_info = "Становится персональным при поднятии\nСпина\nБроня: 39\n+4 к выносливости\n+4 к интеллекту\n+15 к духу\nТребуется 49-й ур."},
[10844] = {name = "[q3]Шпиль Хаккара", additional_info = "Становится персональным при поднятии\n{Двуручное} {Посох}\n{Урон: 126-190 } {Скорость 3.40}\n(46.47 ед. урона в секунду)\n+16 к выносливости\n+16 к духу\nПрочность: 100 / 100\nТребуется 49-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 18 ед."},
[10845] = {name = "[q3]Облачение Воина", additional_info = "Становится персональным при поднятии\n{Грудь} {Латы}\nБроня: 567\n+4 к ловкости\n+11 к выносливости\nПрочность: 135 / 135\nТребуется 49-й ур.\n[q2]Если на персонаже: Увеличение рейтинга уклонения на 2%."},
[10846] = {name = "[q3]Забрызганные кровью наголенники", additional_info = "Становится персональным при поднятии\n{Ступни} {Кольчуга}\nБроня: 221\n+5 к силе\n+6 к ловкости\n+20 к выносливости\nПрочность: 60 / 60\nТребуется 49-й ур."},
[10847] = {name = "[q4]Драконий зов", additional_info = "Становится персональным при поднятии\n{Одноручное} {Меч}\n{Урон: 72-135 } {Скорость 2.50}\n(41.40 ед. урона в секунду)\nПрочность: 105 / 105\nТребуется 52-й ур.\n[q2]Возможный эффект при попадании: Вызывает изумрудного дракончика для защиты вас в битве в течение короткого времени."},
[10858] = {name = "Чертеж: прочная железная кувалда", additional_info = "Требует Кузнечное дело (155)\n[q2]Использование: Обучение изготовлению прочной железной кувалды.\n[q2]Прочная железная кувалда\nСтановится персональным при надевании\n{Двуручное} {Дробящее}\n{Урон: 59-89 } {Скорость 3.50}\n(21.14 ед. урона в секунду)\n+12 к выносливости\nПрочность: 85 / 85\nТребуется 26-й ур.\nТребуется: Железный слиток (8), Сильный плавень (2), Тяжелый шлифовальный камень , Серебряный слиток (4), Толстая кожа (2)"},
[10878] = {name = "[q0]Monster - Sword, Horde Jagged Green", additional_info = "{Одноручное} {Меч}\n{Урон: 1-2 } {Скорость 2.00}\n(0.75 ед. урона в секунду)\nПрочность: 20 / 20"},
