[10918] = {name = "Нейтрализующий яд", additional_info = "Классы: Разбойник\nТребуется 32-й ур.\n[q2]Использование: Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, который на 55% снижает действие эффектов лечения на противнике в течение 15 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 60 раз (Вероятность срабатывания: 30%)"},
[10919] = {name = "[q2]Перчатки аптекаря", additional_info = "Становится персональным при поднятии\n{Кисти рук} {Ткань}\nБроня: 20\n+3 к интеллекту\n+2 к духу\nПрочность: 20 / 20"},
[10920] = {name = "Нейтрализующий яд II", additional_info = "Классы: Разбойник\nТребуется 40-й ур.\n[q2]Использование: Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, который на 75% снижает действие эффектов лечения на противнике в течение 15 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 75 раз. (Вероятность срабатывания: 30%)"},
[10921] = {name = "Нейтрализующий яд III", additional_info = "Классы: Разбойник\nТребуется 48-й ур.\n[q2]Использование: Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, который на 105% снижает действие эффектов лечения на противнике в течение 15 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 90 раз. (Вероятность срабатывания: 30%)"},
[10922] = {name = "Нейтрализующий яд IV", additional_info = "Классы: Разбойник\nТребуется 56-й ур.\n[q2]Использование: Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, который на 135% снижает действие эффектов лечения на противнике в течение 15 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 105 раз. (Вероятность срабатывания: 30%)"},
