[12105] = {name = "[q2]Славнокольчужные поножи", additional_info = "Становится персональным при поднятии\n{Ноги} {Кольчуга}\nБроня: 282\n+13 к духу\nПрочность: 75 / 75\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами сил природы, на 29 ед."},
[12106] = {name = "[q2]Кираса каменной кожи", additional_info = "Становится персональным при поднятии\n{Грудь} {Латы}\n[q2]Броня: 770\n+13 к силе\nПрочность: 115 / 115"},
