[17200] = {name = "Рецепт: имбирное печенье", additional_info = "Требует Кулинария (1)\n[q2]Использование: Обучение приготовлению имбирного печенья.\nИмбирное печенье\n[q2]Использование: Восполняет 61.2 ед. здоровья за 18 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 2 на 15 мин.\nТребуется: Небольшое яйцо , Праздничные пряности"},
[17201] = {name = "Рецепт: гоголь-моголь", additional_info = "Требует Кулинария (35)\n[q2]Использование: Обучение приготовлению гоголя-моголя.\nГоголь-моголь\n[q2]Использование: Восполняет 61.2 ед. здоровья за 18 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 2 на 15 мин. Сильное пойло...\nТребуется: Небольшое яйцо , Ледяное молоко , Праздничная выпивка , Праздничные пряности"},
[17202] = {name = "Снежок", additional_info = "[q2]Использование: Бросай меня!"},
[17203] = {name = "[q4]Сульфуронский слиток", additional_info = nil},
[17204] = {name = "[q5]Глаз Сульфураса", additional_info = "Становится персональным при поднятии\n[q2]Использование: Глаз Сульфураса можно соединить с сульфуронским молотом, чтобы создать Сульфурас, легендарный молот Рагнароса."},
[17222] = {name = "Паучья колбаска", additional_info = "Требуется 35-й ур.\n[q2]Использование: Восполняет 1392 ед. здоровья за 30 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 12 на 15 мин."},
[17223] = {name = "[q4]Громовой удар", additional_info = "Становится персональным при поднятии\n{Двуручное} {Древковое}\n{Урон: 147-221 } {Скорость 3.10}\n(59.35 ед. урона в секунду)\nПрочность: 120 / 120\nТребуется 58-й ур.\n[q2]Возможный эффект при попадании: Поражение целей числом до 3 с нанесением 150 в 250 ед. урона от сил природы. Каждая последующая цель получает все меньше урона.\n[q2]Использование: Преобразование Громового удара в Удар Тени. (1 Мин Восстановление)"},
[17224] = {name = "[q2]Прицел Видящих", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Используя заклинание одновременно с Магическим шаром, вы можете осмотреть крепость Альянса через глаз Рисона в небе."},
