[18251] = {name = "[q3]Накладки из кожи Недр", additional_info = "Требуется 50-й ур.\n[q2]Использование: Постоянное укрепление предмета одежды, носимого на груди, ногах, руках или ступнях на 3. Укрепить можно только предметы уровня 35 и выше."},
[18252] = {name = "[q3]Выкройка: накладки из кожи Недр", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (300)\n[q2]Использование: Обучение изготовлению накладок из кожи Недр.\n[q3]Накладки из кожи Недр\nТребуется 50-й ур.\n[q2]Использование: Постоянное укрепление предмета одежды, носимого на груди, ногах, руках или ступнях на 3. Укрепить можно только предметы уровня 35 и выше.\nТребуется: Сердцевинная кожа (3), Руническая нить (2)"},
[18253] = {name = "Сильнейшее зелье омоложения", additional_info = "Требуется 50-й ур.\n[q2]Использование: Восполнение 1440 в 1760 ед. здоровья и маны. (2 Мин Восстановление)"},
[18254] = {name = "Десерт из корня Рун-Тум", additional_info = "Требуется 45-й ур.\n[q2]Использование: Восполнение 1933.2 ед. здоровья за 27 сек. Действие эффекта прерывается, если персонаж встает с места. Дополнительное повышение интеллекта на 10 ед. на 10 мин."},
[18255] = {name = "Корень Рун-Тум", additional_info = "Требуется 45-й ур.\n[q2]Использование: Восполняет 1392 ед. здоровья за 30 сек. Действие прерывается, если встать с места."},
[18256] = {name = "Укрепленная колба", additional_info = nil},
[18257] = {name = "[q3]Рецепт: сильнейшее зелье омоложения", additional_info = "Требует Алхимия (300)\n[q2]Использование: Обучает приготовлению сильнейшего зелья омоложения.\nСильнейшее зелье омоложения\nТребуется 50-й ур.\n[q2]Использование: Восполнение 1440 в 1760 ед. здоровья и маны. (2 Мин Восстановление)\nТребуется: Сердце дикой природы , Золотой сансам (4), Снолист (4), Укрепленная колба"},
[18258] = {name = "[q2]Доспехи клана Гордок", additional_info = "Уникальный\nТребуется 55-й ур.\n[q2]Использование: Позволяет выдать себя за одного из огров из клана Гордок и даже обмануть капитана! Маскировка продержится 10 мин.\n[q]\"Утягивающий эффект и укрепление!\""},
[18259] = {name = "[q3]Формула чар для оружия: сила заклинаний I", additional_info = "Становится персональным при поднятии\nТребует Наложение чар (300)\n[q2]Использование: Обучение наложению на оружие чар, повышающих урон от заклинаний на 30 ед."},
[18260] = {name = "[q3]Формула чар для оружия: целительная сила", additional_info = "Становится персональным при поднятии\nТребует Наложение чар (300)\n[q2]Использование: Обучение наложению на оружие чар, увеличивающих эффект исцеляющих заклинаний не более чем на 55 ед."},
[18261] = {name = "Книга магических формул", additional_info = "Предмет, необходимый для задания"},
[18262] = {name = "[q2]Точильный камень стихий", additional_info = "Требуется 50-й ур.\n[q2]Использование: Повышение рейтинга критического удара оружием ближнего боя на 2% на 30 мин."},
[18263] = {name = "[q4]Напульсники с сияющей сердцевиной", additional_info = "Становится персональным при надевании\n{Запястья} {Ткань}\nБроня: 43\n+8 к интеллекту\nУстойчивость: +7 Огонь\nПрочность: 35 / 35\nТребуется 60-й ур.\n[q2]Если на персонаже: Восполнение 9 ед. маны раз в 5 сек."},
[18264] = {name = "[q3]Чертеж: точильный камень стихий", additional_info = "Становится персональным при поднятии\nТребует Кузнечное дело (300)\n[q2]Использование: Обучение изготовлению точильного камня стихий.\n[q2]Точильный камень стихий\nТребуется 50-й ур.\n[q2]Использование: Повышение рейтинга критического удара оружием ближнего боя на 2% на 30 мин.\nТребуется: Первородная земля (2), Массивный камень (3)"},
[18265] = {name = "[q3]Выкройка: напульсники с сияющей сердцевиной", additional_info = "Требует Портняжное дело (300)\n[q2]Использование: Обучение изготовлению напульсников с сияющей сердцевиной.\n[q4]Напульсники с сияющей сердцевиной\nСтановится персональным при надевании\n{Запястья} {Ткань}\nБроня: 43\n+8 к интеллекту\nУстойчивость: +7 Огонь\nПрочность: 35 / 35\nТребуется 60-й ур.\n[q2]Если на персонаже: Восполнение 9 ед. маны раз в 5 сек.\nТребуется: Луноткань (6), Огненное ядро (8), Субстанция Огня (2), Зачарованная кожа (6), Руническая нить (4)"},
[18266] = {name = "Ключ от внутреннего двора клана Гордок", additional_info = "Забытый Город\nСтановится персональным при поднятии\nУникальный"},
[18267] = {name = "[q2]Рецепт: десерт из корня Рун-Тум", additional_info = "Становится персональным при поднятии\nТребует Кулинария (275)\n[q2]Использование: Обучение приготовлению сюрприза кота Бегемота.\nДесерт из корня Рун-Тум\nТребуется 45-й ур.\n[q2]Использование: Восполнение 1933.2 ед. здоровья за 27 сек. Действие эффекта прерывается, если персонаж встает с места. Дополнительное повышение интеллекта на 10 ед. на 10 мин.\nТребуется: Корень Рун-Тум , Ароматные специи"},
[18268] = {name = "Ключ от внутренней двери клана Гордок", additional_info = "Забытый Город\nСтановится персональным при поднятии\nУникальный"},
[18269] = {name = "[q2]Зеленый грог клана Гордок", additional_info = "Становится персональным при поднятии\n[q2]Использование: Увеличивает выносливость на 10 в течение 15 мин. и делает вас в доску пьяным. Зеленый - значит хороший!"},
[18282] = {name = "[q4]Снайперская винтовка Центра", additional_info = "Становится персональным при надевании\n{Дальний бой} {Огнестрельное}\n{Урон: 64-120 } {Скорость 2.50}\n(36.80 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение силы атаки в дальнем бою на 22 ед.\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%."},
[18283] = {name = "[q3]Прицел \"Бизникс\" 247x128", additional_info = "Требуется 50-й ур.\n[q2]Использование: Оснащение лука или огнестрельного оружия прицелом, позволяющим повысить наносимый урон на 3 ед."},
[18284] = {name = "[q2]Убойное пойло Крига", additional_info = "Становится персональным при поднятии\n[q2]Использование: Повышение духа на 25 ед. и снижение интеллекта на 5 ед. на 15 мин. Вкууусно."},
