[18286] = {name = "[q0]Фрагмент сконцентрированной маны", additional_info = nil},
[18287] = {name = "Дурнопойло", additional_info = "[q2]Использование: Обычный алкогольный напиток.\n[q]\"Градус лучше понижать, чем повышать.\""},
[18288] = {name = "Огненная вода", additional_info = "[q2]Использование: Крепкий алкогольный напиток.\n[q]\"Не использовать вблизи открытого огня.\""},
[18289] = {name = "[q3]Ожерелье Острых Шипов", additional_info = "Становится персональным при надевании\nШея\n+7 к выносливости\n+6 к интеллекту\nТребуется 51-й ур.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами сил природы, на 17 ед."},
[18290] = {name = "[q3]Чертеж: прицел \"Бизникс\" 247x128", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (300)\n[q2]Использование: Обучение изготовлению прицела \"Бизникс\" 247x128.\n[q3]Прицел &quot;Бизникс&quot; 247x128\nТребуется 50-й ур.\n[q2]Использование: Оснащение лука или огнестрельного оружия прицелом, позволяющим повысить наносимый урон на 3 ед.\nТребуется: Ядро лавы (2), Субстанция Земли (2), Сверхточный арканитовый преобразователь (4), Слиток черного железа (6), Ториевая труба"},
[18291] = {name = "[q3]Чертеж: реактивный диск", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (300)\n[q2]Использование: Обучение изготовлению реагирущего на усиление диска.\n[q4]Реактивный диск\nСтановится персональным при надевании\n{Левая рука} {Щит}\n[q2]Броня: 2548\nБлокирование: 44\n+11 к выносливости\nПрочность: 120 / 120\nТребуется 60-й ур.\nТребует Инженерное дело (300)\n[q2]Если на персонаже: Приведенный в действие щит испускает электрический разряд, который наносит урон всем находящимся поблизости противникам. Есть также вероятность повредить щит. (Восстановление: 1с)\nТребуется: Арканитовый слиток (6), Сверхточный арканитовый преобразователь (2), Субстанция Воздуха (8), Субстанция Жизни (12), Субстанция Земли (8)"},
[18292] = {name = "[q3]Чертеж: снайперская винтовка Центра", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (300)\n[q2]Использование: Обучение изготовлению снайперской винтовки Центра.\n[q4]Снайперская винтовка Центра\nСтановится персональным при надевании\n{Дальний бой} {Огнестрельное}\n{Урон: 64-120 } {Скорость 2.50}\n(36.80 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение силы атаки в дальнем бою на 22 ед.\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%.\nТребуется: Огненное ядро (4), Ядро лавы (2), Арканитовый слиток (6), Сверхточный арканитовый преобразователь (2), Ториевая труба (2)"},
[18293] = {name = "[q0]Monster - Glaive - 2 Blade B03 Green", additional_info = "{Одноручное} {Топор}\n{Урон: 1-2 } {Скорость 2.00}\n(0.75 ед. урона в секунду)\nПрочность: 20 / 20"},
[18294] = {name = "Сильный эликсир водного дыхания", additional_info = "Требуется 35-й ур.\n[q2]Использование: Позволяет выпившему дышать под водой в течение 1 ч. (3 Сек Восстановление)"},
[18295] = {name = "[q3]Регулирующие сапоги", additional_info = "Становится персональным при надевании\n{Ступни} {Ткань}\nБроня: 54\n[q2]<Случайное зачарование>\n+6 к выносливости\n+6 к интеллекту\nПрочность: 40 / 40\nТребуется 50-й ур."},
[18296] = {name = "[q3]Поручи снайпера", additional_info = "Становится персональным при надевании\n{Запястья} {Кольчуга}\nБроня: 146\n+12 к ловкости\n+6 к выносливости\nПрочность: 40 / 40\nТребуется 51-й ур.\n[q2]Если на персонаже: Повышение навыка владения луком на +2.\n[q2]Если на персонаже: Увеличение рейтинга навыка владения арбалетом на 2.\n[q2]Если на персонаже: Повышение навыка использования огнестрельного оружия на 2 ед."},
[18297] = {name = "Семя колючечника", additional_info = "Становится персональным при поднятии\nТребуется 55-й ур.\n[q2]Использование: Высаживание колючечника, который привлечет ближайших противников. (15 Мин Восстановление)"},
