[18634] = {name = "[q3]Гирозамораживающий ледяной отражатель", additional_info = "Становится персональным при надевании\nАксессуар\nУстойчивость: +15 Лед\nТребуется 47-й ур.\nТребует Инженерное дело (260)\n[q2]Использование: Отражает заклинания, наносящие урон от магии льда, назад в заклинателя в течение 5 сек. (5 Мин Восстановление)"},
[18635] = {name = "Ореховая паста Беллары", additional_info = "Требуется 35-й ур.\n[q2]Использование: Восполняет 1392 ед. здоровья за 30 сек. Действие прерывается, если встать с места."},
[18636] = {name = "Испорченные кроссировочные кабели XL", additional_info = "[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[18637] = {name = "[q2]Большой атомарный перенаправлятор", additional_info = "Аксессуар\nТребует Инженерное дело (275)\n[q2]Использование: Снятие эффекта превращения с дружественной цели. Восполнение 375 в 625 ед. здоровья и маны. (5 Мин Восстановление)\n10 зарядов"},
[18638] = {name = "[q3]Гипер-излучающий отражатель пламени", additional_info = "Становится персональным при надевании\nАксессуар\nУстойчивость: +18 Огонь\nТребуется 53-й ур.\nТребует Инженерное дело (290)\n[q2]Использование: Отражает заклинания, наносящие урон от огня, назад в заклинателя в течение 5 сек. (5 Мин Восстановление)"},
[18639] = {name = "[q3]Ультра-вспышечный отражатель тьмы", additional_info = "Становится персональным при надевании\nАксессуар\nУстойчивость: +20 Тьма\nТребуется 55-й ур.\nТребует Инженерное дело (300)\n[q2]Использование: Отражает заклинания, наносящие урон от темной магии, назад в заклинателя в течение 5 сек. (5 Мин Восстановление)"},
[18640] = {name = "Веселый камень", additional_info = "Уникальный (4)\n[q2]Использование: Кинуть камень дружественному игроку. Если у него есть свободное место в сумке, он его поймает!"},
[18641] = {name = "Концентрированный динамит", additional_info = "Требует Инженерное дело (250)\n[q2]Использование: Нанесение 340 в 460 ед. урона от огня в радиусе 5 метров. (1 Мин Восстановление)"},
[18642] = {name = "Автограф Джайны", additional_info = "Предмет, необходимый для задания\nУникальный\n[q]\"Будь сильным Рандис, и добейся того, чего желаешь. - Леди Джайна Праудмур\""},
[18643] = {name = "Отпечаток копыта Кэрна", additional_info = "Предмет, необходимый для задания\nУникальный\n[q]\"Прислушайся к духам, юный Грент, здесь истинные герои могут услышать их зов. - Кэрн Кровавое Копыто.\""},
[18644] = {name = "[q0]Monster - Staff, Ornate Jeweled Staff - Red Low Red Flame", additional_info = "{Двуручное} {Посох}\n{Урон: 1-2 } {Скорость 2.00}\n(0.75 ед. урона в секунду)\nПрочность: 20 / 20"},
[18645] = {name = "Гномский тревого-бот", additional_info = "Требует Инженерное дело (265)\n[q2]Использование: Призывает тревого-бота на 10 мин. Робот пеленгует находящихся поблизости скрывающихся или невидимых противников. (10 Мин Восстановление)"},
[18646] = {name = "[q4]Око Божественности", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Жрец\nТребуется 60-й ур.\n[q]\"Взлядываясь в Око ты замечаешь какое-то движение.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[18647] = {name = "Чертеж: красная петарда", additional_info = "Требует Инженерное дело (150)\n[q2]Использование: Обучение изготовлению красного фейерверка.\nКрасная петарда\n[q2]Использование: Запуск фейерверка, который рассыпается тысячей красных звездочек.\nТребуется: Тяжелое взрывчатое вещество , Толстая кожа"},
[18648] = {name = "Чертеж: зеленая петарда", additional_info = "Требует Инженерное дело (150)\n[q2]Использование: Обучение изготовлению зеленого фейерверка.\nЗеленая петарда\n[q2]Использование: Запуск фейерверка, который рассыпается тысячей зеленых звездочек.\nТребуется: Тяжелое взрывчатое вещество , Толстая кожа"},
[18649] = {name = "Чертеж: голубая петарда", additional_info = "Требует Инженерное дело (150)\n[q2]Использование: Обучение изготовлению синего фейерверка.\nГолубая петарда\n[q2]Использование: Запуск фейерверка, который рассыпается тысячей синих звездочек.\nТребуется: Тяжелое взрывчатое вещество , Толстая кожа"},
[18650] = {name = "Чертеж: динамит \"Pro-100-брос II\"", additional_info = "Требует Инженерное дело (200)\n[q2]Использование: Обучение созданию EZ-Thro динамита II.\nДинамит &quot;Pro-100-брос II&quot;\nТребуется 30-й ур.\n[q2]Использование: Нанесение 213 в 287 ед. урона от огня в радиусе 5 метров. (Допуская, что оно попадет в цель, могут быть наложены ограничения.) (1 Мин Восстановление)\n[q]\"Динамит подходит для использования тем, кто не имеет инженерного образования, редко взрывается в руках, взрывная сила вдвое превосходит предыдущую версию.\"\nТребуется: Твердое взрывчатое вещество , Магическая ткань (2)"},
[18651] = {name = "Чертеж: преобразователь истинного серебра", additional_info = "Требует Инженерное дело (260)\n[q2]Использование: Обучает изготовлению преобразователя истинного серебра.\nПреобразователь истинного серебра\nТребуется: Слиток истинного серебра (2), Первородная земля (2), Первородный воздух"},
[18652] = {name = "Чертеж: гирозамораживающий ледяной отражатель", additional_info = "Требует Инженерное дело (260)\n[q2]Использование: Обучение изготовлению гирозамораживающего ледяного отражателя.\n[q3]Гирозамораживающий ледяной отражатель\nСтановится персональным при надевании\nАксессуар\nУстойчивость: +15 Лед\nТребуется 47-й ур.\nТребует Инженерное дело (260)\n[q2]Использование: Отражает заклинания, наносящие урон от магии льда, назад в заклинателя в течение 5 сек. (5 Мин Восстановление)\nТребуется: Ториевое устройство (6), Преобразователь истинного серебра (2), Синий сапфир (2), Субстанция Огня (4), Масло льда (2), Ледяной зев (4)"},
[18653] = {name = "[q2]Чертеж: гоблинский кабельный макси-дефибриллятор", additional_info = "Требует Инженерное дело (265)\nТребуется:Гоблинский механик\n[q2]Использование: Обучение изготовлению гоблинских кроссировочных кабелей XL.\nГоблинский кабельный макси-дефибриллятор\nАксессуар\nТребует Инженерное дело (265)\n[q2]Использование: Кабельный дефибриллятор - это шанс вернуть убитого игрока к жизни. В бою использовать нельзя. (30 Мин Восстановление)\nТребуется: Ториевое устройство (2), Преобразователь истинного серебра (2), Кабельная система с плавкими предохранителями (2), Железношелковая паутина (2), Звездный рубин (2)"},
[18654] = {name = "[q2]Чертеж: гномский тревого-бот", additional_info = "Требует Инженерное дело (265)\nТребуется:Гномский механик\n[q2]Использование: Обучение изготовлению тревого-бота.\nГномский тревого-бот\nТребует Инженерное дело (265)\n[q2]Использование: Призывает тревого-бота на 10 мин. Робот пеленгует находящихся поблизости скрывающихся или невидимых противников. (10 Мин Восстановление)\nТребуется: Ториевый слиток (4), Ториевое устройство (2), Грубая кожа (4), Звездный рубин , Кабельная система с плавкими предохранителями"},
[18655] = {name = "[q2]Чертеж: большой атомарный перенаправлятор", additional_info = "Требует Инженерное дело (275)\n[q2]Использование: Обучает изготовлению старшего перенаправлятора.\n[q2]Большой атомарный перенаправлятор\nАксессуар\nТребует Инженерное дело (275)\n[q2]Использование: Снятие эффекта превращения с дружественной цели. Восполнение 375 в 625 ед. здоровья и маны. (5 Мин Восстановление)\n10 зарядов\nТребуется: Ториевая труба (2), Преобразователь истинного серебра , Рунная ткань (2)"},
[18656] = {name = "Чертеж: мощный сефориевый заряд", additional_info = "Требует Инженерное дело (275)\n[q2]Использование: Обучение изготовлению мощного сефориевого заряда.\nМощный сефориевый заряд\nТребует Инженерное дело (275)\n[q2]Использование: Взрывает практически любые запертые двери.\nТребуется: Ториевое устройство (2), Концентрированное взрывчатое вещество (3), Грубая кожа (2), Освежающая ключевая вода"},
[18657] = {name = "[q2]Чертеж: гипер-излучающий отражатель пламени", additional_info = "Требует Инженерное дело (290)\n[q2]Использование: Обучение изготовлению отражателя огня широкого радиуса действия.\n[q3]Гипер-излучающий отражатель пламени\nСтановится персональным при надевании\nАксессуар\nУстойчивость: +18 Огонь\nТребуется 53-й ур.\nТребует Инженерное дело (290)\n[q2]Использование: Отражает заклинания, наносящие урон от огня, назад в заклинателя в течение 5 сек. (5 Мин Восстановление)\nТребуется: Слиток черного железа (4), Преобразователь истинного серебра (3), Субстанция Воды (6), Звездный рубин (4), Азеротский алмаз (2)"},
[18658] = {name = "[q2]Чертеж: ультра-вспышечный отражатель тьмы", additional_info = "Требует Инженерное дело (300)\n[q2]Использование: Обучение изготовлению ультра-вспышечного отражателя тьмы.\n[q3]Ультра-вспышечный отражатель тьмы\nСтановится персональным при надевании\nАксессуар\nУстойчивость: +20 Тьма\nТребуется 55-й ур.\nТребует Инженерное дело (300)\n[q2]Использование: Отражает заклинания, наносящие урон от темной магии, назад в заклинателя в течение 5 сек. (5 Мин Восстановление)\nТребуется: Слиток черного железа (8), Преобразователь истинного серебра (4), Субстанция Жизни (6), Субстанция Нежити (4), Азеротский алмаз (2), Большой опал (2)"},
[18659] = {name = "[q4]Расщепитель Нордрассила", additional_info = "Становится персональным при поднятии\nУникальный\nТребуется 60-й ур.\n[q2]Использование: В сочетании с Оком Тени и Глазом Божественности дает Благословение.\n[q]\"Маленький кусочек Древа Жизни.\""},
[18660] = {name = "[q2]Увеличитель мира", additional_info = "Требует Инженерное дело (250)\nТребуется:Гномский механик\n[q2]Использование: Увеличивает мир на 5 мин. до первой атаки. (1 Час Восстановление)\n[q]\"Только с помощью гномьих технологий можно произвести прибор, который воздействует на весь мир.\""},
[18661] = {name = "[q2]Чертеж: увеличитель мира", additional_info = "Требует Инженерное дело (260)\nТребуется:Гномский механик\n[q2]Использование: Обучение изготовлению увеличителя мира.\n[q2]Увеличитель мира\nТребует Инженерное дело (250)\nТребуется:Гномский механик\n[q2]Использование: Увеличивает мир на 5 мин. до первой атаки. (1 Час Восстановление)\n[q]\"Только с помощью гномьих технологий можно произвести прибор, который воздействует на весь мир.\"\nТребуется: Мифриловая обшивка , Ториевое устройство (2), Золотое силовое ядро , Нестабильное пусковое устройство , Цитрин"},
[18662] = {name = "Мяч из толстой кожи", additional_info = "Уникальный (10)\n[q2]Использование: Бросьте мяч в одного из дружественных игроков. Если у них есть свободное место в сумке, они его поймают!"},
[18663] = {name = "Флакон Д'жииви", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Освобождение беса Дж'ииви в центре пьедестала Бессмер'тера в Забытом Городе."},
[18664] = {name = "Трактат о военных рангах", additional_info = "[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[18665] = {name = "[q4]Око Тени", additional_info = "Становится персональным при надевании\nУникальный\nАксессуар\nТребуется 60-й ур.\n[q]\"В оке клубится тьма.\""},
[18666] = {name = "QAEnchant Weapon Crusader", additional_info = "[q2]Использование: Наложение на оружие ближнего боя чар, периодически восполняющих 75 в 125 ед. здоровья и повышающих силу на 100 ед. на 15 сек после совершения атаки."},
[18667] = {name = "QAEnchant Weapon Icy Chill", additional_info = "[q2]Использование: Наложение на оружие ближнего боя чар, периодически замораживающих противника и снижающих его скорость атак и передвижения."},
[18668] = {name = "QAEnchant Weapon Spell Power", additional_info = "[q2]Использование: Наложение на оружие ближнего боя чар, повышающих наносимый от заклинаний урон не более чем на 30 ед."},
[18669] = {name = "QAEnchant Weapon Healing Power", additional_info = "[q2]Использование: Наложение на оружие ближнего боя чар, увеличивающих исцеляющий эффект заклинаний на 55 ед."},
[18670] = {name = "Зоротианские письмена", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Вызов ксоротианского коня погибели в наделенном силой круге Темного Призывания."},
[18671] = {name = "[q3]Скипетр Барона Огнерра", additional_info = "Становится персональным при надевании\n{Правая рука} {Дробящее}\n{Урон: 70-132 } {Скорость 2.60}\n(38.85 ед. урона в секунду)\n+5 к силе\nПрочность: 90 / 90\nТребуется 54-й ур.\n[q2]Возможный эффект при попадании: Нанесение цели 35 ед. урона от огня."},
[18672] = {name = "[q2]Элементарный уголь", additional_info = "Становится персональным при надевании\nЛевая рука\n+10 к выносливости\nТребуется 54-й ур.\n[q2]Если на персонаже: Увеличение наносимого урона от заклинаний и эффектов огня не более чем на 13 ед."},
[18673] = {name = "[q3]Каменная шкура Лавиниона", additional_info = "Становится персональным при надевании\n{Левая рука} {Щит}\nБроня: 2026\nБлокирование: 37\n+16 к выносливости\nПрочность: 100 / 100\nТребуется 54-й ур.\n[q2]Если на персонаже: Увеличение показателя блока щитом на 10 ед."},
[18674] = {name = "[q2]Закаленное каменное кольцо", additional_info = "Становится персональным при надевании\nПалец\n+8 к силе\n+8 к выносливости\nТребуется 54-й ур.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 3 ед."},
[18675] = {name = "Табель о рангах Орды и Альянса", additional_info = "[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[18676] = {name = "[q3]Кушак Ветробоя", additional_info = "Становится персональным при надевании\n{Пояс} {Кольчуга}\nБроня: 202\n+6 к выносливости\n+7 к интеллекту\n+7 к духу\nПрочность: 40 / 40\nТребуется 56-й ур.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами сил природы, на 29 ед."},
[18677] = {name = "[q2]Зефирский плащ", additional_info = "Становится персональным при надевании\nСпина\nБроня: 39\nУстойчивость: +15 Природа\nТребуется 56-й ур."},
[18678] = {name = "[q3]Замерзшее ожерелье Темпестрии", additional_info = "Становится персональным при надевании\nШея\n+8 к выносливости\n+5 к интеллекту\nУстойчивость: +15 Лед\nТребуется 56-й ур."},
[18679] = {name = "[q2]Кольцо безразличия", additional_info = "Становится персональным при надевании\nПалец\n+10 к интеллекту\nТребуется 56-й ур.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами льда, на 14 ед."},
[18680] = {name = "[q3]Древний костяной лук", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Лук}\n{Урон: 61-114 } {Скорость 2.80}\n(31.25 ед. урона в секунду)\n+11 к ловкости\nПрочность: 75 / 75\nТребуется 56-й ур."},
[18681] = {name = "[q3]Погребальная наплечная накидка", additional_info = "Становится персональным при поднятии\n{Плечо} {Ткань}\nБроня: 65\n+16 к интеллекту\nПрочность: 50 / 50\nТребуется 56-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 20 ед."},
[18682] = {name = "[q3]Поножи из кожи вурдалака", additional_info = "Становится персональным при поднятии\n{Ноги} {Кожа}\nБроня: 150\n+20 к выносливости\n+8 к интеллекту\n+8 к духу\nПрочность: 75 / 75\nТребуется 56-й ур.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 44 ед."},
