[19287] = {name = "[q4]Карта Новолуния: Героизм", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nТребуется 60-й ур.\n[q2]Если на персонаже: Иногда носитель исцеляется от 120 в 180 ед. урона при нанесении урона противнику в ближнем бою."},
[19288] = {name = "[q4]Карта Новолуния: Синий Дракон", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение до 2% вероятности восполнять ману в процессе применения заклинаний в течение 15 сек. после успешного применения заклинания со скоростью, равной 100% от обычной скорости восполнения. (Вероятность срабатывания: 2%)"},
[19289] = {name = "[q4]Карта Новолуния: Мальстрим", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nТребуется 60-й ур.\n[q2]Если на персонаже: Вероятность поражения вашей цели в ближнем бою молнией с нанесением 200 в 300 ед. урона от сил природы."},
[19290] = {name = "[q4]Карта Новолуния: Круговерть Пустоты", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nТребуется 60-й ур.\n[q2]Если на персонаже: 10% шанс того, что носитель сможет воскреснуть с 20% здоровья и маны."},
[19291] = {name = "Ящик Новолуния", additional_info = "Уникальный\nСумка (ячеек: 14)"},
[19292] = {name = "Прошлогодний окорок", additional_info = "{Одноручное} {Дробящее}\n{Урон: 29-54 } {Скорость 2.50}\n(16.60 ед. урона в секунду)\nПрочность: 75 / 75\nТребуется 29-й ур."},
[19293] = {name = "Прошлогодний окорок", additional_info = "{Одноручное} {Дробящее}\n{Урон: 44-82 } {Скорость 2.00}\n(31.50 ед. урона в секунду)\nПрочность: 75 / 75\nТребуется 50-й ур."},
[19295] = {name = "Цветок Новолуния", additional_info = "Левая рука"},
[19296] = {name = "[q2]Большой приз Новолуния", additional_info = "Требуется 45-й ур.\n[q]\"Качество гарантированно.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[19297] = {name = "[q2]Малый приз Новолуния", additional_info = "Требуется 30-й ур.\n[q]\"Качество гарантированно.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[19298] = {name = "[q2]Поощрительный приз Новолуния", additional_info = "Требуется 15-й ур.\n[q]\"Качество гарантированно.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[19299] = {name = "Ярмарочная шипучка", additional_info = "Требуется 15-й ур.\n[q2]Использование: Восполнение 835.2 ед. маны за 24 сек. Действие эффекта прерывается, если персонаж встает с места."},
[19300] = {name = "Бутылка талой воды", additional_info = "Требуется 35-й ур.\n[q2]Использование: Восполнение 1992 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места."},
[19301] = {name = "Альтеракский бисквит из манны", additional_info = "Становится персональным при поднятии\nТребуется 51-й ур.\n[q2]Использование: Восполнение 4410 ед. здоровья и 4410 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места."},
[19302] = {name = "[q3]Кольцо Новолуния", additional_info = "Становится персональным при поднятии\nПалец\n+6 к выносливости\nТребуется 50-й ур.\n[q2]Если на персонаже: Восполняет 6 ед. здоровья каждые 5 сек."},
[19303] = {name = "[q3]Ожерелье Новолуния", additional_info = "Становится персональным при поднятии\nШея\n+6 к интеллекту\nТребуется 50-й ур.\n[q2]Если на персонаже: Восполнение 6 ед. маны раз в 5 сек."},
[19304] = {name = "Острая бастурма", additional_info = "Требуется 5-й ур.\n[q2]Использование: Восполняет 243.6 ед. здоровья за 21 сек. Действие прерывается, если встать с места."},
[19305] = {name = "Маринованная ножка кодо", additional_info = "Требуется 15-й ур.\n[q2]Использование: Восполняет 552 ед. здоровья за 24 сек. Действие прерывается, если встать с места."},
[19306] = {name = "Хрустящая лягушка", additional_info = "Требуется 35-й ур.\n[q2]Использование: Восполняет 1392 ед. здоровья за 30 сек. Действие прерывается, если встать с места."},
[19307] = {name = "Плотные альтеракские бинты из рунной ткани", additional_info = "Становится персональным при поднятии\nТребует Первая помощь (225)\n[q2]Использование: Восполнение 2000 ед. здоровья в течение 8 сек.\n[q]\"Нельзя использовать за пределами Альтеракской долины.\""},
[19308] = {name = "[q4]Фолиант Чародейской силы", additional_info = "Становится персональным при поднятии\nУникальный\nЛевая рука\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами тайной магии, на 34 ед.\n[q2]Если на персонаже: Восполнение 3 ед. маны раз в 5 сек."},
[19309] = {name = "[q4]Фолиант Силы тени", additional_info = "Становится персональным при поднятии\nУникальный\nЛевая рука\n+8 к выносливости\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами темной магии, на 34 ед."},
[19310] = {name = "[q4]Фолиант Ледяного лорда", additional_info = "Становится персональным при поднятии\nУникальный\nЛевая рука\n+9 к интеллекту\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами льда, на 34 ед."},
[19311] = {name = "[q4]Фолиант Огненных чар", additional_info = "Становится персональным при поднятии\nУникальный\nЛевая рука\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение наносимого урона от заклинаний и эффектов огня не более чем на 40 ед."},
[19312] = {name = "[q4]Гирлянда Жизнедателя", additional_info = "Становится персональным при поднятии\nУникальный\nЛевая рука\nТребуется 60-й ур.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 53 ед.\n[q2]Если на персонаже: Восполнение 3 ед. маны раз в 5 сек."},
[19315] = {name = "[q4]Касание Теразана", additional_info = "Становится персональным при поднятии\nУникальный\nЛевая рука\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 33 ед."},
[19316] = {name = "[q2]Пронизанная льдом стрела", additional_info = "Становится персональным при поднятии\n{Боеприпасы} {Стрелы}\nДобавляет 16.5 ед. урона в секунду\nТребуется 51-й ур."},
[19317] = {name = "[q2]Пронизанная льдом пуля", additional_info = "Становится персональным при поднятии\n{Боеприпасы} {Пули}\nДобавляет 16.5 ед. урона в секунду\nТребуется 51-й ур."},
[19318] = {name = "Бутыль воды из Альтерака", additional_info = "Становится персональным при поднятии\nТребуется 55-й ур.\n[q2]Использование: Восполнение 4410 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места. Дополнительное повышение духа на 10 ед. на 10 мин.\n[q]\"Вода горных ключей Альтеракской долины!\""},
[19319] = {name = "[q3]Колчан из шкуры гарпии", additional_info = "Становится персональным при поднятии\nУникальный\nКолчан (ячеек: 16)\nТребуется 55-й ур.\n[q2]Если на персонаже: Увеличение скорости дальней атаки на 15%."},
[19320] = {name = "[q3]Нагрудный патронташ из кожи гнолла", additional_info = "Становится персональным при поднятии\nУникальный\nПодсумок (ячеек: 16)\nТребуется 55-й ур.\n[q2]Если на персонаже: Увеличение скорости дальней атаки на 15%."},
[19321] = {name = "[q4]Недвижимый объект", additional_info = "Становится персональным при поднятии\nУникальный\n{Левая рука} {Щит}\nБроня: 2468\nБлокирование: 44\n+15 к выносливости\nПрочность: 120 / 120\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение показателя блока щитом на 27 ед."},
[19322] = {name = "[q2]Почетный знак Песни Войны", additional_info = "Становится персональным при поднятии\nУникальный (10)\n[q]\"Знак за победу в Ущелье Песни Войны.\""},
[19323] = {name = "[q4]Непреодолимая сила", additional_info = "Становится персональным при поднятии\nУникальный\n{Двуручное} {Дробящее}\n{Урон: 175-292 } {Скорость 3.80}\n(61.45 ед. урона в секунду)\n+19 к силе\n+15 к выносливости\nПрочность: 120 / 120\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 2%.\n[q2]Возможный эффект при попадании: Оглушение цели на 1 сек."},
[19324] = {name = "[q4]Трепанатор", additional_info = "Становится персональным при поднятии\nУникальный\n{Одноручное} {Кинжал}\n{Урон: 59-111 } {Скорость 1.80}\n(47.22 ед. урона в секунду)\nПрочность: 75 / 75\nТребуется 60-й ур.\n[q2]Возможный эффект при попадании: Ранение цели, наносящее 200 в 300 ед. урона и снижающее ее интеллект на 25 ед. на 30 сек."},
[19325] = {name = "[q4]Кольцо дона Хулио", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\n+11 к выносливости\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%.\n[q2]Если на персонаже: Увеличивает силу атаки на 16."},
[19326] = {name = "Выкройка: мощь Древобрюхов", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (290)\nТребуется: Уважение (Древобрюхи\n)\n[q2]Использование: Обучение изготовлению мощи Древобрюхов.\n[q3]Мощь Древобрюхов\nСтановится персональным при надевании\n{Пояс} {Кожа}\nБроня: 93\n+21 к силе\n+9 к выносливости\nПрочность: 35 / 35\nТребуется 53-й ур.\nТребуется: Грубая кожа (30), Мощный амулет (2), Субстанция Жизни (4), Обработанная грубая шкура (2), Руническая нить (2)"},
[19327] = {name = "Выкройка: боевые перчатки Древобрюхов", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (300)\nТребуется: Почтение (Древобрюхи\n)\n[q2]Использование: Обучение изготовлению боевых перчаток Древобрюхов.\n[q3]Боевые перчатки Древобрюхов\nСтановится персональным при надевании\n{Кисти рук} {Кожа}\nБроня: 112\n+23 к силе\n+10 к выносливости\nПрочность: 35 / 35\nТребуется 59-й ур.\nТребуется: Зачарованная кожа (8), Мощный амулет (6), Субстанция Жизни (6), Обработанная грубая шкура (2), Железношелковая паутина (2)"},
[19328] = {name = "Выкройка: рассветные ботфорты", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (290)\nТребуется: Уважение (Серебряный Рассвет\n)\n[q2]Использование: Обучение изготовлению рассветных вибрамов.\n[q3]Рассветные ботфорты\nСтановится персональным при надевании\n{Ступни} {Кожа}\nБроня: 114\n+18 к выносливости\nПрочность: 50 / 50\nТребуется 53-й ур.\n[q2]Если на персонаже: Увеличение рейтинга уклонения на 1%.\nТребуется: Грубая кожа (30), Охранный камень (2), Субстанция Воды (4), Обработанная грубая шкура (2), Руническая нить (2)"},
[19329] = {name = "Выкройка: золотое оплечье Рассвета", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (300)\nТребуется: Почтение (Серебряный Рассвет\n)\n[q2]Использование: Обучение изготовлению золотого оплечья Рассвета.\n[q3]Золотое оплечье Рассвета\nСтановится персональным при надевании\n{Плечо} {Кожа}\nБроня: 134\n+22 к выносливости\nПрочность: 60 / 60\nТребуется 59-й ур.\n[q2]Если на персонаже: Увеличение рейтинга уклонения на 1%.\nТребуется: Зачарованная кожа (8), Субстанция Жизни (4), Охранный камень (4), Обработанная грубая шкура (2), Руническая нить (2)"},
[19330] = {name = "Выкройка: лавовый пояс", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (300)\n[q2]Использование: Обучение изготовлению лавового пояса.\n[q4]Лавовый пояс\nСтановится персональным при надевании\n{Пояс} {Кожа}\n[q2]Броня: 223\n+15 к выносливости\nУстойчивость: +26 Огонь\nПрочность: 40 / 40\nТребуется 60-й ур.\nТребуется: Ядро лавы (5), Обработанная грубая шкура (4), Железношелковая паутина (4)"},
[19331] = {name = "Выкройка: разноцветные рукавицы", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (300)\nТребуется: Кожевничество: чешуя драконов\n[q2]Использование: Обучение изготовлению разноцветных рукавиц.\n[q4]Разноцветные рукавицы\nСтановится персональным при надевании\n{Кисти рук} {Кольчуга}\nБроня: 279\nУстойчивость: +5 Огонь\nУстойчивость: +5 Природа\nУстойчивость: +5 Лед\nУстойчивость: +5 Тьма\nПрочность: 50 / 50\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 44.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%.\nТребуется: Огненное ядро (5), Ядро лавы (2), Сердцевинная кожа (4), Сверкающая многоцветная чешуя (4), Обработанная грубая шкура (4), Железношелковая паутина (4)"},
[19332] = {name = "Выкройка: пояс пса Недр", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (300)\nТребуется: Кожевничество: традиции предков\n[q2]Использование: Обучение изготовлению пояса пса Недр.\n[q4]Пояс пса Недр\nСтановится персональным при надевании\n{Пояс} {Кожа}\nБроня: 118\n+16 к интеллекту\nУстойчивость: +12 Огонь\nПрочность: 40 / 40\nТребуется 60-й ур.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 62 ед.\nТребуется: Огненное ядро (8), Сердцевинная кожа (12), Зачарованная кожа (10), Обработанная грубая шкура (4), Железношелковая паутина (4)"},
[19333] = {name = "Выкройка: оплавленный пояс", additional_info = "Становится персональным при поднятии\nТребует Кожевничество (300)\nТребуется: Кожевничество: сила стихий\n[q2]Использование: Обучение изготовлению оплавленного пояса.\n[q4]Оплавленный пояс\nСтановится персональным при надевании\n{Пояс} {Кожа}\nБроня: 118\n+28 к ловкости\n+16 к выносливости\nУстойчивость: +12 Огонь\nПрочность: 40 / 40\nТребуется 60-й ур.\nТребуется: Огненное ядро (2), Ядро лавы (7), Субстанция Земли (6), Обработанная грубая шкура (4), Железношелковая паутина (4)"},
[19334] = {name = "[q4]Неукротимый клинок", additional_info = "Становится персональным при поднятии\n{Двуручное} {Меч}\n{Урон: 192-289 } {Скорость 3.40}\n(70.74 ед. урона в секунду)\n+22 к ловкости\n+16 к выносливости\nПрочность: 120 / 120\nТребуется 60-й ур.\n[q2]Возможный эффект при попадании: Увеличивает силу на 300 ед. на 8 сек."},
[19335] = {name = "[q4]Хребтодробитель", additional_info = "Становится персональным при поднятии\nУникальный\n{Правая рука} {Дробящее}\n{Урон: 99-184 } {Скорость 2.60}\n(54.42 ед. урона в секунду)\n+9 к силе\n+16 к выносливости\nПрочность: 105 / 105\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 5 ед."},
[19336] = {name = "[q4]Наделенный чародейством самоцвет", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Охотник\nТребуется 60-й ур.\n[q2]Использование: Наполнение Тайной энергией, заставляющей ваш следующий \"Чародейский выстрел\", примененный в течение последующих 10 сек., взрываться при попадании в цель. \"Грохот Чар\" наносит 185 в 215 ед. урона противникам поблизости от цели. (2 Мин Восстановление)"},
[19337] = {name = "[q4]Черная книга", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Чернокнижник\nТребуется 60-й ур.\n[q2]Использование: Увеличивает урон прислужника на 100% и усиливает его броню на 100% на 30 сек. Действует только на беса, суккуба, инкуба, демона Бездны и охотника Скверны. (5 Мин Восстановление)"},
[19338] = {name = "Бесплатное поручительство", additional_info = "Предмет, необходимый для задания\nУникальный"},
[19339] = {name = "[q4]Дар Стремительной Мысли", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Маг\nТребуется 60-й ур.\n[q2]Использование: Ускорение способности соображать. Скорость применения заклинаний повышается на 33% в течение 20 сек. (5 Мин Восстановление)"},
[19340] = {name = "[q4]Руна Метаморфозы", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Друид\nТребуется 60-й ур.\n[q2]Использование: Снижение расхода маны для изменений облика друида на 100% на 20 сек. (5 Мин Восстановление)"},
[19341] = {name = "[q4]Животворный камень", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Воин\nТребуется 60-й ур.\n[q2]Использование: Восстанавливает вам 15% от вашего максимального запаса здоровья и увеличивает ваш максимальный запас здоровья на 15% на 20 сек. (5 Мин Восстановление)"},
[19342] = {name = "[q4]Ядовитый тотем", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Разбойник\nТребуется 60-й ур.\n[q2]Использование: Повышает вероятность применения к цели яда на 30% на 20 сек. (5 Мин Восстановление)"},
[19343] = {name = "[q4]Свитки Слепящего Света", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Паладин\nТребуется 60-й ур.\n[q2]Использование: Наделяет паладина энергией света, которая повышает скорость в ближнем бою на 25%, а скорость произнесения заклинаний – на 33% на 20 сек. (5 Мин Восстановление)"},
[19344] = {name = "[q4]Кристалл Природного Управления", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Шаман\nТребуется 60-й ур.\n[q2]Использование: Повышение урона от заклинаний на 20% и улучшение целительства на 20%, повышение расхода маны на заклинания на 20% в течение 20 сек. (5 Мин Восстановление)"},
[19345] = {name = "[q4]Эгида Сохранения", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nКлассы: Жрец\nТребуется 60-й ур.\n[q2]Использование: Усиление брони на 500 ед., восполнение 35 ед. здоровья каждый раз, когда вам наносится урон в ближнем или дальнем бою. Время действия – 20 сек. (5 Мин Восстановление)"},
[19346] = {name = "[q4]Клинок Драконьего клыка", additional_info = "Становится персональным при поднятии\nУникальный\n{Одноручное} {Кинжал}\n{Урон: 69-130 } {Скорость 1.80}\n(55.28 ед. урона в секунду)\n+16 к ловкости\n+13 к выносливости\nПрочность: 75 / 75\nТребуется 60-й ур."},
[19347] = {name = "[q4]Коготь Хроммагуса", additional_info = "Становится персональным при поднятии\nУникальный\n{Одноручное} {Кинжал}\n{Урон: 37-90 } {Скорость 1.50}\n(42.33 ед. урона в секунду)\n+7 к выносливости\n+17 к интеллекту\nПрочность: 75 / 75\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 64 ед.\n[q2]Если на персонаже: Восполнение 4 ед. маны раз в 5 сек."},
