[19989] = {name = "[q3]Фолиант Пожирающих теней", additional_info = "Становится персональным при поднятии\nЛевая рука\nУстойчивость: +6 Природа\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами темной магии, на 20 ед.\n[q]\"Некоторых тайн лучше не касаться.\""},
[19990] = {name = "[q3]Благословенные четки", additional_info = "Становится персональным при поднятии\nАксессуар\n[q2]Использование: Увеличение исцеления, производимого заклинаниями и эффектами на 190 ед. на 20 сек. (2 Мин Восстановление)\n[q]\"Друг в беде, - друг без четок.\""},
[19991] = {name = "[q3]Глаз девизавра", additional_info = "Становится персональным при поднятии\nАксессуар\n[q2]Использование: Сила атаки повышена на 150, а шанс нанести удар – на 2%. Время действия эффекта – 20 сек. (2 Мин Восстановление)"},
[19992] = {name = "[q3]Зуб девизавра", additional_info = "Становится персональным при поднятии\nАксессуар\n[q2]Использование: Если следующая атака питомца может нанести критическое поражение, то она непременно его нанесет. (2 Мин Восстановление)"},
[19993] = {name = "[q3]Охотничий лук худу", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Лук}\n{Урон: 68-128 } {Скорость 2.80}\n(35.00 ед. урона в секунду)\n+10 к ловкости\n+4 к выносливости\nПрочность: 75 / 75\nТребуется 60-й ур."},
[19994] = {name = "Фрукты с праздника урожая", additional_info = "Становится персональным при поднятии\nУникальный (20)\n[q2]Использование: Восполнение 2% здоровья в сек. в течение 25 сек. Действие эффекта прерывается, если персонаж встает с места."},
[19995] = {name = "Мясо вепря с праздника урожая", additional_info = "Становится персональным при поднятии\nУникальный (20)\n[q2]Использование: Восполнение 2% здоровья в сек. в течение 25 сек. Действие эффекта прерывается, если персонаж встает с места."},
[19996] = {name = "Рыба с праздника урожая", additional_info = "Становится персональным при поднятии\nУникальный (20)\n[q2]Использование: Восполнение 2% здоровья в сек. в течение 25 сек. Действие эффекта прерывается, если персонаж встает с места."},
[19997] = {name = "Нектар с праздника урожая", additional_info = "Становится персональным при поднятии\nУникальный (20)\n[q2]Использование: Восполнение 2% маны в сек. в течение 30 сек. Действие эффекта прерывается, если персонаж встает с места."},
[19998] = {name = "[q3]Линза Кровавой Лозы", additional_info = "Становится персональным при надевании\n{Голова} {Кожа}\nБроня: 147\n+12 к выносливости\nПрочность: 60 / 60\nТребуется 60-й ур.\nТребует Инженерное дело (300)\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 2%.\n[q2]Если на персонаже: Небольшое повышение вашей способности \"Обнаружение незаметности\"."},
[19999] = {name = "[q3]Очки Кровавой Лозы", additional_info = "Становится персональным при надевании\n{Голова} {Ткань}\nБроня: 75\nПрочность: 50 / 50\nТребуется 60-й ур.\nТребует Инженерное дело (300)\n[q2]Если на персонаже: Повышение на 2% рейтинга меткости заклинаний.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%.\n[q2]Если на персонаже: Восполнение 9 ед. маны раз в 5 сек."},
[20000] = {name = "Чертеж: очки Кровавой Лозы", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (300)\nТребуется: Уважение (Племя Зандалар\n)\n[q2]Использование: Обучение изготовлению очков Кровавой Лозы.\n[q3]Очки Кровавой Лозы\nСтановится персональным при надевании\n{Голова} {Ткань}\nБроня: 75\nПрочность: 50 / 50\nТребуется 60-й ур.\nТребует Инженерное дело (300)\n[q2]Если на персонаже: Повышение на 2% рейтинга меткости заклинаний.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%.\n[q2]Если на персонаже: Восполнение 9 ед. маны раз в 5 сек.\nТребуется: Кровавая лоза (4), Свет Души (5), Сверхточный арканитовый преобразователь (2), Мощный амулет (8), Зачарованная кожа (4)"},
[20001] = {name = "Чертеж: линза Кровавой Лозы", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (300)\nТребуется: Дружелюбие (Племя Зандалар\n)\n[q2]Использование: Обучение изготовлению линзы Кровавой Лозы.\n[q3]Линза Кровавой Лозы\nСтановится персональным при надевании\n{Голова} {Кожа}\nБроня: 147\n+12 к выносливости\nПрочность: 60 / 60\nТребуется 60-й ур.\nТребует Инженерное дело (300)\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 2%.\n[q2]Если на персонаже: Небольшое повышение вашей способности \"Обнаружение незаметности\".\nТребуется: Кровавая лоза (5), Свет Души (5), Сверхточный арканитовый преобразователь , Мощный амулет (8), Зачарованная кожа (4)"},
[20002] = {name = "Сильное зелье спокойного сна", additional_info = "Требуется 55-й ур.\n[q2]Использование: Погружение в сон без сновидений на 12 сек. За это время выпивший восполняет 2100 ед. здоровья и 2100 ед. маны. (2 Мин Восстановление)"},
[20003] = {name = "[q3]Когти девизавра", additional_info = "Становится персональным при поднятии\n{Правая рука} {Кистевое оружие}\n{Урон: 48-90 } {Скорость 2.00}\n(34.50 ед. урона в секунду)\n+4 к ловкости\nПрочность: 65 / 65\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%.\n[q]\"Когти просто вибрируют от переполняющей их энергии.\""},
[20004] = {name = "Сильнейшее зелье тролльей крови", additional_info = "Требуется 53-й ур.\n[q2]Использование: Восполнение 20 ед. здоровья раз в 5 сек. в течение 1 ч. (3 Сек Восстановление)"},
[20005] = {name = "[q3]Когти девизавра", additional_info = "Становится персональным при поднятии\n{Левая рука} {Кистевое оружие}\n{Урон: 48-90 } {Скорость 2.00}\n(34.50 ед. урона в секунду)\n+4 к ловкости\nПрочность: 65 / 65\n[q2]Если на персонаже: Повышение рейтинга навыка владения кистевым оружием на 4 ед.\n[q]\"Когти просто вибрируют от переполняющей их энергии.\""},
[20006] = {name = "[q3]Обруч Надежды", additional_info = "Становится персональным при поднятии\nПалец\nУстойчивость: +6 Тьма\n[q2]Если на персонаже: Повышает вероятность критического эффекта ваших заклинаний светлой магии на 1%.\n[q]\"Выкован из чистого света.\""},
[20007] = {name = "Зелье крови волшебника", additional_info = "Требуется 40-й ур.\n[q2]Использование: Восполнение 12 ед. маны каждые 5 сек. в течение 1 ч. (3 Сек Восстановление)"},
[20008] = {name = "Зелье неудержимости", additional_info = "Требуется 47-й ур.\n[q2]Использование: Неуязвимость к эффектам оглушения и стеснения движений на ближайшие 5 сек. Удаление уже наложенных эффектов оглушения и стеснения передвижения. (2 Мин Восстановление)"},
[20009] = {name = "Во имя Света!", additional_info = "[q]\"Написано Женром Певцом Знаний. Посвящается Утеру Светоносному.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[20010] = {name = "Адский крик Орды", additional_info = "[q]\"Написано Толвеном из клана Песни Войны. Посвящается Грому Адскому Крику.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[20011] = {name = "Рецепт: зелье крови волшебника", additional_info = "Становится персональным при поднятии\nТребует Алхимия (275)\nТребуется: Почтение (Племя Зандалар\n)\n[q2]Использование: Обучение приготовлению зелья крови волшебника.\nЗелье крови волшебника\nТребуется 40-й ур.\n[q2]Использование: Восполнение 12 ед. маны каждые 5 сек. в течение 1 ч. (3 Сек Восстановление)\nТребуется: Снолист , Чумоцвет (2), Хрустальная колба"},
[20012] = {name = "Рецепт: сильное зелье спокойного сна", additional_info = "Становится персональным при поднятии\nТребует Алхимия (275)\nТребуется: Дружелюбие (Племя Зандалар\n)\n[q2]Использование: Обучает приготовлению сильного зелья спокойного сна.\nСильное зелье спокойного сна\nТребуется 55-й ур.\n[q2]Использование: Погружение в сон без сновидений на 12 сек. За это время выпивший восполняет 2100 ед. здоровья и 2100 ед. маны. (2 Мин Восстановление)\nТребуется: Снолист (2), Золотой сансам , Хрустальная колба"},
[20013] = {name = "Рецепт: зелье неудержимости", additional_info = "Становится персональным при поднятии\nТребует Алхимия (285)\nТребуется: Превознесение (Племя Зандалар\n)\n[q2]Использование: Обучение приготовлению зелья актерства.\nЗелье неудержимости\nТребуется 47-й ур.\n[q2]Использование: Неуязвимость к эффектам оглушения и стеснения движений на ближайшие 5 сек. Удаление уже наложенных эффектов оглушения и стеснения передвижения. (2 Мин Восстановление)\nТребуется: Ледяной зев (2), Горный серебряный шалфей (2), Сердце дикой природы (2), Хрустальная колба"},
[20014] = {name = "Рецепт: сильнейшее зелье тролльей крови", additional_info = "Становится персональным при поднятии\nТребует Алхимия (290)\nТребуется: Уважение (Племя Зандалар\n)\n[q2]Использование: Обучает приготовлению сильнейшего зелья тролльей крови.\nСильнейшее зелье тролльей крови\nТребуется 53-й ур.\n[q2]Использование: Восполнение 20 ед. здоровья раз в 5 сек. в течение 1 ч. (3 Сек Восстановление)\nТребуется: Кровь Грома , Чумоцвет (2), Хрустальная колба"},
