[20542] = {name = "Свиток: создание скипетра Власти", additional_info = "[q2]Использование: Соедините с жезлами истинного серебра в количестве 1 шт. и изначальным воздухом в количестве 20 для создания скипетра призыва: Гром."},
[20543] = {name = "Свиток: создание скипетра Власти", additional_info = "[q2]Использование: Соединить с жезлами истинного серебра в количестве 1 шт. и массивными камнями в количестве 20 для создания скипетра призыва: Камень."},
[20544] = {name = "Свиток: создание скипетра Власти", additional_info = "[q2]Использование: Соединить с жезлами истинного серебра в количестве 1 шт. и заколдованной водой в количестве 20 для создания скипетра призыва: Вода."},
