[20620] = {name = "Священный камень силы", additional_info = "Становится персональным при поднятии\n[q2]Использование: Раскалывание священного Камня Мощи, с дарованием 300 ед. силы атаки и увеличением урона от заклинаний и эффектов светлой магии на 400 в сражениях с нежитью. Время действия – 10 мин."},
