[21178] = {name = "[q3]Перчатки Силы Земли", additional_info = "Становится персональным при поднятии\n{Кисти рук} {Кожа}\nБроня: 109\n+9 к интеллекту\nПрочность: 35 / 35\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 27 ед."},
[21179] = {name = "[q3]Кольцо Гнева Земли", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\n+8 к интеллекту\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%.\n[q2]Если на персонаже: Восполнение 3 ед. маны раз в 5 сек."},
[21180] = {name = "[q4]Земной удар", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\n[q2]Использование: Увеличение силы атаки ближнего и дальнего боя на 280 ед. на 20 сек. (2 Мин Восстановление)"},
[21181] = {name = "[q3]Благодать Земли", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\n[q2]Использование: Снижение вашей угрозы вражеским целям в радиусе 30 м., что уменьшает вероятность нападения на вас. (5 Мин Восстановление)"},
[21182] = {name = "[q3]Кольцо Мощи Земли", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\n+6 к силе\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%."},
[21183] = {name = "[q3]Жилет Силы земли", additional_info = "Становится персональным при поднятии\n{Грудь} {Ткань}\nБроня: 93\n+22 к интеллекту\nПрочность: 80 / 80\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 25 ед."},
[21184] = {name = "[q4]Глубокоскальные наручи", additional_info = "Становится персональным при поднятии\n{Запястья} {Латы}\nБроня: 309\n+19 к силе\n+10 к ловкости\n+8 к выносливости\nПрочность: 55 / 55"},
[21185] = {name = "[q4]Сфера Спокойствия земли", additional_info = "Становится персональным при поднятии\nЛевая рука\n+10 к интеллекту\n[q2]Если на персонаже: Восполнение 8 ед. маны раз в 5 сек.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 18 ед."},
[21186] = {name = "[q4]Наручи Скальной Ярости", additional_info = "Становится персональным при поднятии\n{Запястья} {Ткань}\nБроня: 42\n+7 к выносливости\nПрочность: 35 / 35\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 27 ед.\n[q2]Если на персонаже: Повышение на 1% рейтинга меткости заклинаний."},
[21187] = {name = "[q3]Землетканный плащ", additional_info = "Становится персональным при поднятии\nСпина\nБроня: 44\n+15 к ловкости\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%."},
[21188] = {name = "[q4]Боевая перчатка Кенария", additional_info = "Становится персональным при поднятии\n{Двуручное} {Дробящее}\n{Урон: 175-263 } {Скорость 3.50}\n(62.57 ед. урона в секунду)\nПрочность: 120 / 120\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 40 ед.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 2%."},
[21189] = {name = "[q4]Мощь Кенария", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\n+8 к выносливости\n[q2]Если на персонаже: +4 ед. урона от оружия.\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%."},
[21190] = {name = "[q4]Гнев Кенария", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\n[q2]Если на персонаже: При успешной атаке вашим боевым заклинанием вы получаете шанс увеличить урон ото всех заклинаний и эффектов на 132 ед. на 10 сек. (Вероятность срабатывания: 5%)"},
[21191] = {name = "Тщательно упакованный подарок", additional_info = "Становится персональным при поднятии\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
