[22046] = {name = "Правая часть амулета Лорда Вальтхалака", additional_info = "Предмет, необходимый для задания\nУникальный\n[q2]Использование: Воссоединение левой, правой и верхней частей амулета Лорда Вальтхалака.\n[q]\"Часть амулета явственно вибрирует, желая воссоединиться с остальными\""},
[22047] = {name = "Верхняя часть амулета Лорда Вальтхалака", additional_info = "Предмет, необходимый для задания\nУникальный\n[q2]Использование: Воссоединение левой, правой и верхней частей амулета Лорда Вальтхалака.\n[q]\"При прикосновении к этой вещи появляется неприятное ощущение, как будто заключенное в ней зло стремится вырваться наружу.\""},
[22048] = {name = "Амулет Лорда Вальтхалака", additional_info = "Предмет, необходимый для задания\nУникальный\n[q2]Использование: Цельтесь по телу Лорда Вальтхалака, чтобы выдворить его дух из амулета.\n[q]\"Собранный воедино, амулет пульсирует от силы Лорда Вальтхалака.\""},
