[22191] = {name = "[q4]Обсидиановый кольчужный мундир", additional_info = "Становится персональным при надевании\n{Грудь} {Кольчуга}\nБроня: 458\nПрочность: 140 / 140\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 76.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Получаемый урон от заклинаний снижается на 10 ед."},
[22192] = {name = "Эликсир наложения чар", additional_info = "Становится персональным при поднятии\n[q2]Использование: Повышение рейтинга уклонения на 3% на 30 мин."},
[22193] = {name = "Эликсир устойчивости", additional_info = "Становится персональным при поднятии\n[q2]Использование: Увеличивает сопротивляемость всем магическим воздействиям на 15 ед. на 30 мин."},
[22194] = {name = "[q4]Черный напоясник Разрушителя", additional_info = "Становится персональным при надевании\n{Кисти рук} {Кольчуга}\nБроня: 279\nПрочность: 50 / 50\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 28.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Восполнение 8 ед. маны и дополнительное похищение 8 ед. маны у противника при ее наличии после успешной атаки ближнего или дальнего боя."},
[22195] = {name = "[q3]Легкий обсидиановый пояс", additional_info = "Становится персональным при надевании\n{Пояс} {Кольчуга}\nБроня: 224\nПрочность: 40 / 40\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 32.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: +5 ко всем видам сопротивления."},
[22196] = {name = "[q4]Толстая обсидиановая кираса", additional_info = "Становится персональным при надевании\n{Грудь} {Латы}\nБроня: 814\n+38 к силе\n+16 к выносливости\nПрочность: 165 / 165\nТребуется 60-й ур.\n[q2]Если на персонаже: При поражении непериодическим заклинанием урона вы получаете вероятность 30% создать 6 сек щит заклятий, который поглотит 300 в 500 ед. этой школы магии. (Вероятность срабатывания: 30%, Восстановление: 10с)"},
[22197] = {name = "[q3]Тяжелый обсидиановый пояс", additional_info = "Становится персональным при надевании\n{Пояс} {Латы}\nБроня: 397\n+25 к силе\nПрочность: 45 / 45\nТребуется 60-й ур.\n[q2]Если на персонаже: +5 ко всем видам сопротивления."},
[22198] = {name = "[q4]Звездчатый обсидиановый щит", additional_info = "Становится персональным при надевании\n{Левая рука} {Щит}\nБроня: 2645\nБлокирование: 48\nПрочность: 120 / 120\nТребуется 60-й ур.\n[q2]Если на персонаже: Повышает вероятность блокирования атаки щитом на 2%,\n[q2]Если на персонаже: +5 ко всем видам сопротивления.\n[q2]Если на персонаже: При нанесении урона заклинанием, заклинатель с вероятностью 5% онемеет на 3 сек. (Вероятность срабатывания: 5%, Восстановление: 20с)"},
[22199] = {name = "[q0]Monster - Axe, 2H Arcanite Reaper", additional_info = "{Двуручное} {Топор}\n{Урон: 2-4 } {Скорость 3.30}\n(0.91 ед. урона в секунду)\nПрочность: 20 / 20"},
[22200] = {name = "Стрела с серебряным древком", additional_info = "Становится персональным при поднятии\nДлительность: 10 дн.\n[q2]Использование: Выстрелите в игрока, и его отыщет Кви К. Мелкошустр! (Сработает, только если у игрока нет текущего небоевого питомца)"},
[22201] = {name = "Реликварий Чистоты", additional_info = "Предмет, необходимый для задания\nУникальный"},
