[22203] = {name = "Большой обсидиановый осколок", additional_info = nil},
[22204] = {name = "[q3]Накулачники Известности", additional_info = "Становится персональным при поднятии\n{Запястья} {Кожа}\nБроня: 74\n+9 к силе\n+10 к ловкости\n+10 к выносливости\nПрочность: 35 / 35\nТребуется 55-й ур."},
[22205] = {name = "[q3]Черные стальные наручники", additional_info = "Становится персональным при поднятии\n{Запястья} {Латы}\nБроня: 261\n+10 к силе\n+7 к ловкости\n+10 к выносливости\nПрочность: 45 / 45\nТребуется 52-й ур."},
[22206] = {name = "[q2]Букет красных роз", additional_info = "Становится персональным при поднятии\nУникальный\nЛевая рука\n[q2]Использование: Осыпание находящейся поблизости цели каскадом розовых лепестков! (5 Мин Восстановление)"},
[22207] = {name = "[q3]Кушак великой охоты", additional_info = "Становится персональным при поднятии\n{Пояс} {Кольчуга}\nБроня: 199\n+15 к ловкости\n+14 к выносливости\n+6 к интеллекту\nПрочность: 40 / 40\nТребуется 55-й ур.\n[q2]Если на персонаже: Повышение навыка владения луком на +2.\n[q2]Если на персонаже: Повышение навыка использования огнестрельного оружия на 2 ед.\n[q2]Если на персонаже: Увеличение рейтинга навыка владения арбалетом на 2."},
[22208] = {name = "[q3]Лавовый молот", additional_info = "Становится персональным при поднятии\n{Двуручное} {Дробящее}\n{Урон: 135-203 } {Скорость 3.40}\n(49.71 ед. урона в секунду)\n+10 к силе\n+14 к выносливости\n+12 к интеллекту\nПрочность: 100 / 100\nТребуется 53-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 20 ед."},
[22209] = {name = "Чертеж: тяжелый обсидиановый пояс", additional_info = "Становится персональным при поднятии\nТребует Кузнечное дело (300)\nТребуется: Дружелюбие (Круг Кенария\n)\n[q2]Использование: Обучение изготовлению тяжелого обсидианового пояса.\n[q3]Тяжелый обсидиановый пояс\nСтановится персональным при надевании\n{Пояс} {Латы}\nБроня: 397\n+25 к силе\nПрочность: 45 / 45\nТребуется 60-й ур.\n[q2]Если на персонаже: +5 ко всем видам сопротивления.\nТребуется: Небольшой обсидиановый осколок (14), Зачарованный ториевый слиток (4), Субстанция Земли (2)"},
[22210] = {name = "[q0]Monster - Knuckle, B01 Red", additional_info = "{Одноручное} {Кистевое оружие}\n{Урон: 1 } {Скорость 1.50}\n(0.67 ед. урона в секунду)\nПрочность: 16 / 16"},
[22211] = {name = "[q0]Monster - Knuckle, B01 Red Offhand", additional_info = "{Левая рука} {Кистевое оружие}\n{Урон: 1 } {Скорость 1.50}\n(0.67 ед. урона в секунду)\nПрочность: 16 / 16"},
[22212] = {name = "[q3]Наплечье размером на голема", additional_info = "Становится персональным при поднятии\n{Плечо} {Кольчуга}\nБроня: 250\n+13 к ловкости\n+17 к выносливости\nПрочность: 70 / 70\nТребуется 51-й ур."},
[22213] = {name = "[q0]Monster - Mace, Hand of Edward the Odd", additional_info = "{Одноручное} {Дробящее}\n{Урон: 1-2 } {Скорость 2.00}\n(0.75 ед. урона в секунду)\nПрочность: 20 / 20"},
[22214] = {name = "Чертеж: легкий обсидиановый пояс", additional_info = "Становится персональным при поднятии\nТребует Кузнечное дело (300)\nТребуется: Уважение (Круг Кенария\n)\n[q2]Использование: Обучение изготовлению легкого обсидианового пояса.\n[q3]Легкий обсидиановый пояс\nСтановится персональным при надевании\n{Пояс} {Кольчуга}\nБроня: 224\nПрочность: 40 / 40\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 32.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: +5 ко всем видам сопротивления.\nТребуется: Небольшой обсидиановый осколок (14), Зачарованная кожа (4)"},
[22215] = {name = "[q0]Monster - Dagger, Bonescraper", additional_info = "{Одноручное} {Кинжал}\n{Урон: 1 } {Скорость 1.50}\n(0.67 ед. урона в секунду)\nПрочность: 16 / 16"},
[22216] = {name = "Ядовитая железа Веноксиса", additional_info = "Предмет, необходимый для задания"},
[22217] = {name = "Ядовитая железа Куриннакса", additional_info = "Предмет, необходимый для задания"},
[22218] = {name = "Горсть розовых лепестков", additional_info = "Длительность: 10 дн.\n[q2]Использование: Осыпание находящейся поблизости цели каскадом розовых лепестков! (30 Сек Восстановление)"},
[22219] = {name = "Чертеж: звездчатый обсидиановый щит", additional_info = "Становится персональным при поднятии\nТребует Кузнечное дело (300)\nТребуется: Почтение (Круг Кенария\n)\n[q2]Использование: Обучение изготовлению зазубренного обсидианового щит.\n[q4]Звездчатый обсидиановый щит\nСтановится персональным при надевании\n{Левая рука} {Щит}\nБроня: 2645\nБлокирование: 48\nПрочность: 120 / 120\nТребуется 60-й ур.\n[q2]Если на персонаже: Повышает вероятность блокирования атаки щитом на 2%,\n[q2]Если на персонаже: +5 ко всем видам сопротивления.\n[q2]Если на персонаже: При нанесении урона заклинанием, заклинатель с вероятностью 5% онемеет на 3 сек. (Вероятность срабатывания: 5%, Восстановление: 20с)\nТребуется: Большой обсидиановый осколок (8), Небольшой обсидиановый осколок (24), Зачарованный ториевый слиток (8), Субстанция Земли (4)"},
[22220] = {name = "[q3]Чертеж: Черный напоясник Разрушителя", additional_info = "Требует Кузнечное дело (300)\n[q2]Использование: Обучение изготовлению Черного напоясника Разрушителя.\n[q4]Черный напоясник Разрушителя\nСтановится персональным при надевании\n{Кисти рук} {Кольчуга}\nБроня: 279\nПрочность: 50 / 50\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 28.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Восполнение 8 ед. маны и дополнительное похищение 8 ед. маны у противника при ее наличии после успешной атаки ближнего или дальнего боя.\nТребуется: Большой обсидиановый осколок (8), Небольшой обсидиановый осколок (24), Зачарованная кожа (8), Настой великой силы"},
[22221] = {name = "Чертеж: обсидиановый кольчужный мундир", additional_info = "Становится персональным при поднятии\nТребует Кузнечное дело (300)\nТребуется: Превознесение (Круг Кенария\n)\n[q2]Использование: Обучение изготовлению обсидианового кольчужного мундира.\n[q4]Обсидиановый кольчужный мундир\nСтановится персональным при надевании\n{Грудь} {Кольчуга}\nБроня: 458\nПрочность: 140 / 140\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 76.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Получаемый урон от заклинаний снижается на 10 ед.\nТребуется: Большой обсидиановый осколок (15), Небольшой обсидиановый осколок (36), Зачарованная кожа (12), Охранный камень (10), Азеротский алмаз (4)"},
[22222] = {name = "[q3]Чертеж: толстая обсидиановая кираса", additional_info = "Требует Кузнечное дело (300)\n[q2]Использование: Обучение изготовлению толстой обсидиановой кирасы.\n[q4]Толстая обсидиановая кираса\nСтановится персональным при надевании\n{Грудь} {Латы}\nБроня: 814\n+38 к силе\n+16 к выносливости\nПрочность: 165 / 165\nТребуется 60-й ур.\n[q2]Если на персонаже: При поражении непериодическим заклинанием урона вы получаете вероятность 30% создать 6 сек щит заклятий, который поглотит 300 в 500 ед. этой школы магии. (Вероятность срабатывания: 30%, Восстановление: 10с)\nТребуется: Большой обсидиановый осколок (18), Небольшой обсидиановый осколок (40), Зачарованный ториевый слиток (12), Субстанция Земли (10), Огромный изумруд (4)"},
[22223] = {name = "[q3]Шлем старшины", additional_info = "Становится персональным при поднятии\n{Голова} {Латы}\nБроня: 469\n+15 к силе\n+14 к выносливости\n+11 к интеллекту\nПрочность: 80 / 80\nТребуется 50-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 13 ед."},
[22224] = {name = "Сущность язвительного призрака", additional_info = "Предмет, необходимый для задания"},
[22225] = {name = "[q3]Клобук из драконьей кожи", additional_info = "Становится персональным при поднятии\n{Голова} {Ткань}\nБроня: 69\n[q2]<Случайное зачарование>\n+12 к выносливости\n+15 к интеллекту\nПрочность: 50 / 50\nТребуется 55-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 18 ед."},
[22226] = {name = "Останки друидов", additional_info = "Предмет, необходимый для задания\n[q]\"От тела бойца Круга Кенария стараниями силитидов осталось немного.\""},
[22227] = {name = "Реликвия Деревни Звездного Ветра", additional_info = "Предмет, необходимый для задания\n[q]\"Эта реликвия ночных эльфов была заморожена великанами ледяного молота. Обращаться бережно.\""},
