[22231] = {name = "[q3]Кайзеровы сапоги Верности", additional_info = "Становится персональным при поднятии\n{Ступни} {Ткань}\nБроня: 60\n+11 к выносливости\n+18 к интеллекту\nПрочность: 40 / 40\nТребуется 56-й ур.\n[q2]Если на персонаже: Повышение на 1% рейтинга меткости заклинаний."},
[22232] = {name = "[q3]Ремень снайпера", additional_info = "Становится персональным при поднятии\n{Пояс} {Кольчуга}\nБроня: 202\n+21 к ловкости\nПрочность: 40 / 40\nТребуется 56-й ур.\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%."},
[22233] = {name = "[q2]Сундучок Зигриса", additional_info = "Становится персональным при поднятии\nУникальный\nСумка (ячеек: 16)\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
