[23172] = {name = "Refreshing Red Apple", additional_info = "Становится персональным при поднятии\n[q2]Использование: Restores 4% of your health and mana per second for 25 сек. Must remain seated while eating.\n[q]\"The perfect snack on a warm summer day.\""},
[23173] = {name = "[q3]Поножи из кожи поганища", additional_info = "Становится персональным при поднятии\n{Ноги} {Ткань}\nБроня: 37\n+7 к выносливости\n+8 к интеллекту\nПрочность: 60 / 60\nТребуется 20-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 9 ед."},
