[23663] = {name = "[q4]Ремень неистовства стихий", additional_info = "Становится персональным при поднятии\n{Пояс} {Кольчуга}\nБроня: 301\n+20 к выносливости\n+21 к интеллекту\nПрочность: 50 / 50\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 29 ед.\n[q2]Если на персонаже: Восполнение 5 ед. маны раз в 5 сек."},
[23664] = {name = "[q4]Наплечье неистовства стихий", additional_info = "Становится персональным при поднятии\n{Плечо} {Кольчуга}\nБроня: 401\n+19 к выносливости\n+21 к интеллекту\nПрочность: 85 / 85\nКлассы: Шаман\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 26 ед.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%.\n[q2]Если на персонаже: Повышение на 1% рейтинга меткости заклинаний."},
[23665] = {name = "[q4]Поножи неистовства стихий", additional_info = "Становится персональным при поднятии\n{Ноги} {Кольчуга}\nБроня: 468\n+26 к выносливости\n+27 к интеллекту\nПрочность: 105 / 105\nКлассы: Шаман\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 32 ед.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 2%."},
[23666] = {name = "[q4]Пояс верховного рыцаря", additional_info = "Становится персональным при поднятии\n{Пояс} {Латы}\nБроня: 536\n+18 к силе\n+18 к выносливости\n+18 к интеллекту\nПрочность: 55 / 55\nКлассы: Паладин\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 21 ед.\n[q2]Если на персонаже: Восполнение 7 ед. маны раз в 5 сек."},
[23667] = {name = "[q4]Наплеч верховного рыцаря", additional_info = "Становится персональным при поднятии\n{Плечо} {Латы}\nБроня: 714\n+18 к силе\n+18 к выносливости\n+17 к интеллекту\nПрочность: 100 / 100\nКлассы: Паладин\nТребуется 60-й ур.\n[q2]Если на персонаже: Восполнение 4 ед. маны раз в 5 сек.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 20 ед."},
[23668] = {name = "[q4]Поножи верховного рыцаря", additional_info = "Становится персональным при поднятии\n{Ноги} {Латы}\nБроня: 833\n+21 к силе\n+21 к выносливости\n+21 к интеллекту\nПрочность: 120 / 120\nКлассы: Паладин\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 26 ед.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 2%."},
[23683] = {name = "Пастилка от кашля из кристальных пластинок", additional_info = "Требуется 45-й ур.\n[q2]Использование: Восполняет 450 в 750 ед. здоровья. (2 Мин Восстановление)"},
[23684] = {name = "Бинты Хрустального дара", additional_info = "Требует Первая помощь (225)\n[q2]Использование: Восполнение 2500 ед. здоровья в течение 10 сек."},
[23689] = {name = "Учебник: бинты Хрустального дара", additional_info = "Становится персональным при поднятии\nТребует Первая помощь (300)\n[q2]Использование: Обучение созданию бинтов хрустального дара.\nБинты Хрустального дара\nТребует Первая помощь (225)\n[q2]Использование: Восполнение 2500 ед. здоровья в течение 10 сек.\nТребуется: [PH] Silithus PvP Dust [DEP] , Рунная ткань (10)"},
[23690] = {name = "Рецепт: кристальная пастилка от кашля", additional_info = "Становится персональным при поднятии\nУникальный\nТребует Кулинария (300)\n[q2]Использование: Обучает приготовлению кристальной пастилки от кашля.\nПастилка от кашля из кристальных пластинок\nТребуется 45-й ур.\n[q2]Использование: Восполняет 450 в 750 ед. здоровья. (2 Мин Восстановление)\nТребуется: [PH] Silithus PvP Dust [DEP] , Глубокоскальная соль"},
[23705] = {name = "[q4]Гербовая накидка Пламени", additional_info = "Становится персональным при поднятии\nУникальный\nГербовая накидка"},
[23709] = {name = "Гербовая накидка Льда", additional_info = "Становится персональным при поднятии\nУникальный\nГербовая накидка"},
[23710] = {name = "Верхнепалубная гербовая накидка #3", additional_info = "Становится персональным при поднятии\nУникальный\nГербовая накидка"},
[23712] = {name = "Белый тигренок", additional_info = "Становится персональным при поднятии\n[q2]Использование: Призыв и освобождение котенка белого тигра по щелчку правой кнопкой мыши."},
[23713] = {name = "Детеныш гиппогрифа", additional_info = "Становится персональным при поднятии\n[q2]Использование: Вызов или освобождение детеныша гиппогрифа по щелчку правой кнопкой мыши."},
[23714] = {name = "Непрерывный лиловый фейрверк", additional_info = "Становится персональным при поднятии\nАксессуар\n[q2]Использование: Запуск фейерверка, который рассыпается тысячей пурпурных звездочек. (10 Мин Восстановление)"},
[23715] = {name = "Вечный коктейль \"Легкое дыхание\"", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Увеличение выносливости на 25 ед.\n[q]\"100% первоклассное \"Легкое дыхание\" - свежевыжатое.\""},
[23716] = {name = "Резной огрский идол", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\n[q2]Использование: Станьте громадным лиловым огром на 10 мин! (1 Час Восстановление)"},
[23718] = {name = "Вечная настойка Скорпока", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Увеличение ловкости на 25 ед."},
[23719] = {name = "Вечный эликсир Мозгового штурма", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Повышение интеллекта на 25 ед. при использовании.\n[q]\"Подавать охлажденным.\""},
[23720] = {name = "Ездовая черепаха", additional_info = "Становится персональным при поднятии\nСредство передвижения\nРасы: Человек , Орк , Дворф , Ночной эльф , Нежить , Таурен , Гном , Тролль\nТребуется 20-й ур.\n[q2]Использование: Призыв и освобождение верховой черепахи. Может, она и небыстро ползает, но хоть пешком не идти! (3 Сек Восстановление)"},
[23721] = {name = "Вечное зелье из потрошков", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Поднятие духа на 25 ед.\n[q]\"С клубничным вкусом\""},
[23722] = {name = "Вечная С.И.Л.А.", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Увеличение силы на 25 ед.\n[q]\"Сильнодействующий Истинный Ликер Атлетизации.\""},
[23725] = {name = "QAEnchant Fiery Weapon", additional_info = "[q2]Использование: Наложение на оружие ближнего боя чар, увеличивающих наносимый урон большинства атак на 40 ед. урона от огня."},
[23727] = {name = "QAEnchant Gloves +5 Fishing", additional_info = "Использование: Наложение на перчатки чар, повышающих навык \"Рыбная ловля\" на 2 ед."},
[23728] = {name = "QAEnchant Gloves Riding Skill", additional_info = "[q2]Использование: Наложение на перчатки чар, несколько повышающих скорость передвижения верхом."},
[23743] = {name = "[q0]Monster - Sword 1H - Widow's Remorse", additional_info = "Становится персональным при поднятии\nУникальный\n{Одноручное} {Меч}\n{Урон: 1-2 } {Скорость 2.00}\n(0.75 ед. урона в секунду)\nПрочность: 20 / 20"},
[23794] = {name = "[q2]Вечный Блеск Занзы", additional_info = "Становится персональным при поднятии\nУникальный\nТребуется 55-й ур.\n[q2]Использование: Увеличение вероятности отражение враждебных заклинаний на 3% на 2 ч. Первое боевое заклинание отражается по умолчанию. Одновременно можно применять только одно зелье Занзы.\n[q]\"Благословлено силой Занзы!\""},
[23795] = {name = "[q2]Вечный Дух Занзы", additional_info = "Становится персональным при поднятии\nУникальный\nТребуется 55-й ур.\n[q2]Использование: Повышение духа игрока на 50 ед. и выносливости на 50 ед. на 2 ч. Одновременно можно применять только одно зелье Занзы.\n[q]\"Благословлено силой Занзы!\""},
[23796] = {name = "[q2]Вечная Скорость Занзы", additional_info = "Становится персональным при поднятии\nУникальный\nТребуется 55-й ур.\n[q2]Использование: Повышение скорости игрока на 20% на 2 ч. Одновременно можно применять только одно зелье Занзы.\n[q]\"Благословлено силой Занзы!\""},
[24071] = {name = "[q3]Облегченный кинжал", additional_info = "{Одноручное} {Кинжал}\n{Урон: 82 } {Скорость 1.80}\n(45.56 ед. урона в секунду)\nПрочность: 65 / 65\n[q]\"Для внутреннего использования.\""},
