[180089] = {name = "Ошейник панды", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Щелкните ПКМ, чтобы призвать или отпустить детеныша панды."},
[184937] = {name = "Темпоральный манипулятор", additional_info = "[q2]Использование: Искажает пространство-время, временно отключая полезные глобальные эффекты клича Драконоборца, Зул'Гуруба, Забытого Города и Оскверненного леса. (1 Час Восстановление)"},
