[190186] = {name = "Деревянная статуэтка", additional_info = "Предмет, необходимый для задания\nУникальный\n[q2]Использование: Призывает инкуба с помощью специального круга. (3 Мин Восстановление)\n[q]\"На подставке надпись: \"Я вернулся\".\""},
[190187] = {name = "Истлевший платок", additional_info = "Предмет, необходимый для задания\nУникальный\n[q2]Использование: Призывает инкуба с помощью специального круга. (3 Мин Восстановление)\n[q]\"На ткани вышиты изящные узоры и надпись \"М+К\".\""},
[190232] = {name = "Истлевший платок", additional_info = "Предмет, необходимый для задания\nУникальный\n[q]\"На ткани вышиты изящные узоры и надпись \"М+К\".\""},
[190307] = {name = "Незажженный факел", additional_info = "Сотворенный предмет\nПредмет, необходимый для задания\nУникальный\n[q]\"Знаешь, что бы смотрелось на этом факеле лучше всего? Пламя.\""},
[190308] = {name = "Горящий факел", additional_info = "Сотворенный предмет\nПредмет, необходимый для задания\nУникальный\nДлительность: 5 мин\n[q2]Использование: Бросить факел в указанное место, чтобы зажечь огонь.\n[q]\"Полезная штука, если надо устроить пожар для отвлечения внимания!\""},
