[191204] = {name = "[q2]Малый камень смерти", additional_info = "Становится персональным при поднятии\n[q2]Использование: Превращение 100 малых камней смерти в большой камень смерти."},
[191249] = {name = "[q2]Большой камень смерти", additional_info = "Становится персональным при поднятии\n[q]\"Яркий зеленый камень, излучающий невероятную энергию.\""},
[191267] = {name = "[q2]Руна телепортации: Вестибюль", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Перемещает вас в Вестибюль Наксарамаса."},
[191268] = {name = "[q2]Сфера порчи", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Разбивает сферу, увеличивая количество малых камней смерти, добываемых у прислужников Кел'Тузада, на 50% на 30 мин."},
[191272] = {name = "[q3]Жезл некромантии", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Подавляет волю нежити в Наксарамасе, подчиняя цель на 5 мин.\n3 зарядов"},
[191280] = {name = "[q3]Скопление грибных спор", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Ваши наносящие урон способности могут призвать спору, после смерти дающую ближайшим игрокам эффект \"Плеснецвет\". Время действия – 1 ч.\n\nПлеснецвет \n150 ед. урона от сил природы раз в 1 сек. Вероятность критического удара в ближнем и дальнем бою и критического эффекта заклинаний повышена на 15%. (Вероятность срабатывания: 10%, Восстановление: 15с)"},
[191288] = {name = "[q4]Руна телепортации: логово ледяного змея", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Перемещает вас в логово ледяного змея в Наксарамасе."},
[191292] = {name = "[q3]Ритуальный кинжал", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Поглощает жизненную силу целей вокруг вас, повышая выносливость на 3 за каждую пораженную цель. Эффект суммируется до 40 раз и действует в течение 1 ч."},
[191312] = {name = "[q4]Безотказная филактерия", additional_info = "Становится персональным при поднятии\nУникальный\nДлительность: 7 дн.Аксессуар\nТребуется 60-й ур.\n[q2]Если на персонаже: Блокирует атаку, которая могла бы вас убить. Когда этот эффект срабатывает, вы получаете невосприимчивость к урону на 3 сек., а филактерия разрушается."},
[191313] = {name = "Маска смерти", additional_info = "Длительность: 7 дн.\n[q2]Использование: Превращает в одного из обитателей Наксарамаса."},
[191414] = {name = "[q3]Костяной артефакт", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Пленяет душу цели, наделяя вас положительным эффектом. Время действия – 1 ч."},
[191458] = {name = "[q0]Разбитая филактерия", additional_info = "Становится персональным при поднятии\nУникальный\nДлительность: 7 дн.Аксессуар\nТребуется 60-й ур.\n[q]\"Тусклая и бесполезная.\""},
[191459] = {name = "[q4]Руна удачи", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Усиливает Кел'Тузада и командиров его армии энергией некромантии, увеличивая их запас здоровья и урон. За победу над усиленными противниками даются дополнительные награды.\n\n Эффект суммируется и действует всю неделю."},
[191477] = {name = "[q4]Костяная коновязь", additional_info = "Становится персональным при поднятии\nУникальный\nДлительность: 7 дн.\nТребуется 60-й ур.\n[q2]Использование: Призывает костяную коновязь.\n\n Участники группы могут воспользоваться ею, чтобы получить скелета-скакуна."},
[191480] = {name = "[q4]Скакун-скелет", additional_info = "Становится персональным при поднятии\nУникальный\nДлительность: 1 час\nСредство передвижения\nТребуется 40-й ур.\n[q2]Использование: Позволяет призывать и отпускать скакуна-скелета. Он верно служит тому, кто его призвал, и позволяет ездить верхом в Наксрамасе. Когда призывателя атакуют, скакун-скелет убегает в страхе. (3 Сек Восстановление)"},
[191481] = {name = "[q4]Гербовая накидка мастерства", additional_info = "Становится персональным при поднятии\nГербовая накидка\n[q]\"Свидетельство мастерства.\""},
[191550] = {name = "Книга камней смерти: маска смерти", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти маску смерти.\""},
[191605] = {name = "[q2]Книга камней смерти: руна телепортации I", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти руну телепортации.\""},
[191606] = {name = "[q2]Книга камней смерти: сфера порчи", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти сферу порчи.\""},
[191607] = {name = "[q3]Книга камней смерти: костяной артефакт", additional_info = "Становится персональным при поднятии\nУникальный\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти костяной артефакт.\""},
[191608] = {name = "[q3]Книга камней смерти: жезл некроманта", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти жезл некромантии.\""},
[191609] = {name = "[q3]Книга камней смерти: скопление спор грибов", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти скопление грибных спор.\""},
[191610] = {name = "[q3]Книга камней смерти: ритуальный кинжал", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти ритуальный кинжал.\""},
[191611] = {name = "[q4]Книга камней смерти: безотказная филактерия", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти безотказную филактерию.\""},
[191612] = {name = "[q4]Книга камней смерти: руна телепортации II", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти руну телепортации.\""},
[191613] = {name = "[q4]Книга камней смерти: руна удачи", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти руну удачи.\""},
[191614] = {name = "[q4]Книга камней смерти: костяная коновязь", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти костяную коновязь.\""},
[191656] = {name = "[q4]Сущность смерти", additional_info = "Становится персональным при поднятии\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[191660] = {name = "[q3]Молнии Таддиуса", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Прикрепляет к вашей шее наполненные силой грома болты, случайным образом наделяя положительным или отрицательным зарядом, увеличивающим урон и силу исцеления на 1%.\n\n Эффект суммируется рядом с игроками с таким же зарядом и наносит урон от сил природы игрокам с противоположным зарядом."},
[191661] = {name = "[q3]Чудовищный паучий клык", additional_info = "Становится персональным при поднятии\nДлительность: 7 дн.\n[q2]Использование: Вы пронзаете себя клыком, повышая скорость атаки, передвижения и применения заклинаний на 15% на 1 ч. (Вероятность срабатывания: 5%, Восстановление: 30с)"},
[191664] = {name = "[q3]Книга камней смерти: молнии Таддиуса", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти молнии Таддиуса.\""},
[191666] = {name = "[q3]Книга камней смерти: огромное паучье жвало", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Книга с описанием ритуала, позволяющего изготовить из камней смерти чудовищный паучий клык.\""},
[202251] = {name = "Мешочек угощений для питомцев", additional_info = "Становится персональным при поднятии\n[q2]Использование: Вы открываете мешочек с угощениями и подкладываете их цели в карман, увеличивая получаемый урон от животных на 20. (1 Мин Восстановление)"},
[202254] = {name = "[q3]Наручи перенаправления", additional_info = "Становится персональным при надевании\n{Запястья} {Кожа}\nБроня: 44\n+11 к выносливости\n+13 к интеллекту\n+8 к духу\nПрочность: 35 / 35\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%."},
[202256] = {name = "[q2]Изысканная пистоль капера", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Огнестрельное}\n{Урон: 6-13 } {Скорость 1.90}\n(5.00 ед. урона в секунду)\nПрочность: 35 / 35\nКлассы: Разбойник\n[q2]Если на персонаже: Вы получаете способность \"Быстрая реакция\":\n\n\nВы достаете оружие и быстро стреляете в противника, нанося обычный урон от оружия дальнего боя и снижая скорость передвижения на 50% на 6 сек. Продлевает серию приемов на 1.\n\n \"Быстрая реакция\" взаимодействует с теми же талантами и эффектами, что и \"Коварный удар\"."},
[202641] = {name = "Запачканный грязью блокнот", additional_info = "Становится персональным при поднятии\nЭтот предмет позволяет получить задание.\nКлассы: Разбойник\n[q]\"Этот блокнот покрыт грязью, но внутри изображены руны, а также есть записка на каком-то жаргоне.\""},
[203723] = {name = "Записка Катти", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q]\"Записка на воровском жаргоне\"\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[203726] = {name = "[q2]Руна Катти", additional_info = "Классы: Разбойник"},
[203745] = {name = "[q2]Заметки о заклинаниях: ледяное копье", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\nТребуетГравировка\n(1)\n[q2]Выгравировать на перчатках руну \"Ледяное копье\":\n\n\nНаносит противнику [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 55 / 100 * ( 1 ) ]-[(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 65 / 100 * ( 1 ) ] ед. урона от магии льда. Замороженные цели получают 400% урона.\n\n Когда другие ваши заклинания магии льда наносят урон целям, не контролируемым игроками, следующее \"Ледяное копье\" наносит этим целям на 20% больше урона. Суммируется до 5 раз. Для срабатывания этого эффекта требуется талант \"Зимняя стужа\".\n[q]\"Обучает новой способности вырезания рун.\""},
[203746] = {name = "[q2]Заметки о заклинаниях: живой жар", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\nТребуетГравировка\n(1)\n[q2]Выгравировать на поножах руну \"Живой жар\":\n\nПризывает чародейское пламя, которое движется к цели и оставляет за собой след зачарованного огня, наносящий окружающим противникам [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 100 / 100] ед. урона от чар огня. Действует в течение 10 сек.\n[q]\"Обучает новой способности вырезания рун.\""},
[203747] = {name = "[q2]Заметки о заклинаниях: ледяные пальцы", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\nТребуетГравировка\n(1)\n[q2]Выгравировать на нагруднике или мантии руну \"Ледяные пальцы\":\n\n\nПрименяя к целям эффект окоченения, вы с вероятностью 25% можете получить эффект \"Ледяные пальцы\". Пока он действует, 2 ваших следующих заклинания сработают:ваших следующих заклинаний сработают так, словно цель заморожена. Время действия – 15 сек.\n[q]\"Обучает новой способности вырезания рун.\""},
[203748] = {name = "[q2]Заметки о заклинании: выгорание", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Выгравировать на нагруднике руну \"Выгорание\":\n\n\nУвеличивает вероятность критического урона заклинаний на 15%. Когда ваши наносящие прямой урон заклинания наносят критический удар, они расходуют еще 1% вашего базового запаса маны.\n[q]\"Обучает новой способности гравировки.\""},
[203749] = {name = "[q2]Заметки о заклинании: просветление", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Выгравировать на нагруднике или мантии руну \"Просветление\":\n\n\nВы наносите на 10% больше урона, пока уровень маны выше 70%. При уровне маны ниже 30% она продолжает восстанавливаться во время применения заклинаний со скоростью 10% от обычной.\n[q]\"Обучает новой способности гравировки.\""},
[203750] = {name = "Карта сокровищ Элвиннского леса", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q2]Использование: Выкопать сокровище в указанном месте. (1 Мин Восстановление)\n[q]\"К западу от Дозорной башни. Недалеко от пня за логовом хищников.\""},
[203751] = {name = "[q2]Заметки о заклинаниях: ПНЬЕКОЕЯ ДОЛЕ", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Использование: Расшифровать заметки о заклинаниях с помощью подробного введения, чтобы выучить новое заклинание гравировки."},
[203752] = {name = "[q2]Заметки о заклинаниях: АИР ЖОЙЖВ", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Использование: Расшифровать заметки о заклинаниях с помощью заклятья понимания, чтобы выучить новое заклинание гравировки."},
[203753] = {name = "[q2]Заметки о заклинаниях: ДЫН ПЬЕЦЯ АЛЫЕЛ", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Использование: Расшифровать заметки о заклинаниях с помощью заклятья понимания, чтобы выучить новое заклинание гравировки."},
[203754] = {name = "Верховный маг Антонидас: полная автобиография", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Описания некоторых событий немного приукрашены. Тем не менее, будет отлично смотреться в любой библиотеке.\""},
[203755] = {name = "Научные записи верховного мага Теокрита", additional_info = "Уникальный\n[q]\"Исследовательские записи из башни Азоры. Будут отлично смотреться в любой библиотеке.\""},
[203756] = {name = "[q2]Записки ученика Азоры: 1-я страница", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Собирает вместе 6 записок ученика Азоры, чтобы создать новый рецепт гравировки."},
[203784] = {name = "Верхний правый фрагмент карты", additional_info = "[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[203785] = {name = "Верхний левый фрагмент карты", additional_info = "[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[203786] = {name = "Нижний правый фрагмент карты", additional_info = "[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[203787] = {name = "Нижний левый фрагмент карты", additional_info = "[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[203960] = {name = "[q2]Записки ученика Азоры: 2-я страница", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Собирает вместе 6 записок ученика Азоры, чтобы создать новый рецепт гравировки."},
[203961] = {name = "[q2]Записки ученика Азоры: 3-я страница", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Собирает вместе 6 записок ученика Азоры, чтобы создать новый рецепт гравировки."},
[203962] = {name = "[q2]Записки ученика Азоры: 4-я страница", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Собирает вместе 6 записок ученика Азоры, чтобы создать новый рецепт гравировки."},
[203990] = {name = "[q2]Руна расправы", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на перчатках руну \"Расправа\":\n\n\nОдновременный удар оружием в обеих руках, наносящий 95% обычного урона от оружия. Кроме того, урон от каждого оружия увеличивается еще на [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] ед. Отравленные цели получают на 20% больше урона. Длина серии приемов увеличивается на 2.\n\n \"Расправа\" взаимодействует с теми же талантами и эффектами, что и \"Удар в спину\" (кроме указанных отдельных случаев).\n[q]\"Обучает новой способности гравировки.\""},
[203991] = {name = "[q2]Руна быстрой реакции", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на нагруднике или мантии руну \"Быстрая реакция\":\n\n\nВы достаете оружие и быстро стреляете в противника, нанося обычный урон от оружия дальнего боя и снижая скорость передвижения на 50% на 6 сек. Продлевает серию приемов на 1.\n\n \"Быстрая реакция\" взаимодействует с теми же талантами и эффектами, что и \"Коварный удар\".\n[q]\"Обучает новой способности гравировки.\""},
[203992] = {name = "[q2]Руна коварства", additional_info = "Классы: Разбойник\n[q]\"Обучает новой способности гравировки.\""},
[203993] = {name = "[q2]Руна бойни", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на нагруднике или мантии руну \"Резня во тьме\":\n\n\nСнижает расход энергии на \"Удар в спину\" и \"Внезапный удар\" на 30 ед. и увеличивает урон, который они наносят целям под действием эффектов контроля (кроме игроков), на 70%. [ Гравировка перчаток \"Расправа\" : Не действует на \"Расправу\" / Не действует на способности, изученные через другие руны.]\n[q]\"Обучает новой способности гравировки.\""},
[203994] = {name = "[q2]Руна смертельного варева", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на нагруднике или мантии руну \"Смертельное варево\":\n\n\nУлучшает ваши яды несколькими эффектами:\n\n Поражая цель любым другим ядом, вы также отравляете ее \"Смертельным ядом\".\n\n Если на вашем оружии нет яда, оно может поразить цель \"Быстродействующим ядом\", словно он был нанесен на оружие.\n\n Урон от \"Смертельного яда\" и \"Быстродействующего яда\" теперь увеличивается в зависимости от вашей силы атаки.\n\n Ваш \"Смертельный яд\" теперь может действовать на цели одновременно со \"Смертельным ядом\" другого разбойника.\n[q]\"Обучает новой способности гравировки.\""},
[204174] = {name = "[q2]Руна точности", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на поножах руну \"Промеж глаз\":\n\n\nБыстрый завершающий прием, наносящий урон за каждый прием в серии с бонусом за силу атаки и оглушающий цель:\n\n 1 прием: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))]-[81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] ед. урона, оглушение на 1 сек.\n 2 приема: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)]-[81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] ед. урона, оглушение на 2 сек.\n 3 приема: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)]-[81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] ед. урона, оглушение на 3 сек.\n 4 приема: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)]-[81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] ед. урона, оглушение на 4 сек.\n 5 приемов: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)]-[81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] ед. урона, оглушение на 5 сек.\n\n Общее время восстановления с \"Ударом по почкам\".\n[q]\"Обучает новой способности гравировки.\""},
[204270] = {name = "Глубинный сердечник", additional_info = "Уникальный"},
[204441] = {name = "[q2]Руна кровавого бешенства", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на нагруднике руну \"Кровавое бешенство\":\n\n\n\"Кровопускание\" теперь можно применять в стойке берсерка. Урон от \"Кровопускания\" увеличивается на 100%. Каждый раз, когда \"Кровопускание\" наносит урон, цель получает дополнительный урон в объеме 4% вашей силы атаки.\n[q]\"Обучает новой способности гравировки.\""},
[204476] = {name = "Отрубленная голова кобольда", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[204477] = {name = "Отрубленная голова мурлока", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[204478] = {name = "Отрубленная голова гнолла", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[204688] = {name = "Первый фрагмент руны охотницы на монстров", additional_info = "[q2]Использование: Объединить с 2 другими частями, чтобы создать целую руну."},
[204689] = {name = "Второй фрагмент руны охотницы на монстров", additional_info = "[q2]Использование: Объединить с 2 другими частями, чтобы создать целую руну."},
[204690] = {name = "Третий фрагмент руны охотницы на монстров", additional_info = "[q2]Использование: Объединить с 2 другими частями, чтобы создать целую руну."},
[204703] = {name = "[q2]Руна сокрушения", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на перчатках руну \"Сокрушение\":\n\n\nКогда вы используете защитную стойку и держите в руке щит, \"Раскол брони\" также наносит урон в размере 150% урона в секунду вашего оружия. Урон увеличивается на 15% за каждый эффект \"Раскола брони\", уже наложенный на цель. Пока вы находитесь в защитной стойке, \"Сокрушение\" создает высокий уровень угрозы.\n[q]\"Обучает новой способности гравировки.\""},
[204716] = {name = "[q2]Руна неистового натиска", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на поножах руну \"Неистовый натиск\":\n\n\nКогда вы сражаетесь двуручным оружием, ваша скорость атаки повышается на 40%, а атаки ближнего боя дают еще 2 ед. ярости. Если атаки наносят критический урон, вместо этого они дают еще 4 ед. ярости.\n[q]\"Обучает новой способности гравировки.\""},
[204795] = {name = "[q2]Руна теневого удара", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на перчатках руну \"Теневой удар\":\n\nВы телепортируетесь за спину цели и атакуете, нанося 150% урона от оружия. Требуется состояние незаметности. Продлевает серию приемов на 1.\n[q]\"Обучает новой способности гравировки.\""},
[204804] = {name = "[q3]Гидраксианские браслеты", additional_info = "Становится персональным при поднятии\n{Запястья} {Кольчуга}\nБроня: 95\n+4 к силе\n+7 к выносливости\nПрочность: 40 / 40\nТребуется 25-й ур."},
[204806] = {name = "[q2]Руна победного ража", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на перчатках руну \"Победный раж\":\n\n\nВы мгновенно атакуете цель, нанося (1 + Сила атаки * 45 / 100) ед. урона и восполняя 30% своего максимального запаса здоровья. Можно применить только в течение 20 сек. после убийства противника, за которого можно получить опыт или честь.\n[q]\"Обучает новой способности гравировки.\""},
[204807] = {name = "[q3]Клинок Пучины", additional_info = "Становится персональным при поднятии\n{Двуручное} {Меч}\n{Урон: 71-107 } {Скорость 3.60}\n(24.72 ед. урона в секунду)\nПрочность: 100 / 100\nТребуется 25-й ур.\n[q2]Возможный эффект при попадании: Направляет на противников перед вами мощный поток воды.\n[q2]Если на персонаже: Повышает вероятность попадания атак и заклинаний на 1%.\n[q]\"Каждый взмах клинка издает шум волн.\""},
[204809] = {name = "[q2]Руна неистового грома", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на поножах руну \"Неистовый гром\":\n\n\n\"Удар грома\" теперь увеличивает интервал между атаками еще на 6% и наносит на 100% больше урона. Эту способность можно применять во всех стойках, а уровень создаваемой ею угрозы повышается на 75%.\n[q]\"Обучает новой способности гравировки.\""},
[204864] = {name = "[q2]Записки ученика Азоры", additional_info = "Становится персональным при поднятии\nУникальный (6)\n[q2]Использование: Собирает вместе 6 записок ученика Азоры, чтобы создать новый рецепт гравировки."},
[204905] = {name = "Зловещий фолиант", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Призыв Собоза\n[q]\"Принесите челюсть волка и кровь гнолла в утробу ягненка. Затем произнесите заклинание.\""},
[204906] = {name = "Кровь гнолла", additional_info = "Уникальный\n[q]\"Реагент для ритуала призыва\""},
[204907] = {name = "Челюсть волка", additional_info = "Уникальный\n[q]\"Реагент для ритуала призыва\""},
[204910] = {name = "[q0]Монстр – трезубец, нага (золото)", additional_info = "Становится персональным при поднятии\n{Двуручное} {Древковое}\n{Урон: 2-4 } {Скорость 3.00}\n(1.00 ед. урона в секунду)\nПрочность: 20 / 20"},
[204912] = {name = "[q2]Руна грации", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на поножах руну \"Демоническая грация\":\n\n\nВас переполняет энергия Скверны, повышающая вероятность уклонения для вас и вашего питомца на 20%, а вашу вероятность нанести критический удар любыми атаками – на 20%. Действует 6 сек.\n[q]\"Обучает новой способности гравировки.\""},
[205019] = {name = "Оскверненный кристалл души", additional_info = "Становится персональным при поднятии\nУникальный"},
[205020] = {name = "Чистый кристалл души", additional_info = "Становится персональным при поднятии\nУникальный"},
[205022] = {name = "[q2]Руна вытягивания души", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на плаще руну \"Вытягивание души\":\n\n\nТеперь ваше \"Похищение души\" наносит урон в 3 раза:раз быстрее, при этом \"Похищение жизни\" и \"Похищение души\" вытягивают на 6% больше здоровья за каждый ваш эффект темной магии, действующий на цель. Максимальный бонус – 18%. Когда вы применяете \"Похищение души\" к цели с уровнем здоровья ниже 20%, этот бонус становится равен 50% за каждый эффект вплоть до 150%. Кроме того, ваше \"Похищение души\" теперь может вызвать срабатывание таланта \"Сумерки\".\n[q]\"Обучает новой способности гравировки.\""},
[205181] = {name = "Неопознанный артефакт", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Причудливый магический предмет. Более опытный чернокнижник сможет определить, что это такое.\""},
[205182] = {name = "Лишенный сил артефакт", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Принести в жертву свою кровь, чтобы наполнить артефакт силой."},
[205183] = {name = "Усиленный Скверной артефакт", additional_info = "Становится персональным при поднятии\nУникальный"},
[205184] = {name = "Записка послушника", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[205215] = {name = "[q2]Руна власти", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на нагруднике или мантии руну \"Власть над демонами\":\n\n\nВероятность критического удара атак ближнего боя и заклинаний для вас и вашего прислужника повышается на 10%.\n[q]\"Обучает новой способности гравировки.\""},
[205218] = {name = "[q2]Манускрипт открытия", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Манускрипт}\nКлассы: Паладин\nТребуется 5-й ур.\n[q2]Выгравировать на плаще руну \"Вытягивание души\":\n\n\nТеперь ваше \"Похищение души\" наносит урон в 3 раза:раз быстрее, при этом \"Похищение жизни\" и \"Похищение души\" вытягивают на 6% больше здоровья за каждый ваш эффект темной магии, действующий на цель. Максимальный бонус – 18%. Когда вы применяете \"Похищение души\" к цели с уровнем здоровья ниже 20%, этот бонус становится равен 50% за каждый эффект вплоть до 150%. Кроме того, ваше \"Похищение души\" теперь может вызвать срабатывание таланта \"Сумерки\".\n[q]\"Обретите вдохновение, убив 5 противников, а затем изучите новую способность с помощью этого предмета.\""},
[205228] = {name = "[q2]Руна стрелы Хаоса", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на перчатках руну \"Стрела Хаоса\":\n\n\nПоражает противника стрелой хаотичного пламени, наносящей [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100]-[(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] ед. урона от магии Хаоса. Стрела Хаоса всегда попадает в цель, преодолевает сопротивление противника и позволяет вашим заклинаниям огня игнорировать эффекты поглощения. Монстры, уровень которых превышает ваш на 4 или более, с высокой вероятностью сопротивляются \"Стреле Хаоса\".\n[q]\"Обучает новой способности гравировки.\""},
[205230] = {name = "[q2]Руна блуждающего духа", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на перчатках руну \"Блуждающий дух\":\n\n\nНасылает на противника блуждающего духа, наносящего [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100]-[(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] ед. урона и увеличивающего получаемый целью периодический урон от ваших эффектов темной магии на 40% на 15 сек. По истечении времени действия или в случае рассеивания эффекта блуждающий дух возвращается к вам, восполняя здоровье в объеме 100% урона, нанесенного противнику.\n[q]\"Обучает новой способности гравировки.\""},
[205364] = {name = "Котомка послушника", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[205420] = {name = "[q2]Манускрипт правосудия", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Манускрипт}\nКлассы: Паладин\n[q2]Выгравировать на перчатках руну \"Удар воина Света\":\n\n\nМгновенный удар, наносящий 75% урона от оружия как урон от светлой магии и восстанавливающий 5% вашего максимального запаса маны. Время действия всех эффектов правосудия на цели обновляется до 30 сек.\n[q]\"Обучает новой способности после того, как вы высвободите энергию 10 печатей.\""},
[205683] = {name = "[q2]Руна укора", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]Выгравировать на поножах руну\n \"Укор\":\n\n\nПрерывает применение заклинаний и не позволяет применять заклинания той же школы в течение 3 сек.\n[q]\"Обучает новой способности гравировки.\""},
[205685] = {name = "[q2]Руна эгиды", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]Выгравировать на нагруднике руну \"Эгида\":\n\n\nУвеличивает показатель блокирования на 30% и изменяет талант \"Оплот\". Теперь \"Оплот\" с вероятностью 10% срабатывает от любой направленной против вас атаки ближнего или дальнего боя, а также всегда срабатывает, когда вы наносите критический удар в ближнем бою. Кроме того, талант \"Расплата\" срабатывает с вероятностью 2% за каждое вложенное в него очко талантов, когда вас атакуют в ближнем или дальнем бою.\n[q]\"Обучает новой способности гравировки.\""},
[205863] = {name = "Оскверненный манускрипт", additional_info = "Классы: Паладин"},
[205864] = {name = "Обгоревшая записка", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[205897] = {name = "[q2]Руна божественного света", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]Выгравировать на плаще руну \"Божественный свет\":\n\n\nВосполняет союзнику от [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] до [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100] ед. здоровья. 50% избыточного исцеления преобразуется в поглощающий урон щит, существующий в течение 15 сек. Прочность щита не суммируется при повторном применении \"Божественного света\".\n\n \"Божественный свет\" взаимодействует с теми же талантами и эффектами, что и \"Свет небес\".\n[q]\"Обучает новой способности гравировки.\""},
[205905] = {name = "[q2]Воспоминание о благочестивом защитнике", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на нагруднике или мантии руну \"Обман разума\":\n\n\n\"Пытка разума\" и \"Взрыв разума\" наносят на 50% больше урона, если противник находится под действием \"Слова Тьмы: Боль\".\n[q2]Использование: Сосредоточиться на воспоминании, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о духовных тайнах Азерота."},
[205932] = {name = "[q2]Пророчество о погибели короля", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на перчатках руну \"Слово Тьмы: Смерть\":\n\n\nНаносит противнику [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100]-[(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100] ед. урона от темной магии. Если он не погибает, вы получаете 50% урона от этого заклинания.\n[q2]Использование: Сосредоточиться на пророчестве, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о двух духовных тайнах Азерота."},
[205940] = {name = "[q2]Воспоминание о темном предназначении", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на обуви руну \"Чума Бездны\":\n\n\nПоражает цель болезнью, наносящей [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 129 / 100 * 6] ед. урона от темной магии за 18 сек.\n[q2]Использование: Сосредоточиться на воспоминании, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о духовных тайнах Азерота."},
[205942] = {name = "Химеричное прозрение", additional_info = "[q2]Выгравировать на поножах руну \"Молитва восстановления\":\n\n\nМолитва оберегает союзника и восстанавливает ему [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] ед. здоровья при следующем получении урона или восполнении здоровья. После исцеления заклинание переходит к другому участнику рейда в пределах 20 м. Молитва может совершить переход 5 раз и длится 30 сек. после каждой смены цели. Это заклинание можно накладывать только на одну цель единовременно."},
[205943] = {name = "Пророчество об оскверненной цитадели", additional_info = "Уникальный\n[q2]Выгравировать на поножах руну \"Гомункулы\":\n\n\nОтрывает щепотку души и создает 3 ваших миниатюрных копии:ваших миниатюрных копий, которые пытаются атаковать противника булавой, мечом или топором, снижая скорость атаки, силу атаки и показатель брони соответственно у всех пораженных целей.\n[q2]Использование: Сосредоточиться на пророчестве, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о двух духовных тайнах Азерота."},
[205944] = {name = "[q2]Взаимное прозрение", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на поножах руну \"Молитва восстановления\":\n\n\nМолитва оберегает союзника и восстанавливает ему [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] ед. здоровья при следующем получении урона или восполнении здоровья. После исцеления заклинание переходит к другому участнику рейда в пределах 20 м. Молитва может совершить переход 5 раз и длится 30 сек. после каждой смены цели. Это заклинание можно накладывать только на одну цель единовременно.\n[q]\"Обучает новой способности гравировки.\""},
[205945] = {name = "[q2]Воспоминание о плененном спасителе", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на поножах руну \"Общая боль\":\n\n\n\"Слово Тьмы: Боль\" теперь поражает еще до 2 противников в радиусе 15 м.\n[q2]Использование: Сосредоточиться на воспоминании, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о духовных тайнах Азерота."},
[205946] = {name = "[q2]Воспоминание о предательстве лидера", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на обуви руну \"Подавление боли\":\n\n\nУменьшает урон, получаемый союзником, на 40% и повышает сопротивление рассеиванию магии на 65% на 8 сек.\n[q2]Использование: Сосредоточиться на воспоминании, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о духовных тайнах Азерота."},
[205947] = {name = "[q2]Пророчество об оскверненной цитадели", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на поножах руну \"Гомункулы\":\n\n\nОтрывает щепотку души и создает 3 ваших миниатюрных копии:ваших миниатюрных копий, которые пытаются атаковать противника булавой, мечом или топором, снижая скорость атаки, силу атаки и показатель брони соответственно у всех пораженных целей.\n[q2]Использование: Сосредоточиться на пророчестве, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о двух духовных тайнах Азерота."},
[205948] = {name = "Успокаивающее прозрение", additional_info = "[q2]Выгравировать на плаще руну \"Прикосновение вампира\":\n\n\nПрименяет к цели эффект таланта \"Объятия вампира\" и наносит ей [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] ед. урона от темной магии за 15 сек. Все участники вашей группы восполняют ману в объеме 2% любого урона от темной магии, который вы наносите цели."},
[205949] = {name = "Многогранное прозрение", additional_info = "Классы: Жрец\n[q2]Выгравировать на перчатках руну \"Круг исцеления\":\n\n\nИсцеляет участников группы или рейда выбранного игрока в радиусе 43.5 м от него, восполняя [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100]-[(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] ед. здоровья.\n[q]\"Обучает новой способности гравировки.\""},
[205950] = {name = "[q2]Мрачное прозрение", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на перчатках руну \"Иссушение разума\":\n\n\nВзрыв темной магии, наносящий цели и противникам рядом с ней от [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] до [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] ед. урона от темной магии раз в 1 сек. в течение 6 сек. Действует в радиусе 10 м от цели.\n[q]\"Обучает новой способности гравировки.\""},
[205951] = {name = "[q2]Воспоминание о беспокойном послушнике", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на перчатках руну \"Исповедь\":\n\n\nВыпускает в цель поток небесного света, наносящий [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 128 / 100] ед. урона от светлой магии противнику или восполняющий [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 85 / 100] ед. здоровья союзнику мгновенно и далее раз в 1 сек. в течение 2 сек.\n[q2]Использование: Сосредоточиться на воспоминании, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о духовных тайнах Азерота."},
[205952] = {name = "Воспоминание о расколотом мире", additional_info = "[q2]Использование: Сосредоточиться на воспоминании, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о духовных тайнах Азерота."},
[205953] = {name = "[q2]Пророчество о нарушенной клятве", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на поясе руну \"Пронзание разума\":\n\n\nНаносит цели [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]-[142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] ед. урона от темной магии льда и повышает вероятность критического удара следующего \"Взрыва разума\" против этой цели на 30%. Суммируется до 3 раз.\n[q2]Использование: Сосредоточиться на пророчестве, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о двух духовных тайнах Азерота."},
[205961] = {name = "Мясо мулгорской птицы", additional_info = "Уникальный\n[q2]Использование: Положить приманку у логова скальной кошки."},
[205979] = {name = "[q2]Руна обходного удара", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на поножах руну \"Обходной удар\":\n\n\nВы с вашим питомцем одновременно наносите по 100% ед. урона в ближнем бою. После этого наносимый вами урон увеличивается на 8% на 10 сек. Эффект суммируется до 3 раз. Автоатаки вашего питомца с вероятностью 50% восстанавливают \"Обходной удар\".\n[q]\"Обучает новой способности гравировки.\""},
[205995] = {name = "Мускус луговой собачки", additional_info = "Классы: Охотник\n[q2]Использование: \"Приручение зверя\" также действует на луговых собачек (как на питомцев - спутников) (10 Мин Восстановление)"},
[206032] = {name = "[q2]Руна разделки туши", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на перчатках руну \"Разделка туши\":\n\n\nРазмашистый удар, который поражает все цели перед вами вашим оружием ближнего боя, нанося им 65% урона от оружия. Основная цель получает на 50% больше урона.\n[q]\"Обучает новой способности гравировки.\""},
[206155] = {name = "[q2]Руна меткости", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на нагруднике или мантии руну \"Мастер стрельбы\":\n\n\nПовышает вероятность критического урона на 5% и снижает затраты маны на способности-выстрелы на 25%.\n[q]\"Обучает новой способности гравировки.\""},
[206157] = {name = "Сефориевый заряд", additional_info = "Предмет, необходимый для задания\nУникальный (5)"},
[206159] = {name = "Маскировка Торговой компании", additional_info = "Предмет, необходимый для задания\n[q]\"Выглядит не очень убедительно...\""},
[206168] = {name = "[q2]Руна химеры", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на перчатках руну \"Выстрел химеры\":\n\n\nВы наносите 135% урона от оружия, обновляя действие текущего \"Укуса\" и активируя дополнительный эффект:\n\n \"Укус змеи\" – моментально наносит 48% от урона \"Укуса змеи\".\n\n \"Укус гадюки\" – моментально восполняет 60% маны, вытягиваемой этой способностью.\n\n \"Укус скорпида\" – пытается обезоружить противника на 10 сек сек. Этот эффект срабатывает не чаще раза в минуту.\n[q]\"Обучает новой способности гравировки.\""},
[206169] = {name = "[q2]Руна разрывного выстрела", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на перчатках руну \"Разрывной выстрел\":\n\n\nРазрывной выстрел наносит противникам в радиусе 8 м [Сила атаки дальнего боя * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Сила атаки дальнего боя * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. урона от огня. После этого заряд повторно наносит урон раз в сек. в течение 2 сек.\n[q]\"Обучает новой способности гравировки.\""},
[206170] = {name = "Шишка неистовства ветра", additional_info = "Предмет, необходимый для задания"},
[206175] = {name = "Кедровый бальзам", additional_info = "Предмет, необходимый для задания\nУникальный"},
[206176] = {name = "Ступка и пестик", additional_info = "Предмет, необходимый для задания\nУникальный\n[q2]Использование: Растереть 8 шишек Неистовства Ветра, чтобы изготовить ядовитую мазь для оружия. В теории."},
[206177] = {name = "Масло из кедровых орешков", additional_info = "Становится персональным при поднятии\n[q2]Использование: Восполняет 61.2 ед. здоровья за 18 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 2 на 15 мин."},
[206264] = {name = "[q2]Руна вдохновения", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]Выгравировать на поножах руну \"Пример для подражания\":\n\n\nВаш вдохновляющий образ время от времени снимает эффекты страха и сна с находящихся рядом участников группы.\n[q]\"Обучает новой способности гравировки.\""},
[206344] = {name = "Комплект ножей", additional_info = "Предмет, необходимый для задания\nУникальный\n[q2]Использование: Попытка разделать сырую блестящую рыбку."},
[206345] = {name = "Кусочки рыбы", additional_info = "Предмет, необходимый для задания\nУникальный"},
[206376] = {name = "[q2]Икона бастиона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\nТребуется 3-й ур.\n[q2]Выгравировать на нагруднике или мантии руну \"Мастерское владение щитом\":\n\n\nБлокируя атаку, вы восполняете 8% максимального запаса маны и усиливаете броню на 30% от показателя брони вашего щита. Суммируется до 5 раз. Кроме того, ваша базовая вероятность блокирования повышается на 10%, а показатель блокирования – на 15%.\n\n Когда вы применяете способность категории \"Шок\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 60 * 5). Время действия – 15 сек.\n[q]\"Обучает новой способности после того, как вы поразите противников \"Оружием камнедробителя\" 25 раз.\""},
[206381] = {name = "[q2]Сдвоенная икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\n[q2]Выгравировать на нагруднике или мантии руну \"Перегрузка\":\n\n\n\"Молния\", \"Цепная молния\", \"Цепное исцеление\", \"Волна исцеления\" и \"Выброс лавы\" с вероятностью 60% применяются к той же цели повторно без затрат ресурсов. Второе заклинание наносит вдвое меньше урона и не создает угрозы.\n[q]\"Обучает новой способности после того, как вы получите урон от сил природы 10 раз.\""},
[206382] = {name = "[q2]Грозовая икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\n[q2]Выгравировать на перчатках руну \"Водный щит\":\n\n\nСоздает щит из 3 водяных сфер:водяных сфер, восполняющий 1% максимального запаса маны раз в 5 секунд. Каждый раз, когда шаман получает удар в ближнем или дальнем бою или его поражает заклинание, щит восполняет 4% максимального запаса маны, теряя одну сферу. Этот эффект срабатывает не чаще, чем раз в несколько секунд. Время действия – 10 мин. Шаман может быть защищен только одним заклинанием категории \"Щит стихий\" одновременно.\n[q]\"Обучает новой способности после того, как вы нанесете 10 противникам, не являющимся игроками, урон 3 разных типов (силы природы, лед, огонь).\""},
[206383] = {name = "[q2]Монолитная икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\nТребуется 3-й ур.\n[q2]Выгравировать на поножах руну \"Щит земли\":\n\n\nЗащищает цель земляным щитом, который сокращает задержку применения и поддержания заклинаний при получении урона на 30%. Кроме того, когда защищенная цель становится целью атаки, она восполняет [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] ед. здоровья. Этот эффект срабатывает не чаще раза в несколько секунд. 9заряд:заряда:зарядов;. Время действия – 10 мин. \"Щит земли\" можно единовременно применить только к одной цели.\n[q]\"Обучает новой способности после того, как вы заблокируете 20 атак с помощью щита.\""},
[206384] = {name = "[q2]Астральная икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\nТребуется 3-й ур.\n[q]\"Обучает новой способности после того, как вы поразите противников \"Оружием камнедробителя\" 25 раз.\""},
[206385] = {name = "[q2]Обломочная икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\nТребуется 3-й ур.\n[q2]Выгравировать на поножах руну \"Путь земли\":\n\n\nПока \"Оружие камнедробителя\" действует на оружие в правой руке и вы держите щит в левой руке, уровень создаваемой вами угрозы повышается на 65%, запас здоровья увеличивается на 25%, получаемый урон уменьшается на 10%, вероятность получения критического удара в ближнем бою снижается на 6%, а \"Земной шок\" провоцирует цели, вынуждая атаковать вас, и получает отдельное время восстановления, но его дальность действия снижается до дистанции ближнего боя. Однако дальность заклинаний \"Молния\", \"Цепная молния\", \"Цепное исцеление\", \"Волна исцеления\" и \"Выброс лавы\" снижается на 20 м.\n[q]\"Обучает новой способности после того, как вы убьете 20 противников \"Земным шоком\".\""},
[206386] = {name = "[q2]Гальваническая икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\n[q2]Выгравировать на нагруднике или мантии руну \"Мастерское владение щитом\":\n\n\nБлокируя атаку, вы восполняете 8% максимального запаса маны и усиливаете броню на 30% от показателя брони вашего щита. Суммируется до 5 раз. Кроме того, ваша базовая вероятность блокирования повышается на 10%, а показатель блокирования – на 15%.\n\n Когда вы применяете способность категории \"Шок\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 60 * 5). Время действия – 15 сек.\n[q]\"Обучает новой способности после того, как вы убьете 10 противников \"Молнией\".\""},
[206387] = {name = "[q2]Каджарская икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\n[q2]Выгравировать на перчатках руну \"Выброс лавы\":\n\nВы бросаете в противника раскаленную лаву, наносящую [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)]-[605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] ед. урона от огня. Если цель находится под действием эффекта \"Огненный шок\", \"Выброс лавы\" наносит критический удар.\n[q]\"Обучает новой способности после того, как вы 5 раз получите урон от лавы (уменьшает урон от некоторых источников лавы).\""},
[206388] = {name = "[q2]Сернистая икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\n[q2]Выгравировать на перчатках руну \"Всплеск лавы\":\n\n\nВы наносите максимум 10 противникам:противникам в секторе перед собой от [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Сила атаки] до [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Сила атаки] ед. урона от огня. Эта способность создает высокий уровень угрозы. Периодический урон от \"Огненного шока\" с вероятностью 10% завершает восстановление \"Всплеска лавы\".\n[q]\"Обучает новой способности после того, как вы убьете 10 противников \"Земным шоком\".\""},
[206389] = {name = "[q2]Серная икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\nТребуется 3-й ур.\n[q2]Выгравировать на поясе руну \"Кольцо огня\":\n\n\n\"Тотем кольца огня\" заменяется на \"Кольцо огня\", при применении которого тотем огня пульсирует и наносит урон вокруг себя.\n[q]\"Обучает новой способности после того, как вы поразите противников \"Оружием камнедробителя\" 25 раз.\""},
[206390] = {name = "[q2]Ихтианская икона", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\nТребуется 3-й ур.\n[q2]Выгравировать на перчатках руну \"Водный щит\":\n\n\nСоздает щит из 3 водяных сфер:водяных сфер, восполняющий 1% максимального запаса маны раз в 5 секунд. Каждый раз, когда шаман получает удар в ближнем или дальнем бою или его поражает заклинание, щит восполняет 4% максимального запаса маны, теряя одну сферу. Этот эффект срабатывает не чаще, чем раз в несколько секунд. Время действия – 10 мин. Шаман может быть защищен только одним заклинанием категории \"Щит стихий\" одновременно.\n[q]\"Обучает новой способности после того, как вы поразите противников \"Оружием камнедробителя\" 25 раз.\""},
[206391] = {name = "[q2]Икона сизигии", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Тотем}\nКлассы: Шаман\nТребуется 3-й ур.\n[q2]Выгравировать на наручах руну \"Быстрина\":\n\n\nВосполняет союзнику [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]-[63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] ед. здоровья мгновенно и еще [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] ед. за 15 сек. Каждое \"Цепное исцеление\", примененное вами к той же основной цели в течение 15 сек., восстанавливает на 25% больше здоровья. Вызывает срабатывание \"Пробуждения предка\".\n[q]\"Обучает новой способности после того, как вы поразите противников \"Оружием камнедробителя\" 25 раз.\""},
[206466] = {name = "Луговой венок", additional_info = "[q2]Использование: Пробуждает дух равнин."},
[206469] = {name = "Луговой цветок", additional_info = "Классы: Друид\n[q2]Использование: Связать 3 луговых цветка в венок."},
[206954] = {name = "[q2]Идол медвежьей ярости", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Идол}\nКлассы: Друид\n[q2]Выгравировать на перчатках руну \"Увечье\":\n\n\nУвечит цель, нанося ей 160% обычного урона и увеличивая урон, получаемый целью от эффектов кровотечения и способности \"Полоснуть\", на 30%. Действует в течение 1 мин.\n\n Когда вы поражаете цель \"Увечьем\" в облике медведя, ваша сила атаки повышается на 4 за каждую единицу навыка защиты выше ( 60 * 5). Действует в течение 15 сек.\n[q]\"Обучает новой способности после того, как вы сохраните 50 ед. ярости или более в облике медведя на протяжении 60 сек.\""},
[206963] = {name = "[q2]Руна природного таланта", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на нагруднике или мантии руну \"Семя жизни\":\n\n\nКогда ваше исцеляющее заклинание прямого действия имеет критический эффект, вы наделяете цель семенем жизни, сохраняющим 50% восполненного здоровья. Семя жизни расцветет, когда цель в следующий раз получит урон или прямое исцеление. Время действия – 15 сек.\n[q]\"Обучает новой способности гравировки.\""},
[206966] = {name = "Луковица сатир-травы", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Поросль чужеродного растения.\""},
[206970] = {name = "[q2]Руна жизни", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на поножах руну \"Жизнецвет\":\n\nСокращает общее время восстановления для \"Жизнецвета\" и \"Омоложения\" на 0.5 сек. и дает способность \"Жизнецвет\":\n\n\nВосполняет цели [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья за 7 сек. Когда время действия \"Жизнецвета\" завершается или эффект рассеивают, цель восстанавливает еще [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья, а друид восполняет половину маны, затраченной на заклинание. Эффект суммируется на одной цели до 3 раз.\n[q]\"Обучает новой способности гравировки.\""},
[206975] = {name = "Ключ от хранилища артефактов", additional_info = "Уникальный\n[q]\"Открывает сундук в хранилище артефактов.\""},
[206985] = {name = "[q2]Отголосок вожака стаи", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Шаман\nТребуется 3-й ур.\n[q2]Выгравировать на обуви руну \"Дух вожака стаи\":\n\n\nУсиливает цель духом вожака стаи, повышая уровень создаваемой целью угрозы на 45% на 30 мин. Максимум 1 цель. Если шаман применяет это заклинание не к себе, он также получает эффект \"Верный помощник\", увеличивающий наносимый физический урон на 5% и уменьшая уровень создаваемой угрозы на 30% на 30 мин. Одна цель не может одновременно получить эффекты \"Дух вожака стаи\" и \"Верный помощник\".\n[q]\"Обучает новой способности.\""},
[206989] = {name = "[q2]Руна солнца", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на перчатках руну \"Солнечный огонь\":\n\n\nОбжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек.\n\n Также заменяет \"Лунный огонь\" на \"Солнечный огонь\" в облике медведя, кошки и лютого медведя. Это заклинание получает усиление от всех эффектов, связанных с \"Лунным огнем\", а также активирует такие эффекты.\n\n \"Солнечный огонь\" (облик медведя)\nОбжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек.\n\n \"Солнечный огонь\" (облик кошки)\nОбжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек. Продлевает серию приемов на 1.\n[q]\"Обучает новой способности гравировки.\""},
[206992] = {name = "[q2]Руна лобовой атаки", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на перчатках руну \"Лобовая атака\":\n\n\nВы бросаетесь к противнику в радиусе 13 м и с силой бьете его по голове, прерывая произносимые им заклинания. Противник не сможет произносить заклинания той же школы в течение 2 сек. Имеет общее время восстановления со \"Звериной атакой\".\n[q]\"Обучает новой способности гравировки.\""},
[206994] = {name = "Отрубленная голова свинобраза", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[206995] = {name = "Отрубленная голова гарпии", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[207062] = {name = "Отрубленная голова кентавра", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[207098] = {name = "Записка от Ба'со", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q]\"Записка на воровском жаргоне\"\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[207106] = {name = "Нижний левый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[207107] = {name = "Нижний правый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[207108] = {name = "Верхний левый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[207109] = {name = "Верхний правый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[207110] = {name = "Карта сокровищ Дуротара", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q2]Использование: Выкопать сокровище в указанном месте. (1 Мин Восстановление)\n[q]\"Перед головой обезьяны на самом южном из островов Эхо.\""},
[207590] = {name = "Мясо дуротарской свиньи", additional_info = "Уникальный\n[q2]Использование: Положить приманку у логова островной кошки."},
[207631] = {name = "Феромоны гадюки", additional_info = "Классы: Охотник\n[q2]Использование: \"Приручение зверя\" также действует на аспидов (как на питомцев - спутников) (10 Мин Восстановление)"},
[207731] = {name = "Зловещий фолиант", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Призыв Собоза\n[q]\"Принесите ногу макруры и череп култирасца на самый крупный из островов Эхо. Найдите круг силы и проведите ритуал.\""},
[207732] = {name = "Нога макруры", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Реагент для ритуала призыва.\""},
[207733] = {name = "Череп култирасца", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Реагент для ритуала призыва.\""},
[207972] = {name = "Уроки Та'зо", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Копия записей великого тролля-мага. Будет отлично смотреться в любой библиотеке.\""},
[207973] = {name = "Челюсть гончей", additional_info = "Уникальный"},
[207974] = {name = "Зловещий фолиант", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Призыв Собоза\n[q]\"Поместите челюсть гончей и кровь гнолла в стоки. Затем произнесите заклинание.\""},
[207975] = {name = "Отрубленная голова нетопыря", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
