[208038] = {name = "Нижний левый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[208085] = {name = "Перстень-печатка лейтенанта Алого ордена", additional_info = "Уникальный\n[q2]Использование: Изготовление поддельных документов, доказывающих вину Алого ордена перед Альянсом. Требуются письменные принадлежности из ратуши Брилла."},
[208086] = {name = "Фальшивая записка Алого ордена", additional_info = "Уникальный\n[q]\"Оскорбительные рассуждения о расовом превосходстве людей. Руководству Альянса это не понравится.\""},
[208139] = {name = "Зловещий фолиант", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Призыв Собоза\n[q]\"Принесите челюсть волка и кровь вендиго на Мерцающий хребет. Встаньте на ритуальный камень и призовите демона.\""},
[208140] = {name = "Кровь вендиго", additional_info = "Уникальный\n[q]\"Реагент для ритуала призыва\""},
[208158] = {name = "Безупречное сердце трогга", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[208159] = {name = "Отрубленная голова тролля", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[208160] = {name = "Отрубленная лапа вендиго", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[208180] = {name = "Кроличий мускус", additional_info = "Классы: Охотник\n[q2]Использование: \"Приручение зверя\" также действует на кроликов (как на питомцев - спутников) (10 Мин Восстановление)"},
[208183] = {name = "[q2]Записки аптекаря", additional_info = "Становится персональным при поднятии\nУникальный (6)\n[q2]Использование: Собирает вместе 6 записок аптекаря, чтобы создать новый рецепт гравировки."},
[208185] = {name = "Учебник аптекаря по метафизике", additional_info = "Уникальный\n[q]\"Базовые уроки по теории чар и исследованию магии за авторством верховного мага Ротвика из Королевского фармацевтического общества. Будут отлично смотреться в любой библиотеке.\""},
[208192] = {name = "Мясо свиньи из Дун Морога", additional_info = "Уникальный\n[q2]Использование: Положить приманку в берлоге великого медведя."},
[208196] = {name = "[q3]Кольцо Моа'кина", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\n+7 к выносливости\n+7 к духу\nТребуется 60-й ур.\n[q2]Использование: Предъявление прав на обещанную душу. (3 Ч Восстановление)"},
[208205] = {name = "Записка Чернокрыса", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q]\"Записка на воровском жаргоне.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[208213] = {name = "Верхний правый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[208215] = {name = "Верхний левый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[208218] = {name = "Нижний правый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[208219] = {name = "Нижний левый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[208220] = {name = "Карта сокровищ Дун Морога", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q2]Использование: Выкопать сокровище в указанном месте. (1 Мин Восстановление)\n[q]\"Под мостом от Караноса в Стальгорн.\""},
[208222] = {name = "[q3]Каратель старой гвардии", additional_info = "Становится персональным при поднятии\nУникальный\n{Двуручное} {Топор}\n{Урон: 163-245 } {Скорость 3.90}\n(52.31 ед. урона в секунду)\n+8 к силе\n+10 к ловкости\n+41 к выносливости\nПрочность: 100 / 100\nКлассы: Воин\nТребуется 55-й ур.\n[q2]Если на персонаже: Когда ваш удар добивает врага, убийство которого дает опыт или честь, следующая атака наносит критический урон.\n[q]\"Предыдущий владелец этого оружия крайне бережно с ним обращался.\""},
[208223] = {name = "Котомка послушника", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[208224] = {name = "Записка послушника", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[208414] = {name = "[q2]Лунный идол", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Идол}\nКлассы: Друид\n[q2]Выгравировать на нагруднике или мантии руну \"Гнев Ярости Бури\":\n\n\n\"Гнев\" теперь расходует на 100% меньше маны, и его можно применять в облике Древа Жизни. Каждый раз, когда \"Гнев\" наносит урон, он с вероятностью 12% позволяет применить следующее \"Целительное прикосновение\" мгновенно и в любом облике. Время действия эффекта – 15 сек.\n[q]\"Победите 6 существ, на которых действует ваш \"Лунный огонь\", а затем изучите новую способность с помощью этого предмета.\""},
[208425] = {name = "[q7]Блестящий пережиток прошлого.", additional_info = "Связан с учетной записью\nУникальный\nШея\n+6 к духу\n[q2]Использование: Возвращает вас в область \"[Hearthstone Location]\". Пункт назначения определяется тем, в какой таверне вы остановились. (1 Час Восстановление)"},
[208484] = {name = "[q3]Свет солнца", additional_info = "Становится персональным при поднятии\nУникальный\nОдноручное\n{Урон: 10-14 } {Скорость 1.70}\n(7.06 ед. урона в секунду)\n+11 к выносливости\n+34 к духу\nУстойчивость: +17 Тьма"},
[208601] = {name = "Верхний правый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
