[208604] = {name = "Нижний левый фрагмент карты", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить с 3 другими частями, чтобы создать целую карту.\n[q]\"Кажется, это оторванный клочок карты...\""},
[208605] = {name = "Карта сокровищ Тельдрассила", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q2]Использование: Выкопать сокровище в указанном месте. (1 Мин Восстановление)\n[q]\"Полый пень в деревне Рут'теран.\""},
[208607] = {name = "Олений мускус", additional_info = "Классы: Охотник\n[q2]Использование: \"Приручение зверя\" также действует на оленей (как на питомцев - спутников) (10 Мин Восстановление)"},
[208608] = {name = "Мясо тельдрассильской птицы", additional_info = "Уникальный\n[q2]Использование: Положить приманку в берлоге великого медведя."},
[208609] = {name = "Цветок с поляны", additional_info = "Классы: Друид\n[q2]Использование: Связать 3 цветка с поляны в венок."},
[208610] = {name = "Отрубленная голова совы", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[208611] = {name = "Отрубленная голова тигра", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[208612] = {name = "Отрубленная голова паука", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Зловещий трофей. Возможно, кого-то он заинтересует...\""},
[208682] = {name = "Брошенное яйцо хрустогрыза", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q]\"Ему нужен новый дом.\""},
[208687] = {name = "[q2]Руна растерзания", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на поножах руну \"Растерзать\":\n\n\nРазрывает противника, нанося ему [(9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) * 20 / 100 * 5] ед. урона от кровотечения за 15 сек. и еще по 20% урона от оружия за каждый эффект \"Растерзать\" на цели. Удар значительно повышает уровень угрозы. Эффект суммируется до 5 раз на одной цели.\n[q]\"Обучает новой способности гравировки.\""},
[208689] = {name = "[q2]Свирепый идол", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Идол}\nКлассы: Друид\n[q2]Выгравировать на поножах руну \"Дикий рев\":\n\n\nЗавершающий прием, увеличивающий наносимый физический урон в облике кошки на 30%. Время действия зависит от длины серии:\n 1 прием: 14 секунд\n 2 приема: 19 секунд.\n 3 приема: 24 секунды\n 4 приема: 29 секунд\n 5 приемов: 34 секунды.\n[q]\"Нанесите урон от кровотечения гуманоидам 20 раз, а затем изучите новую способность с помощью этого идола.\""},
[208701] = {name = "[q2]Руна повелителя зверей", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на нагруднике или мантии руну \"Повелитель зверей\":\n\n\nУвеличивает урон и запас здоровья вашего питомца на 15%, а скорость восстановления концентрации – на 50%. Кроме того, \"Рык\" питомца теперь провоцирует цель, заставляя ее атаковать питомца в течение 3 сек.\n[q]\"Обучает новой способности гравировки.\""},
[208739] = {name = "Боевой штандарт Орды", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q]\"Втыкайте его в землю промеж трупов ваших врагов.\""},
[208741] = {name = "[q2]Руна бесконечной ярости", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на шлеме руну \"Бесконечная ярость\":\n\n\nНанося любой урон, вы накапливаете на 25% больше ярости.\n[q]\"Обучает новой способности гравировки.\""},
[208743] = {name = "Душа жадности", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник"},
[208744] = {name = "[q2]Руна стрел Тьмы", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на перчатках руну \"Залп стрел Тьмы\":\n\n\n\"Стрела Тьмы\" поражает до 5 целей на общем расстоянии в 10 м, но наносит на 30% меньше урона.\n[q]\"Обучает новой способности гравировки.\""},
[208749] = {name = "Ключ от тайника племени Кривой Сосны", additional_info = "Уникальный\n[q]\"На поверхности грубо вырезан символ в виде ветки.\""},
[208750] = {name = "[q2]Руна направления", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на нагруднике или мантии руну \"Мастер-чаротворец\":\n\n\n\"Похищение жизни\" больше нельзя поддерживать. Теперь оно действует 15 сек., получает время восстановления 15 сек., расходует на 100% больше маны и восстанавливает вам на 50% больше здоровья каждый раз, когда наносит урон.\n[q]\"Обучает новой способности гравировки.\""},
[208753] = {name = "[q2]Заметки о заклинании: регенерация", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Выгравировать на нагруднике или мантии руну \"Регенерация\":\n\n\nВосстанавливает цели [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] ед. здоровья за 3 сек. и дает эффект \"Темпоральный маяк\" на 30 сек.\n\n Темпоральный маяк\n\nЗапоминает положение цели в пространстве-времени. 70% наносимого вами урона от тайной магии преобразуется в темпоральное исцеление и применяется к каждой текущей цели \"Темпорального маяка\". Вы получаете на 50% меньше исцеления из этого источника. Заклинания тайной магии, наносящие урон нескольким целям, дают на 80% меньше чародейского исцеления.\n[q]\"Teaches you a new Engraving ability.\""},
[208754] = {name = "[q2]Заметки о заклинании: НЕРА ЯЦИГЕРЕ", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Использование: Расшифровать заметки о заклинаниях с помощью заклятья понимания, чтобы выучить новое заклинание гравировки."},
[208758] = {name = "[q2]Руна земли", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Шаман\n[q2]Выгравировать на поножах руну \"Путь земли\":\n\n\nПока \"Оружие камнедробителя\" действует на оружие в правой руке и вы держите щит в левой руке, уровень создаваемой вами угрозы повышается на 65%, запас здоровья увеличивается на 25%, получаемый урон уменьшается на 10%, вероятность получения критического удара в ближнем бою снижается на 6%, а \"Земной шок\" провоцирует цели, вынуждая атаковать вас, и получает отдельное время восстановления, но его дальность действия снижается до дистанции ближнего боя. Однако дальность заклинаний \"Молния\", \"Цепная молния\", \"Цепное исцеление\", \"Волна исцеления\" и \"Выброс лавы\" снижается на 20 м.\n[q]\"Обучает новой способности гравировки.\""},
[208760] = {name = "Венок полян", additional_info = "[q2]Использование: Пробуждает дух равнин."},
[208764] = {name = "[q2]Руна разума", additional_info = "Уникальный\nКлассы: Жрец\n[q2]Выгравировать на поясе руну \"Пронзание разума\":\n\n\nНаносит цели [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]-[142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] ед. урона от темной магии льда и повышает вероятность критического удара следующего \"Взрыва разума\" против этой цели на 30%. Суммируется до 3 раз."},
[208765] = {name = "[q2]Рука помощи", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q]\"Рука откроется для того, кто спасает других.\""},
[208766] = {name = "[q2]Рука помощи", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q]\"Рука открылась для вас.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[208767] = {name = "[q2]Руна восстановления", additional_info = "Уникальный\nКлассы: Жрец\n[q2]Выгравировать на поножах руну \"Молитва восстановления\":\n\n\nМолитва оберегает союзника и восстанавливает ему [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] ед. здоровья при следующем получении урона или восполнении здоровья. После исцеления заклинание переходит к другому участнику рейда в пределах 20 м. Молитва может совершить переход 5 раз и длится 30 сек. после каждой смены цели. Это заклинание можно накладывать только на одну цель единовременно.\n[q]\"Обучает новой способности вырезания рун.\""},
[208768] = {name = "Спичечный коробок буканьера", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q]\"Используется для воспламенения горючих материалов.\""},
[208771] = {name = "[q2]Руна танца клинков", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на поножах руну \"Танец клинков\":\n\nЗавершающий прием, повышающий вероятность парирования на 10%, а силу атаки – на 4 за каждую единицу навыка защиты выше ( 60 * 5). Время действия зависит от длины серии:\n\n 1 прием: 14 секунд\n 2 приема: 18 секунд\n 3 приема: 22 секунды\n 4 приема: 26 секунд\n 5 приемов: 30 секунд.\n[q]\"Обучает новой способности гравировки.\""},
[208772] = {name = "[q2]Руна удара саблей", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на перчатках руну \"Удар саблей\":\n\n\nВы жестоко рубите противника, нанося 100% урона от оружия мгновенно и еще (Сила атаки * 5 / 100) ед. урона от кровотечения раз в 2 сек. в течение 12 сек. Суммируется до 3 раз. Каждый эффект также увеличивает урон от \"Удара саблей\" и \"Коварного удара\" на 50%. Продлевает серию приемов на 1.\n\n \"Удар саблей\" взаимодействует с теми же талантами и эффектами, что и \"Коварный удар\".\n[q]\"Обучает новой способности гравировки.\""},
[208773] = {name = "Рыболовный гарпун", additional_info = "Становится персональным при поднятии\nКлассы: Воин , Охотник\n[q2]Использование: Бросает гарпун в цель (дальность: 40 м)\n[q]\"Лучший друг начинающего охотника на акул!\""},
[208777] = {name = "[q2]Руна снайпера", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на поножах руну \"Навыки снайпера\":\n\n\nКогда вы не двигаетесь с места в течение 2 сек., вероятность критического удара ваших способностей-выстрелов повышается на 2%. Эффект суммируется каждую секунду до 5 раз. Когда вы накапливаете 2 или более эффектов, ваш \"Прицельный выстрел\" начинает применяться мгновенно. Передвигаясь, вы теряете один эффект каждую секунду.\n[q]\"Обучает новой способности гравировки.\""},
[208778] = {name = "[q2]Руна быстрого удара", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на перчатках руну \"Быстрый удар\":\n\n\nБезрассудная и стремительная атака ближнего боя с использованием двуручного оружия, наносящая от (Сила атаки * 30 / 100) до (Сила атаки * 40 / 100) ед. физического урона. Эта способность получает усиление от всех эффектов, связанных со способностью \"Удар героя\", а также активирует такие эффекты.\n[q]\"Обучает новой способности гравировки.\""},
[208799] = {name = "[q2]Заметки о заклинаниях: живой жар", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Выгравировать на перчатках руну \"Живая бомба\":\n\n\nВы превращаете цель в живую бомбу, нанося [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] ед. урона от огня за 12 сек. Через 12 сек. или при снятии эффекта цель взрывается, нанося [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] ед. урона от огня противникам в радиусе 10 м.\n\n \"Живая бомба\" взаимодействует с теми же талантами и эффектами, что и \"Ожог\".\n[q]\"Обучает новой способности гравировки.\""},
[208800] = {name = "Бакстан: о разрушительной магии", additional_info = "Уникальный\n[q]\"Заметки знаменитого гоблинского мага. Будут отлично смотреться в любой библиотеке.\""},
[208823] = {name = "Монета-подношение", additional_info = "Становится персональным при поднятии\nКлассы: Жрец\n[q2]Использование: Бросить в ближайший колодец и загадать желание"},
[208828] = {name = "Воспоминание о нарушенной клятве", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на поясе руну \"Пронзание разума\":\n\n\nНаносит цели [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]-[142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] ед. урона от темной магии льда и повышает вероятность критического удара следующего \"Взрыва разума\" против этой цели на 30%. Суммируется до 3 раз.\n[q2]Использование: Сосредоточиться на воспоминании, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о духовных тайнах Азерота."},
[208833] = {name = "Злобный пирог", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q]\"Этот пирог источает зловещую энергию.\""},
[208838] = {name = "[q2]Сейф клана Черного Железа", additional_info = "Становится персональным при поднятии\nУникальный\n[q0]Заперт\n Требует Вскрытие замков (1)"},
[208843] = {name = "Боевой тотем", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Использование: Вызывает таурена на дуэль\n[q]\"Символ враждебности для участников Орды.\""},
[208847] = {name = "Жеода в форме черепа", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q]\"Наверняка можно разбить хорошим ударом.\""},
[208848] = {name = "Треснувшая жеода в форме черепа", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q]\"Эта жеода разбита.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[208849] = {name = "[q2]Манускрипт благословений", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Манускрипт}\nКлассы: Паладин\n[q2]Выгравировать на нагруднике руну \"Благословенная земля\":\n\n\n\"Освящение\" теперь также исцеляет участников группы в области действия, восполняя здоровье в объеме 200% нанесенного урона.\n[q]\"Обучает новой способности после того, как вы благословите 5 разных игроков.\""},
[208851] = {name = "[q2]Манускрипт справедливости", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Манускрипт}\nКлассы: Паладин\n[q2]Выгравировать на перчатках руну \"Длань возмездия\":\n\n\nПровоцирует цель, заставляя ее атаковать вас. Не действует, если эта цель уже атакует вас.\n\n Пока вам известна эта способность, бонус к уровню создаваемой угрозы от \"Праведного неистовства\" увеличивается до 80%. Когда другие игроки исцеляют вас, \"Праведное неистовство\" восстанавливает вам ману в объеме 25% восполненного здоровья. Кроме того, если вы должны получить урон, после которого ваш уровень здоровья упадет ниже 35%, этот урон уменьшается на 20%. \"Праведное неистовство\" действует до отмены.\n[q]\"Обучает новой способности после того, как вы убьете 10 врагов, оглушенных \"Молотом правосудия\".\""},
[208853] = {name = "[q2]Заметки о заклинаниях: заморозка мозгов", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\nТребуетГравировка\n(1)\n[q2]Выгравировать на обуви руну \"Заморозка мозгов\":\n\n\nВаши наносящие урон заклинания льда, применяющие эффект окоченения, с вероятностью 20% позволяют применить следующий \"Огненный шар\", \"Стрелу чар льда\", \"Стрелу гибельного огня\" или \"Стрелу ледяного огня\" мгновенно и без затрат маны.\n[q]\"Обучает новой способности вырезания рун.\""},
[208854] = {name = "[q2]Жеваные заметки о заклинаниях", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Использование: Расшифровать заметки о заклинаниях с помощью заклятья понимания, чтобы выучить новое заклинание гравировки.\n[q]\"Трогги-шаманы прямо-таки глотают книги.\""},
[208855] = {name = "Приманка из радужного тунца", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Использование: Скормить подкормку цели.\n[q]\"Лакомство для озерных монстров.\""},
[208860] = {name = "Руми из Гномрегана: собрание трудов", additional_info = "Уникальный\n[q]\"Заметки знаменитого гномьего мага. Будут отлично смотреться в любой библиотеке.\""},
[209027] = {name = "Угощения для крабов", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник , Друид\n[q2]Использование: Скормить приманку цели.\n[q]\"Фурболги приманивают молодых рифовых крабов на эти лакомства.\""},
[209028] = {name = "[q2]Заметки о заклинаниях: БАВОЖИ МЯБА", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Использование: Расшифровать заметки о заклинаниях с помощью заклятья понимания, чтобы выучить новое заклинание гравировки."},
[209029] = {name = "Письмо от Эмили", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[209030] = {name = "Ключ от тайника со снаряжением", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник"},
[209031] = {name = "Непримечательный конверт", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[209041] = {name = "Волшебные тыквенные семена", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Использование: Посадка тыквенных семян\n[q]\"Для роста требуется особая почва и питание.\""},
[209042] = {name = "Рыбная костная мука", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q]\"Отвратительно пахнет, но содержит массу питательных веществ! Хорошо подходит для удобрения.\""},
[209043] = {name = "Проба плодородной земли", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q]\"Тот, кто собрал эту пробу, хорошо разбирается в почве.\""},
[209045] = {name = "Душа моря", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин , Чернокнижник"},
[209047] = {name = "Корявый гарпун", additional_info = "Становится персональным при поднятии\nКлассы: Воин , Охотник\n[q2]Использование: Бросает гарпун в цель (дальность: 40 м)\n[q]\"Только кровь величайшего крепкозуба утолит его жажду.\""},
[209056] = {name = "Запасные детали уборочного голема", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг , Чернокнижник\n[q2]Использование: Соединить запасные детали уборочного голема с ядром элементаля, чтобы изготовить прототип двигателя."},
[209057] = {name = "Прототип двигателя", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг , Чернокнижник\n[q2]Использование: Установить в прототип уборочного голема."},
[209058] = {name = "Ядро элементаля", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг , Чернокнижник\n[q2]Использование: Соединить запасные детали уборочного голема с ядром элементаля, чтобы изготовить прототип двигателя."},
[209059] = {name = "Окорок кровоклыка", additional_info = "Уникальный\nКлассы: Охотник\n[q2]Использование: Положить приманку у логова койота."},
[209418] = {name = "[q3]Адамантиновая черепаховая броня", additional_info = "Становится персональным при поднятии\n{Грудь} {Кольчуга}\n[q2]Броня: 338\n+11 к выносливости\nПрочность: 120 / 120\nТребуется 25-й ур."},
[209420] = {name = "[q2]Погибель жабр", additional_info = "Становится персональным при поднятии\n{Правая рука} {Дробящее}\n{Урон: 18-34 } {Скорость 2.60}\n(10.00 ед. урона в секунду)\nПрочность: 60 / 60\nКлассы: Воин\nТребуется 14-й ур.\n[q]\"Согласно легенде, это зачарованное оружие способно поглощать души убитых мурлоков.\""},
[209421] = {name = "[q3]Шнурованный ремень Акваниса", additional_info = "Становится персональным при поднятии\n{Пояс} {Кожа}\nБроня: 58\n+7 к ловкости\n+4 к выносливости\n+7 к духу\nПрочность: 35 / 35\nТребуется 25-й ур."},
[209422] = {name = "[q3]Колье приливов", additional_info = "Становится персональным при поднятии\nШея\n+7 к силе\n+4 к ловкости\nТребуется 25-й ур."},
[209423] = {name = "[q3]Развевающийся платок", additional_info = "Становится персональным при поднятии\nСпина\nБроня: 24\n+6 к интеллекту\n+6 к духу\nТребуется 25-й ур."},
[209424] = {name = "[q3]Барьер из панцирной пластины", additional_info = "Становится персональным при поднятии\n{Левая рука} {Щит}\nБроня: 661\nБлокирование: 14\n+12 к силе\nПрочность: 100 / 100\nТребуется 25-й ур."},
[209432] = {name = "[q3]Кушак Гхаму-ра", additional_info = "Становится персональным при поднятии\n{Пояс} {Ткань}\nБроня: 27\n+8 к выносливости\n+8 к интеллекту\nПрочность: 30 / 30\nТребуется 25-й ур."},
[209436] = {name = "[q3]Надколотый Укус Серракиса", additional_info = "Становится персональным при поднятии\n{Одноручное} {Кинжал}\n{Урон: 29-55 } {Скорость 1.80}\n(23.33 ед. урона в секунду)\nПрочность: 65 / 65\nТребуется 25-й ур.\n[q2]Возможный эффект при попадании: 4 ед. урона от сил природы раз в 2 сек. в течение 20 сек.\n[q]\"Похоже, этот кинжал видал виды, но лезвие у него по-прежнему острое.\""},
[209523] = {name = "[q3]Мерцающая накидка крепкозуба", additional_info = "Становится персональным при поднятии\nСпина\nБроня: 24\n+6 к силе\n+6 к духу\nТребуется 25-й ур."},
[209524] = {name = "[q3]Наручники Серракиса", additional_info = "Становится персональным при поднятии\n{Запястья} {Кожа}\n[q2]Броня: 75\n+6 к силе\n+4 к выносливости\nПрочность: 35 / 35\nТребуется 25-й ур."},
[209525] = {name = "[q3]Заточенный тальвар Темноводья", additional_info = "Становится персональным при поднятии\n{Правая рука} {Меч}\n{Урон: 43-82 } {Скорость 2.70}\n(23.15 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется 25-й ур.\n[q2]Возможный эффект при попадании: Поражение противника теневой молнией, наносящей 30 ед. урона от темной магии."},
[209526] = {name = "[q3]ТЕСТОВЫЙ тальвар Темноводья", additional_info = "Становится персональным при поднятии\n{Правая рука} {Меч}\nТребуется 25-й ур.\n[q2]Возможный эффект при попадании: Поражение противника теневой молнией, наносящей 30 ед. урона от темной магии.\n[q]\"Это фальшивое, ненастоящее, полностью выдуманное оружие\""},
[209527] = {name = "[q3]Нагские рукавицы", additional_info = "Становится персональным при поднятии\n{Кисти рук} {Кожа}\n[q2]Броня: 94\n+6 к силе\n+4 к выносливости\n+8 к духу\nПрочность: 35 / 35\nТребуется 25-й ур."},
[209534] = {name = "[q4]Азшарский арбалет", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Арбалет}\n{Урон: 36-69 } {Скорость 2.80}\n(18.75 ед. урона в секунду)\nПрочность: 95 / 95\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение силы атаки в дальнем бою на 17 ед."},
[209559] = {name = "[q3]Трость сумеречного мудреца", additional_info = "Становится персональным при поднятии\n{Двуручное} {Посох}\n{Урон: 51-78 } {Скорость 2.60}\n(24.81 ед. урона в секунду)\n+5 к выносливости\n+10 к духу\nПрочность: 100 / 100\nТребуется 25-й ур.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 24 ед."},
[209560] = {name = "[q3]Молот праведного правосудия", additional_info = "Становится персональным при поднятии\n{Правая рука} {Дробящее}\n{Урон: 17-32 } {Скорость 1.30}\n(18.85 ед. урона в секунду)\nБроня: 50\n+3 к силе\n+2 к выносливости\nПрочность: 90 / 90\nТребуется 25-й ур."},
[209561] = {name = "[q4]Жезл древнего сноходца", additional_info = "Становится персональным при поднятии\n{Двуручное} {Посох}\n{Урон: 37-63 } {Скорость 2.00}\n(25.00 ед. урона в секунду)\n+15 к интеллекту\n+14 к духу\nУстойчивость: +5 Тьма\nПрочность: 120 / 120\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 26 ед."},
[209562] = {name = "[q4]Смертоносный удар гидры", additional_info = "Становится персональным при поднятии\n{Двуручное} {Меч}\n{Урон: 87-132 } {Скорость 3.50}\n(31.29 ед. урона в секунду)\nПрочность: 120 / 120\nТребуется 25-й ур.\n[q2]Возможный эффект при попадании: Поражает цель древним разъедающим ядом, наносящим 20 ед. урона от сил природы раз в 3 сек. и ослабляющим броню на 150 ед. на 15 сек."},
[209563] = {name = "[q3]Нагский сердцеруб", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Лук}\n{Урон: 30-56 } {Скорость 2.90}\n(14.83 ед. урона в секунду)\n+5 к силе\nПрочность: 80 / 80\nТребуется 25-й ур."},
[209564] = {name = "[q3]Трезубец защитника", additional_info = "Становится персональным при поднятии\n{Двуручное} {Древковое}\n{Урон: 59-90 } {Скорость 3.00}\n(24.83 ед. урона в секунду)\n+12 к ловкости\n+11 к выносливости\nПрочность: 100 / 100\nТребуется 25-й ур."},
[209565] = {name = "[q3]Кольцо далеких глубин", additional_info = "Становится персональным при поднятии\nПалец\n+6 к силе\n+6 к выносливости\nТребуется 25-й ур."},
