[209687] = {name = "[q3]Кираса из шкуры гидры", additional_info = "Становится персональным при поднятии\n{Грудь} {Кожа}\n[q2]Броня: 168\n+6 к силе\n+12 к выносливости\n+7 к интеллекту\nПрочность: 100 / 100\nТребуется 25-й ур."},
