[209822] = {name = "[q3]Сила целеустремленности", additional_info = "Становится персональным при поднятии\n{Правая рука} {Дробящее}\n{Урон: 26-50 } {Скорость 2.00}\n(19.00 ед. урона в секунду)\n+2 к выносливости\n+5 к интеллекту\n+3 к духу\nПрочность: 90 / 90\nТребуется 25-й ур."},
[209823] = {name = "[q3]Перстень зверей", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\nКлассы: Охотник\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличивает урон, наносимый вашими питомцами, на 1%."},
[209824] = {name = "[q3]Мерцающие наплечные пластины", additional_info = "Становится персональным при поднятии\n{Плечо} {Кольчуга}\n[q2]Броня: 223\n+6 к выносливости\nПрочность: 70 / 70\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 4 ед."},
