[209841] = {name = "Сущность буйной магии", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Наполняет большой магический жезл буйной магией."},
[209843] = {name = "Нар'таласский альманах, том 74", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Чародейские исследования древних кель'дорай. Достойное пополнение любой библиотеки.\""},
[209844] = {name = "Даларанский справочник, том 23", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Чародейские исследования магов Кирин-Тора. Достойное пополнение любой библиотеки.\""},
[209845] = {name = "Заговоры и чары", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Заклинания, предназначенные для обмана и манипуляций. Достойное пополнение любой библиотеки.\""},
[209846] = {name = "Тайны Дремлющих", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Наблюдения и размышления об Изумрудном Сне. Достойное пополнение любой библиотеки.\""},
[209847] = {name = "Руководство по магическим системам", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Беспорядочные советы по исправлению неполадок в гоблинских устройствах. Достойное пополнение любой библиотеки.\""},
[209848] = {name = "Свитки Гоаз", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Написаны на забытом языке титанов. Тем не менее, достойное пополнение любой библиотеки.\""},
[209849] = {name = "Преступления против анатомии", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Автор: доктор Крастинов. Сомнительное пополнение любой библиотеки.\""},
[209850] = {name = "Руны королей-чародеев", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Реликвия времен могучих империй огров Дренора. Достойное пополнение любой библиотеки.\""},
[209851] = {name = "Ярость земли", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Особо охраняемые тайны шаманов из племени Зловещего Тотема. Достойное пополнение любой библиотеки.\""},
[209852] = {name = "[q2]Руна команды \"Взять!\"", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на поножах руну \"Убийственный выстрел\":\n\n\nВы пытаетесь добить раненую цель выстрелом, наносящим 100% урона от оружия и еще [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. \"Убийственный выстрел\" не имеет минимальной дальности применения. \"Убийственный выстрел\" мгновенно восстанавливается, когда вы применяете его против противника с уровнем здоровья 20% или менее.\n[q]\"Обучает новой способности гравировки.\""},
[209872] = {name = "Шлем драконоборца", additional_info = "Становится персональным при поднятии\nУникальный"},
[209873] = {name = "Щит драконоборца", additional_info = "Становится персональным при поднятии\nУникальный"},
[209874] = {name = "Копье драконоборца", additional_info = "Становится персональным при поднятии\nУникальный"},
[210015] = {name = "[q2]Руна яростного выпада", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на нагруднике руну \"Яростный выпад\":\n\n\nСвирепый удар, наносящий 115% урона от оружия. Способность можно применить только под действием \"Исступления\", \"Ярости берсерка\" или \"Кровавой ярости\". Другие способности ближнего боя, примененные под действием этих эффектов, сокращают время восстановления \"Яростного выпада\" на 1 сек.\n[q]\"Обучает новой способности гравировки.\""},
[210026] = {name = "Символ третьей совы", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q]\"Вы покорили морскую стихию.\""},
[210043] = {name = "Символ второй совы", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q]\"Наконец-то душа Агона обрела покой.\""},
[210044] = {name = "Символ первой совы", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q]\"Знак истинного стража.\""},
