[210080] = {name = "Подношение вуду", additional_info = "Предмет, необходимый для задания\nУникальный"},
[210137] = {name = "[q2]Руна буйного роста", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на перчатках руну \"Буйный рост\":\n\n\nИсцеляет участников группы или рейда выбранного игрока в радиусе 43.5 м от него, восполняя [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья за 7 сек. Скорость исцеления постепенно снижается на протяжении действия \"Буйного роста\".\n[q]\"Обучает новой способности гравировки.\""},
[210138] = {name = "Указ Черного Железа", additional_info = nil},
[210146] = {name = "Турбобатарея крошшера", additional_info = nil},
[210147] = {name = "Измельчитель-утилизатор", additional_info = "[q2]Использование: Позволяет извлечь запчасти из разбитого крошшера."},
[210177] = {name = "Атаерик: \"О любопытных свойствах тайной магии\"", additional_info = "Уникальный\n[q]\"Заметки знаменитого верховного мага из Кирин-Тора. Будут отлично смотреться в любой библиотеке.\""},
[210178] = {name = "[q2]Схема: измельчитель-утилизатор", additional_info = "Требует Инженерное дело (135)"},
[210179] = {name = "[q2]Заметки о заклинаниях: АЗГЕРАТРЕНЕЛЬ СЛЫДИТЫ", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Расшифровать заметки о заклинаниях, чтобы создать новый рецепт вырезания рун. Требуется образец авторского почерка."},
[210183] = {name = "Рог Кселтоса", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Издает мягкое гудение, проникающее прямо в мозг.\""},
[210186] = {name = "Подрывной заряд", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Открыть тяжелые ворота по-гоблински!"},
[210187] = {name = "Заказ Торговой Компании", additional_info = "Становится персональным при поднятии\nУникальный"},
[210188] = {name = "[q0]Рваный заказ", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Похоже, он был поврежден во время боя.\""},
[210195] = {name = "[q2]Несбалансированный идол", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Идол}\nКлассы: Друид\nТребуется 10-й ур.\n[q2]Использование: Приведите в равновесие силы луны, Изумрудного Сна и дикой природы, чтобы обучиться новой способности."},
[210209] = {name = "Парный ключ", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник"},
[210210] = {name = "[q0]Сертификат основателя \"Оборонного предприятия Гризенштерна\"", additional_info = "[q]\"Мелким шрифтом напечатано, что этот сертификат не дает права на владение акциями и не имеет юридической силы. Если закрыть эту строчку пальцем, какой-нибудь торговец, может, и купит.\""},
[210212] = {name = "Полуключ брата", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Сложить вместе полуключи брата и сестры."},
[210213] = {name = "Полуключ сестры", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Сложить вместе полуключи брата и сестры."},
[210229] = {name = "[q2]Руна расправы", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на перчатках руну \"Расправа\":\n\n\nОдновременный удар оружием в обеих руках, наносящий 95% обычного урона от оружия. Кроме того, урон от каждого оружия увеличивается еще на [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] ед. Отравленные цели получают на 20% больше урона. Длина серии приемов увеличивается на 2.\n\n \"Расправа\" взаимодействует с теми же талантами и эффектами, что и \"Удар в спину\" (кроме указанных отдельных случаев).\n[q]\"Обучает новой способности гравировки.\""},
[210250] = {name = "Золотое кольцо с гравировкой", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\n[q]\"Надпись гласит: Надень __кольца __преклони __перед __на __.\""},
[210251] = {name = "Серебряное кольцо с гравировкой", additional_info = "Становится персональным при поднятии\nУникальный\nПалец\n[q]\"Надпись гласит: __оба __и __колени __статуей __кладбище.\""},
[210252] = {name = "[q2]Руна отравляющего укола", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на перчатках руну \"Горлорез\":\n\n\nДля применения \"Внезапного удара\", \"Удара в спину\" и \"Гарроты\" больше не требуется находиться за спиной у цели. \"Удар в спину\" с вероятностью 15% позволяет применить следующий \"Внезапный удар\" в течение 10 сек. вне состояния незаметности.\n[q]\"Обучает новой способности гравировки.\""},
[210253] = {name = "[q2]Тотем гнили", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Взывает к духам стихий.\n[q]\"Традиционный тотем... но магия тьмы изуродовала и осквернила его настолько, что говорящие со стихиями едва могут его узнать.\""},
[210322] = {name = "[q2]Руна яда", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на поножах руну \"Отравление\":\n\nЗавершающий удар, наносящий мгновенный урон от яда за каждую дозу \"Смертельного яда\" на цели. \"Отравление\" повышает вероятность применить к цели \"Быстродействующий яд\" на 75% на 1 сек. и еще на 1 сек. за каждый прием серии. Один прием серии равняется одной дозе яда:\n 1 доза: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + Сила атаки * 0.072] ед. урона\n 2 дозы: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Сила атаки * 0.144] ед. урона\n 3 дозы: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Сила атаки * 0.216] ед. урона\n 4 дозы: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Сила атаки * 0.288] ед. урона\n 5 доз: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Сила атаки * 0.36] ед. урона.\n[q]\"Обучает новой способности гравировки.\""},
[210323] = {name = "Код от сейфа", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q]\"0-4-5-1\""},
[210329] = {name = "Хилсбрадская карта сокровищ", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q]\"Ступай на север, вдоль реки, мимо Альтеракских гор. То, что ты ищешь, спрятано за низвергающимися потоками.\""},
[210330] = {name = "Ценная подсказка", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"За информацию надо платить.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[210410] = {name = "Приманка из пресноводного луциана", additional_info = "Классы: Охотник\n[q2]Использование: Бросить приманку. (5 Мин Восстановление)\n[q]\"Бросьте за борт – и приманите настоящего великана!\""},
[210499] = {name = "Болотный гриб", additional_info = "[q2]Использование: Можно съесть (на свой страх и риск)."},
[210500] = {name = "[q2]Руна звезд", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на поножах руну \"Звездный поток\":\n\nОбрушивает поток звездной энергии, наносящий от [248 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)] до [304 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)] ед. урона от тайной магии и увеличивающий урон от 1 следующего применения \"Звездного огня\" на 80% на 15 сек.\n\n Большая часть эффектов и талантов, которые активируются \"Гневом\" и \"Звездным огнем\" или усиливают эти способности, также взаимодействует со \"Звездным потоком\".\n[q]\"Обучает новой способности гравировки.\""},
[210534] = {name = "[q2]Идол леса", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Идол}\nКлассы: Друид\n[q2]Выгравировать на нагруднике или мантии руну \"Дикие удары\":\n\n\nПока вы остаетесь в облике кошки, медведя или лютого медведя, участники группы или рейда в радиусе 100 м сражаются еще яростнее. Каждый удар ближнего боя с вероятностью 20% срабатывает повторно с увеличенной на 20% силой атаки. Не срабатывает, если на цель уже действует \"Тотем неистовства ветра\".\n[q]\"Обучает новой способности после того, как вы исцелите 10 разных зверей.\""},
[210568] = {name = "Ветхий талисман", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Артефакт окружает странная и зловещая аура.\""},
[210569] = {name = "[q2]Руна флагелляции", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на нагруднике руну \"Флагелляция\":\n\n\nПри получении физического урона вы накапливаете столько ярости, как если бы вы не носили брони.\n[q]\"Обучает новой способности гравировки.\""},
[210573] = {name = "[q2]Руна всепоглощающей ярости", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на поножах руну \"Неконтролируемая ярость\":\n\n\nКогда вы накапливаете более 60 ед. ярости, вы на 12 сек. впадаете в исступление, получая возможность применять требующие этого состояния способности. Кроме того, применяя \"Вихрь\" под действием исступления, вы также поражаете цели оружием в левой руке.\n[q]\"Обучает новой способности гравировки.\""},
[210589] = {name = "[q2]Эхо предков", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Шаман\n[q2]Выгравировать на поножах руну \"Наставления предков\":\n\n\nВ течение следующих 10 сек. 25% наносимого вами урона восполняют здоровье максимум 3 ближайшим участникам группы, а 100% творимого вами исцеления наносятся как урон последней цели \"Огненного шока\".\n[q]\"Обучает новой способности гравировки.\""},
[210596] = {name = "[q2]Руна броска кобры", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на нагруднике или мантии руну \"Бросок кобры\":\n\n\nКогда ваши способности-выстрелы и способности-удары, а также \"Укус мангуста\" наносят критический удар, следующие 2 особые атаки вашего питомца также наносят критические удары.\n[q]\"Обучает новой способности гравировки.\""},
[210653] = {name = "[q2]Руна главного аргумента", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на перчатках руну \"Главный аргумент\":\n\n\nВы атакуете оружием в левой руке, нанося обычный урон и повышая вероятность парирования на 100% на 5 сек. или до первого успешного парирования. \"Главный аргумент\" на 20 сек. снижает затраты энергии на применение \"Коварного удара\" на 20 ед. и повышает уровень создаваемой им угрозы на 50%, а также дает эффекты \"Держать удар\" и увеличивает урон от \"Коварного удара\" и \"Потрошения\" на 50%. Продлевает серию приемов на 1.\n\n \"Главный аргумент\" взаимодействует с большинством тех же талантов и эффектов, что и \"Коварный удар\". Эффект \"Главного аргумента\" не усиливает сам \"Главный аргумент\" и не уменьшает его стоимость.\n[q]\"Обучает новой способности гравировки.\""},
[210654] = {name = "[q2]Заметки о заклинаниях: перемотка времени", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Выгравировать на наручах руну \"Перемотка времени\":\n\n\nТекущая цель с \"Темпоральным маяком\" мгновенно восстанавливает все здоровье, потерянное за последние 5 сек. Не действует на цели, которые получили эффект \"Темпоральный маяк\" менее 5 сек. назад.\n[q]\"Обучает новой способности гравировки.\""},
[210655] = {name = "[q2]Заметки о заклинаниях: РЕМОВРЕНИ МЕТКАПЕ", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Расшифровать заметки о заклинаниях с помощью заклятья понимания, чтобы выучить новое заклинание гравировки."},
[210665] = {name = "Частица проливной ярости", additional_info = "Становится персональным при поднятии\nУникальный"},
[210667] = {name = "Частица инфернальной ярости", additional_info = "Становится персональным при поднятии\nУникальный"},
[210668] = {name = "Частица сейсмической ярости", additional_info = "Становится персональным при поднятии\nУникальный"},
[210696] = {name = "[q2]Погибель Гнилошкуров", additional_info = "Становится персональным при поднятии\n{Правая рука} {Меч}\n{Урон: 18-34 } {Скорость 2.60}\n(10.00 ед. урона в секунду)\nПрочность: 60 / 60\nКлассы: Воин\nТребуется 14-й ур.\n[q]\"Клинок весь покрыт запекшейся кровью. Он больше не блестит на солнце, зато отпугивает врагов.\""},
[210708] = {name = "Эликсир накопившегося сожаления", additional_info = "Требуется 20-й ур.\n[q2]Использование: Позволяет поговорить с мертвецом, у которого остались незавершенные дела в мире смертных. Также помогает от несварения. (3 Сек Восстановление)"},
[210709] = {name = "[q2]Рецепт: эликсир накопившегося сожаления", additional_info = "Требует Алхимия (90)\n[q2]Использование: Обучает приготовлению эликсира накопившегося сожаления.\nЭликсир накопившегося сожаления\nТребуется 20-й ур.\n[q2]Использование: Позволяет поговорить с мертвецом, у которого остались незавершенные дела в мире смертных. Также помогает от несварения. (3 Сек Восстановление)\nТребуется: Удавник (5), Освинцованная колба , Могильный мох (5), Пыль духа"},
[210712] = {name = "Эликсир прозрения", additional_info = "Становится персональным при поднятии\n[q2]Использование: Узрите видение у костра Дже'неу."},
[210713] = {name = "Истерзанная душа", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Использование: Совершает кровавое подношение, чтобы освободить истерзанную душу."},
[210724] = {name = "Посох Хирзека", additional_info = "Становится персональным при поднятии"},
[210741] = {name = "[q3]Автоматический пробойник толпы", additional_info = "Становится персональным при поднятии\n{Двуручное} {Дробящее}\n{Урон: 53-85 } {Скорость 2.00}\n(34.50 ед. урона в секунду)\n+22 к силе\n+8 к ловкости\nПрочность: 100 / 100\nКлассы: Паладин , Шаман , Друид\nТребуется 40-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 69 ед. в облике кошки, медведя и лютого медведя.\n[q2]Использование: Повышает скорость атаки на 50% на 30 сек. Не действует на персонажей выше 55-го уровня. (3 Мин Восстановление)\n[q]\"Модель этого года получила ряд усовершенствований.\""},
[210746] = {name = "[q2]Руна щита земли", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Шаман\n[q2]Выгравировать на поножах руну \"Щит земли\":\n\n\nЗащищает цель земляным щитом, который сокращает задержку применения и поддержания заклинаний при получении урона на 30%. Кроме того, когда защищенная цель становится целью атаки, она восполняет [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] ед. здоровья. Этот эффект срабатывает не чаще раза в несколько секунд. 9заряд:заряда:зарядов;. Время действия – 10 мин. \"Щит земли\" можно единовременно применить только к одной цели.\n[q]\"Обучает новой способности гравировки.\""},
[210763] = {name = "Ветвь Алтека", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Обломок могущественного артефакта. Похоже, это половина расколотого великого оружия.\""},
[210765] = {name = "Сфера Дес", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Внутри сферы мерцают всполохи пламени и темной магии, завораживая и внушая тревогу. Похоже, это половина расколотого великого оружия.\""},
[210771] = {name = "[q2]Перехват припасов: медные слитки", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 20 медными слитками:медными слитками."},
[210772] = {name = "[q2]Партия припасов: медные слитки", additional_info = "Становится персональным при поднятии\nУникальный: [Supply Shipment] (1)\n[q]\"Доставьте эти припасы интенданту, чтобы получить щедрую награду.\""},
[210773] = {name = "[q3]Оплечье Второй войны", additional_info = "Становится персональным при надевании\n{Плечо} {Кольчуга}\nБроня: 163\n+8 к выносливости\nПрочность: 70 / 70\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами светлой магии, на 11 ед."},
[210779] = {name = "[q2]Чертеж: оплечье Второй войны", additional_info = "Становится персональным при поднятии\nТребует Кузнечное дело (150)\n[q2]Использование: Обучает изготовлению оплечья Второй войны.\n[q3]Оплечье Второй войны\nСтановится персональным при надевании\n{Плечо} {Кольчуга}\nБроня: 163\n+8 к выносливости\nПрочность: 70 / 70\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами светлой магии, на 11 ед.\nТребуется: Бронзовый слиток (20), Моховой агат (2), Малый лунный камень (2), Радужная жемчужина (2), Серебряный слиток (4)"},
[210781] = {name = "[q3]Повязки феникса", additional_info = "Становится персональным при надевании\n{Запястья} {Ткань}\nБроня: 21\nПрочность: 30 / 30\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение наносимого урона от заклинаний и эффектов огня не более чем на 13 ед."},
[210794] = {name = "[q4]Изменчивая серебряная кираса", additional_info = "Становится персональным при поднятии\nУникальный использующийся: [Void-Touched] (1)\n{Грудь} {Кольчуга}\nБроня: 238\n+12 к силе\n+5 к выносливости\nПрочность: 145 / 145\nТребуется 25-й ур.\nТребует Кузнечное дело (100)\n[q2]Если на персонаже: Этот предмет заряжен чистой энергией Бездны. Тот, кто атакует его владельца, с высоким шансом получает ужасное проклятие, увеличивающее получаемый урон на 15 секунд. (Вероятность срабатывания: 25%)\n[q2]Если на персонаже: Повышает вероятность попадания атак и заклинаний на 1%."},
[210795] = {name = "[q4]Экстрапланарные сапоги из паучьего шелка", additional_info = "Становится персональным при поднятии\nУникальный использующийся: [Void-Touched] (1)\n{Ступни} {Ткань}\nБроня: 35\n+5 к выносливости\n+5 к интеллекту\n+6 к духу\nПрочность: 50 / 50\nТребуется 25-й ур.\nТребует Портняжное дело (100)\n[q2]Использование: Вы перемещаетесь в другую реальность, мгновенно снизив уровень угрозы. Кроме того, вы в течение 6 сек. получаете и наносите на 30% меньше урона. (10 Мин Восстановление)\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 7 ед.\n[q2]Если на персонаже: Повышает вероятность попадания атак и заклинаний на 1%."},
[210811] = {name = "[q2]Руна первозданного неистовства", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Шаман\n[q2]Выгравировать на поножах руну \"Улучшенный призрачный волк\":\n\n\nСпособность \"Призрачный волк\" действует внутри помещений и уменьшает получаемый урон на 10%.\n[q]\"Обучает новой способности гравировки.\""},
[210817] = {name = "[q2]Руна выживания", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на нагруднике или мантии руну \"Выживание сильнейших\":\n\n\nУменьшает вероятность получить критический удар в ближнем бою на 6% и уменьшает получаемый урон на 10%. В облике медведя или лютого медведя урон уменьшается еще на 10%.\n[q]\"Обучает новой способности гравировки.\""},
[210818] = {name = "[q2]Руна одинокого волка", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на нагруднике или мантии руну \"Одинокий волк\":\n\n\nВаши атаки наносят на 25% больше урона, пока у вас нет активного питомца.\n[q]\"Обучает новой способности гравировки.\""},
[210820] = {name = "[q2]Руна жертвенности", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]Выгравировать на поножах руну \"Длань жертвенности\":\n\n\nНакладывает на участника группы или рейда эффект, перенаправляющий 30% получаемого им урона заклинателю. Длится 12 сек или до тех пор, пока заклинатель не передаст 100% от своего запаса здоровья.\n[q]\"Обучает новой способности гравировки.\""},
[210822] = {name = "[q2]Гармоничное прозрение", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на нагруднике или мантии руну \"Прозорливость\":\n\n\nКогда \"Быстрое исцеление\" восстанавливает здоровье, время произнесения следующего \"Малого исцеления\", \"Большего исцеления\" или \"Молитвы исцеления\" сокращается на 20% на 20 сек. Суммируется до 3 раз.\n[q]\"Обучает новой способности гравировки.\""},
[210823] = {name = "[q2]Руна специализации на бое с оружием в обеих руках", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Шаман\n[q2]Выгравировать на нагруднике или мантии руну \"Специализация на бое с оружием в обеих руках\":\n\n\nКогда вы сражаетесь с оружием в обеих руках, вероятность попадания заклинаниями и атаками ближнего боя повышается на 5%. Кроме того, \"Удар бури\" теперь позволяет атаковать оружием в обеих руках, а также увеличивает урон оружия в левой руке на 60%.\n[q]\"Обучает новой способности гравировки.\""},
[210824] = {name = "[q2]Руна пакта", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на поножах руну \"Демонический союз\":\n\n\nВаши заклинания огня и темной магии наносят на 10% больше урона, а критические удары вашего прислужника дают участникам группы или рейда эффект \"Демонический союз\" на 45 сек. \"Демонический союз\" увеличивает урон от заклинаний и силу исцеления на 10% от вашего бонуса к урону от заклинаний или на ( 60 / 2) – в расчет принимается наибольший показатель. Не работает с порабощенными демонами.\n[q]\"Обучает новой способности гравировки.\""},
[210825] = {name = "[q2]Руна вестника войны", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на нагруднике руну \"Вестник войны\":\n\n\nПозволяет применять способности \"Рывок\", \"Перехват\" и \"Вмешательство\" во время боя и в любой стойке. Кроме того, эти способности снимают все затрудняющие передвижение эффекты.\n[q]\"Обучает новой способности гравировки.\""},
[210953] = {name = "Глаз Бхосски", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Хотя глаз не живой, вам кажется, что за вами следят...\""},
[210955] = {name = "Форма посвященного из Алого ордена", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Замаскируйтесь, приняв облик рыцаря Алого ордена. Подозрительные действия нарушат маскировку."},
[210963] = {name = "Ключ Провидцев", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник"},
[210966] = {name = "Кровь Легиона", additional_info = "Предмет, необходимый для задания\nУникальный (10)\n[q]\"Темная и густая... Эта кровь связана с великими командирами Легиона.\""},
[210967] = {name = "Секретное послание", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[210968] = {name = "Ключ реликвария", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник"},
[210979] = {name = "[q2]Руна шага сквозь тень", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на поясе руну \"Шаг сквозь тень\":\n\n\nВы проходите сквозь тень и появляетесь за спиной у противника. Скорость передвижения повышается на 70% на 3 сек.\n[q]\"Обучает новой способности гравировки.\""},
[210980] = {name = "[q2]Руна метаморфозы", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на перчатках руну \"Метаморфоза\":\n\n\nПревращает вас в демона, усиливая броню на 500%, увеличивая запас здоровья на 15%, снижая вероятность получить критический урон на 6%, повышая уровень создаваемой угрозы на 50% и увеличивая количество маны, получаемое от \"Жизнеотвода\", на 100%, но уменьшая наносимый вами урон на 10%. \"Метаморфоза\" меняет действие некоторых способностей и дает вам новые:\n\n \"Жгучая боль\": теперь применяется мгновенно.\n\n \"Стрела Тьмы\": меняется на \"Теневой рассекающий удар\" – атаку ближнего боя, наносящую максимум 10 противникам:противникам урон от темной магии, но требующую 6 сек. на восстановление.\n\n \"Страх\": меняется на \"Устрашение\".\n\n\nПровоцирует цель, заставляя ее атаковать вас. Не действует, если вы уже сражаетесь с целью.\n\n Демонический прыжок\n\n\nДемон бросается к противнику и оглушает его на 1 сек. Не действует во время боя.\n\n Демонический вой\n\n\nЗаставляет находящихся рядом противников атаковать вас в течение 6 сек.\n[q]\"Обучает новой способности гравировки.\""},
[211205] = {name = "[q2]Руна убийцы кобр", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на перчатках руну \"Убийца кобр\":\n\n\nТеперь каждая атака ближнего боя может с вероятностью 10% вызвать срабатывание \"Укуса мангуста\", при этом \"Укус мангуста\" срабатывает с вероятностью 100%, если противник уклоняется. Вероятность постепенно возрастает на 10% с каждой атакой, если не происходит срабатывание. При срабатывании вероятность возвращается к исходному значению. Также \"Укус мангуста\" наносит дополнительный урон в размере 45% вашей силы атаки.\n[q]\"Обучает новой способности гравировки.\""},
[211247] = {name = "[q2]Выкройка: повязки феникса", additional_info = "Становится персональным при поднятии\nТребует Портняжное дело (125)\n[q2]Использование: Обучает изготовлению повязок феникса.\n[q3]Повязки феникса\nСтановится персональным при надевании\n{Запястья} {Ткань}\nБроня: 21\nПрочность: 30 / 30\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение наносимого урона от заклинаний и эффектов огня не более чем на 13 ед.\nТребуется: Рулон шерсти (6), Бурдюк с маслом (2), Тонкая нить (2)"},
[211263] = {name = "[q0]Нагрудный доспех правосудия", additional_info = "Становится персональным при поднятии\n{Грудь} {Латы}\nБроня: 857\n+17 к силе\n+25 к выносливости\n+20 к интеллекту\nУстойчивость: +10 Огонь\nУстойчивость: +10 Природа\nПрочность: 165 / 165\nКлассы: Паладин\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 6 ед.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 14 ед.\n[q2]Если на персонаже: Увеличение показателя блока щитом на 32 ед.\n\n[q]Оплот правосудия (0/1)\n[q0]Нагрудный доспех правосудия\n[q0](3) Набор : Ваша \"Аура благочестия\" также уменьшает урон, получаемый от заклинаний, на 5%.\n(5) Набор : \"Правосудие\" дополнительно создает 50% угрозы для своей цели.\n(8) Набор : Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 47 ед."},
[211269] = {name = "Примитивный рисунок", additional_info = "Становится персональным при поднятии\nЭтот предмет позволяет получить задание."},
[211273] = {name = "Пойманный зверек", additional_info = "Становится персональным при поднятии\n[q2]Использование: Разместить зверька-приманку."},
[211301] = {name = "[q2]Руна выявления слабости", additional_info = "Становится персональным при поднятии\nКлассы: Охотник\n[q2]Выгравировать на поясе руну \"Выявление слабости\":\n\n\nКритические атаки в ближнем и дальнем бою повышают силу атаки на 40% от текущего показателя ловкости на 7 сек.\n[q]\"Обучает новой способности гравировки.\""},
[211315] = {name = "[q2]Перехват припасов: тонкая кожа", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 14 кусками тонкой кожи:кусками тонкой кожи."},
[211316] = {name = "[q2]Перехват припасов: мироцвет", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 20 пучками мироцвета:пучками мироцвета."},
[211317] = {name = "[q2]Перехват припасов: сребролист", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 20 пучками сребролиста:пучками сребролиста."},
[211318] = {name = "[q2]Перехват припасов: слабые лечебные зелья", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 20 слабыми лечебными зельями:слабыми лечебными зельями."},
[211319] = {name = "[q2]Перехват припасов: медные короткие мечи", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 6 медными короткими мечами:медными короткими мечами."},
[211320] = {name = "[q2]Перехват припасов: рунические медные штаны", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 3 руническими медными штанами."},
[211321] = {name = "[q2]Перехват припасов: малые магические жезлы", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 2 малыми магическими жезлами:малыми магическими жезлами."},
[211322] = {name = "[q2]Перехват припасов: слабое волшебное масло", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 2 флаконами слабого волшебного масла:флаконами слабого волшебного масла."},
[211323] = {name = "[q2]Перехват припасов: грубые медные бомбы", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 12 грубыми медными бомбами:грубыми медными бомбами."},
[211324] = {name = "[q2]Перехват припасов: грубо сработанные огнестрелы", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 3 грубо сработанными огнестрелами:грубо сработанными огнестрелами."},
[211325] = {name = "[q2]Перехват припасов: рукодельные кожаные пояса", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 5 рукодельными кожаными поясами:рукодельными кожаными поясами."},
[211326] = {name = "[q2]Перехват припасов: тисненые кожаные жилеты", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 3 тиснеными кожаными жилетами:тиснеными кожаными жилетами."},
[211327] = {name = "[q2]Перехват припасов: коричневые льняные штаны", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 6 коричневыми льняными штанами."},
[211328] = {name = "[q2]Перехват припасов: коричневые льняные одеяния", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 4 коричневыми льняными одеяниями."},
[211329] = {name = "[q2]Перехват припасов: яйца с травами", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 20 яйцами с травами:яйцами с травами."},
[211330] = {name = "[q2]Перехват припасов: волчатина с пряностями", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 20 кусками волчатины с пряностями:кусками волчатины с пряностями."},
[211331] = {name = "[q2]Перехват припасов: блестящая рыбка", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 20 блестящими рыбками:блестящими рыбками."},
[211332] = {name = "[q2]Перехват припасов: плотные льняные бинты", additional_info = "Становится персональным при поднятии\nУникальный: [Waylaid Shipment] (12)\n[q2]Использование: Пополняет припасы 10 плотными льняными бинтами:плотными льняными бинтами."},
[211365] = {name = "[q2]Партия припасов", additional_info = "Становится персональным при поднятии\n[q]\"Доставьте эти припасы интенданту, чтобы получить щедрую награду.\""},
[211367] = {name = "[q2]Партия припасов", additional_info = "Становится персональным при поднятии\n[q]\"Доставьте эти припасы интенданту, чтобы получить щедрую награду.\""},
[211368] = {name = "[q2]Партия припасов", additional_info = "Становится персональным при поднятии\n[q]\"Доставьте эти припасы интенданту, чтобы получить щедрую награду.\""},
[211382] = {name = "Маленькая сумка курьера", additional_info = "Становится персональным при поднятии\nУникальный\nСумка (ячеек: 10)"},
[211384] = {name = "[q2]Прочная сумка курьера", additional_info = "Становится персональным при поднятии\nУникальный\nСумка (ячеек: 12)"},
[211385] = {name = "[q2]Руна распространяющегося укуса", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Охотник\n[q2]Выгравировать на поножах руну \"Распространяющийся укус\":\n\n\nВаш \"Залп\" также применяет к пораженным целям \"Укус змеи\" на 12 сек.\n[q]\"Обучает новой способности гравировки.\""},
[211386] = {name = "[q2]Заметки о заклинаниях: чародейский выброс", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Выгравировать на поножах руну \"Чародейский выброс\":\n\nКонцентрирует всю оставшуюся ману и выпускает в цель поток энергии, наносящий [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 226 / 100]-[(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 264 / 100] ед. урона от тайной магии. Чем больше остается маны, тем выше урон, вплоть до прибавки в 300%. После этого вы вновь начинаете восстанавливать ману, а скорость восстановления повышается на 300% на 8 сек.\n[q]\"Обучает новой способности гравировки.\""},
[211387] = {name = "[q2]Руна манящего света", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]Выгравировать на перчатках руну \"Частица Света\":\n\n\nНаделяет выбранного игрока частицей Света. Любое исцеление, которое вы применяете к участникам группы или рейда в радиусе 40 м от цели, также применяется к выбранному игроку с эффективностью 75%. Частицей Света можно наделить только одну цель. Время действия – 1 ч.\n[q]\"Обучает новой способности гравировки.\""},
[211390] = {name = "[q2]Руна провокации", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на нагруднике или мантии руну \"Просто царапина\":\n\n\n\"\"Во время действия \"Танца клинков\" вы получаете на 20% меньше физического урона. Получаемый урон уменьшается еще на 1% за каждые 12 ед. навыка защиты, превышающие ( 60 * 5). Вероятность уклонения становится равна 50% обычной, вероятность получить критический урон от атак ближнего боя снижается на 6%, наносимый вами урон уменьшается на 20%, уровень угрозы от любых действий значительно повышается, а способность \"Ложный выпад\" заменяется на \"Издевку\", которая провоцирует цель атаковать вас.\n\n\nПровоцирует цель, заставляя ее атаковать вас. Не действует, если вы уже сражаетесь с целью. \"\"\n[q]\"Обучает новой способности гравировки.\""},
[211391] = {name = "[q2]Руна целительных ливней", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Шаман\n[q2]Выгравировать на нагруднике или мантии руну \"Целительный ливень\":\n\n\nВосполняет цели и участникам ее группы в радиусе 15 м [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] ед. здоровья в секунду.\n[q]\"Обучает новой способности гравировки.\""},
[211392] = {name = "[q2]Руна беспрерывного колдовства", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на поножах руну \"Беспрерывное колдовство\":\n\n\n\"Похищение жизни\", \"Похищение души\", \"Стрела Тьмы\", \"Теневой рассекающий удар\", \"Жгучая боль\", \"Испепеление\" и \"Блуждающий дух\" полностью обновляют время действия \"Порчи\" на цели.\n[q]\"Обучает новой способности гравировки.\""},
[211393] = {name = "[q2]Руна свирепой неистовости", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Воин\n[q2]Выгравировать на перчатках руну \"Свирепая неистовость\":\n\n\nКогда вы сражаетесь с оружием в обеих руках, ваша скорость передвижения повышается на 10%, а скорость атаки – на 4% каждый раз, когда ваш удар в ближнем бою попадает по той же цели, что и предыдущий. Суммируется до 5 раз. Длится 10 сек. или пока вы не нанесете удар по другой цели.\n[q]\"Обучает новой способности гравировки.\""},
[211419] = {name = "[q2]Пригоршня изменчивой чешуи", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Эти любопытные чешуйки слегка переливаются, будто не совсем материальны. Это определенно влияние необычной магии... Вот бы найти кого-нибудь, кто что-то об этом знает.\""},
[211420] = {name = "[q3]Талисман из изменчивой чешуи", additional_info = "Становится персональным при поднятии\nАксессуар\n+5 к духу\nТребуется 25-й ур.\n[q2]Если на персонаже: Защищает от эффектов \"Сокрушающей тьмы\"."},
[211421] = {name = "Коробка", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Попытаться уничтожить Коробку с помощью могучего источника Света.\n[q]\"Прикоснувшись к коробке голыми руками, вы тут же ощущаете тревогу глубоко в душе... а еще прилив вдохновения, какого не испытывали никогда раньше.\""},
[211422] = {name = "[q4]Осколок Бездны", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Все, что осталось от коробки, – маленький осколок идеально черного кристалла. Похоже, он притягивает и поглощает свет.\""},
[211423] = {name = "[q4]Меченные Бездной кожаные перчатки", additional_info = "Становится персональным при поднятии\nУникальный использующийся: [Void-Touched] (1)\n{Кисти рук} {Кожа}\n[q2]Броня: 110\n+6 к ловкости\n+6 к выносливости\n+4 к духу\nПрочность: 70 / 70\nТребуется 25-й ур.\nТребует Кожевничество (100)\n[q2]Если на персонаже: Повышает вероятность попадания атак и заклинаний на 1%.\n[q2]Использование: Погрузиться в пучины безумия, увеличивая скорость атаки на 10%, а также повышая уровень создаваемой вами угрозы на 10 сек. (10 Мин Восстановление)"},
[211427] = {name = "[q3]Вместилище души", additional_info = "[q]\"Позволяет пленить души демонов и извлекать из них силу.\""},
[211443] = {name = "[q2]Клинок ярости", additional_info = "Становится персональным при поднятии\n{Двуручное} {Меч}\n{Урон: 31-47 } {Скорость 3.50}\n(11.14 ед. урона в секунду)\nБроня: 50\n+3 к силе\nПрочность: 60 / 60\nТребуется 13-й ур."},
[211444] = {name = "[q2]Плащ призывателя", additional_info = "Становится персональным при поднятии\nСпина\nБроня: 16\n+3 к интеллекту\n+1 к духу\nТребуется 13-й ур."},
[211445] = {name = "[q2]Изогнутый лук варвара", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Лук}\n{Урон: 12-24 } {Скорость 2.40}\n(7.50 ед. урона в секунду)\nПрочность: 50 / 50\nТребуется 13-й ур."},
[211447] = {name = "Партия оружия", additional_info = "Предмет, необходимый для задания\nУникальный"},
[211448] = {name = "Подписанный контракт на поставку", additional_info = "Предмет, необходимый для задания\nУникальный"},
[211449] = {name = "[q3]Жемчужина Бездны мстителя", additional_info = "Становится персональным при поднятии\nУникальный: [Void Pearl] (1)\nАксессуар\nУстойчивость: +10 Тьма\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 18."},
[211450] = {name = "[q3]Жемчужина Бездны призывателя", additional_info = "Становится персональным при поднятии\nУникальный: [Void Pearl] (1)\nАксессуар\nУстойчивость: +10 Тьма\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 11 ед."},
[211451] = {name = "[q3]Жемчужина Бездны послушника", additional_info = "Становится персональным при поднятии\nУникальный: [Void Pearl] (1)\nАксессуар\nУстойчивость: +10 Тьма\nТребуется 25-й ур.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 20 ед."},
[211452] = {name = "[q3]Идеальная жемчужина из Непроглядной Пучины", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 25-й ур.\n[q]\"Аку'май, служившая древним богам, мертва. Башане Рунический Тотем будет интересно об этом узнать.\""},
[211454] = {name = "Странная водяная сфера", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 25-й ур."},
[211455] = {name = "[q3]Стильные перчатки без пальцев", additional_info = "Становится персональным при поднятии\n{Кисти рук} {Кожа}\nБроня: 68\n+7 к выносливости\n+5 к интеллекту\nПрочность: 35 / 35\nТребуется 25-й ур.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 22 ед.\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами сил природы, на 14 ед."},
[211456] = {name = "[q3]Кинжал добровольной жертвы", additional_info = "Становится персональным при поднятии\nУникальный\n{Правая рука} {Кинжал}\n{Урон: 12-27 } {Скорость 1.50}\n(13.00 ед. урона в секунду)\nБроня: 60\n+4 к выносливости\n+3 к интеллекту\nПрочность: 65 / 65\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 12 ед."},
[211457] = {name = "[q3]Ремень сумеречного защитника", additional_info = "Становится персональным при поднятии\n{Пояс} {Кольчуга}\nБроня: 128\n+7 к силе\n+9 к выносливости\nПрочность: 40 / 40\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 4 ед."},
[211458] = {name = "[q3]Фолиант защиты от темной магии", additional_info = "Становится персональным при поднятии\nЛевая рука\nБроня: 40\n+4 к выносливости\n+3 к интеллекту\nУстойчивость: +5 Тьма\nТребуется 25-й ур."},
[211460] = {name = "[q3]Древний арктический кулачный щит", additional_info = "Становится персональным при поднятии\n{Левая рука} {Щит}\nБроня: 725\nБлокирование: 15\n+7 к выносливости\n+8 к духу\nУстойчивость: +5 Лед\nПрочность: 100 / 100"},
[211461] = {name = "[q3]Покрытый письменами надгробный скипетр", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Жезл}\n{35 - 61 ед. |3-6(тьма)} {Скорость 1.50}\n(32.00 ед. урона в секунду)\n+1 к духу\nУстойчивость: +5 Тьма\nПрочность: 65 / 65"},
[211462] = {name = "[q3]Кольцо вечного воодушевления", additional_info = "Становится персональным при поднятии\nПалец\n+3 к выносливости\n+8 к духу"},
[211463] = {name = "[q3]Застежки стрекочущего жука", additional_info = "Становится персональным при поднятии\n{Запястья} {Кольчуга}\nБроня: 95\n+4 к ловкости\n+7 к выносливости\nПрочность: 40 / 40\nТребуется 25-й ур."},
[211464] = {name = "[q3]Изношенная накидка прелата", additional_info = "Становится персональным при поднятии\nСпина\nБроня: 24\n+9 к духу"},
[211465] = {name = "[q3]Ореольные сапоги проницательности", additional_info = "Становится персональным при поднятии\n{Ступни} {Ткань}\nБроня: 34\n+2 к ловкости\n+5 к интеллекту\n+4 к духу\nПрочность: 35 / 35"},
[211466] = {name = "[q3]Ремень сердцевины древуна", additional_info = "Становится персональным при поднятии\n{Пояс} {Кожа}\nБроня: 57\n+8 к выносливости\n+7 к духу\nПрочность: 30 / 30"},
[211467] = {name = "[q3]Кольцо железного кулака", additional_info = "Становится персональным при поднятии\nПалец\n+4 к силе\n+7 к ловкости"},
[211468] = {name = "[q3]Изношенное оплечье Гнедого", additional_info = "Становится персональным при поднятии\n{Плечо} {Ткань}\nБроня: 30\n+2 к выносливости\n+6 к интеллекту\nПрочность: 40 / 40\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 5 ед."},
[211471] = {name = "Ключ от сундука, найденного у реки Скалистой", additional_info = "Уникальный"},
[211472] = {name = "[q2]Манускрипт изгнания", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Манускрипт}\nКлассы: Паладин\n[q2]Выгравировать на поножах руну \"Владение аурами\":\n\n\n\"Аура сосредоточенности\" дает целям невосприимчивость к немоте и эффектам прерывания. Эффективность других аур повышается на 100%. Время действия – 6 сек.\n[q]\"Обучает новой способности, после того как вы примените \"Изгнание нежити\" к 5 врагам, а затем убьете их с помощью \"Экзорцизма\".\""},
[211476] = {name = "[q2]Руна пробуждения огня", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на нагруднике или мантии руну \"Огненное озеро\":\n\n\n\"Огненный ливень\" больше не нужно поддерживать, но его время восстановления становится равно 8 сек.\n[q]\"Обучает новой способности гравировки.\""},
[211477] = {name = "[q2]Руна испепеления", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Чернокнижник\n[q2]Выгравировать на наручах руну \"Испепеление\":\n\n\nОбжигает противника, нанося ему от [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] до [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] ед. урона и увеличивая наносимый урон от огня на 40% на 15 сек.\n[q]\"Обучает новой способности гравировки.\""},
[211482] = {name = "Подношение Пронзающего Копья", additional_info = "Становится персональным при поднятии\nУникальный"},
[211487] = {name = "[q2]Взрывчатка", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Позволяет установить впереди себя бомбу, которая взрывается через короткое время.\n[q]\"Похоже, может пригодиться только для расчистки обломков.\""},
[211488] = {name = "[q2]Руна мстителя", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]Выгравировать на поножах руну \"Щит мстителя\":\n\n\nБросает в противника священный щит, наносящий от [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Сила заклинаний + 0.091 * Сила атаки] до [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Сила заклинаний + 0.091 * Сила атаки] ед. урона от светлой магии и вызывающий головокружение. Щит затем перескакивает на других находящихся поблизости противников. Максимальное количество целей – 3. Время действия – 5 сек.\n[q]\"Обучает новой способности гравировки.\""},
[211490] = {name = "[q2]Пророчество о тысяче огней", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на перчатках руну \"Круг исцеления\":\n\n\nИсцеляет участников группы или рейда выбранного игрока в радиусе 43.5 м от него, восполняя [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100]-[(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] ед. здоровья.\n[q2]Использование: Сосредоточиться на пророчестве, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о двух духовных тайнах Азерота.\n[q]\"Обучает новой способности гравировки.\""},
[211491] = {name = "[q4]Бездонная сумка из кожи мурлока", additional_info = "Становится персональным при поднятии\nУникальный\nСумка (ячеек: 14)"},
[211492] = {name = "[q4]Сумка Келриса", additional_info = "Становится персональным при поднятии\nСумка душ (ячеек: 16)\nКлассы: Чернокнижник"},
[211498] = {name = "[q3]Саблезуб Стражей для ученика", additional_info = "Становится персональным при поднятии\nСредство передвижения\nТребуется любая раса Альянса\nТребуется 25-й ур.\n[q2]Использование: Призывает саблезуба Стражей ученика. Можно использовать только в Ясеневом лесу. (3 Сек Восстановление)"},
[211499] = {name = "[q3]Ездовой волк для ученика", additional_info = "Становится персональным при поднятии\nСредство передвижения\nТребуется любая раса Орды\nТребуется 25-й ур.\n[q2]Использование: Призывает ездового волка ученика. Можно использовать только в Ясеневом лесу. (3 Сек Восстановление)"},
[211500] = {name = "[q3]Прочная тканевая повязка", additional_info = "Становится персональным при поднятии\nУникальный\n{Голова} {Ткань}\nБроня: 50\nПрочность: 50 / 50\nТребуется 20-й ур.\n[q2]Если на персонаже: Уменьшает получаемый урон и вероятность получить критический удар на 5% в ущелье Песни Войны."},
[211501] = {name = "[q4]Нагрудный доспех мощи", additional_info = "Становится персональным при поднятии\n{Грудь} {Латы}\nБроня: 749\n+27 к силе\n+18 к выносливости\nУстойчивость: +10 Огонь\nПрочность: 165 / 165\nКлассы: Воин\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%."},
[211502] = {name = "[q4]Меченные Бездной кожаные рукавицы", additional_info = "Становится персональным при поднятии\nУникальный использующийся: [Void-Touched] (1)\n{Кисти рук} {Кожа}\nБроня: 70\n+5 к выносливости\n+7 к интеллекту\n+6 к духу\nПрочность: 70 / 70\nТребуется 25-й ур.\nТребует Кожевничество (100)\n[q2]Если на персонаже: Повышает вероятность попадания атак и заклинаний на 1%.\n[q2]Использование: Погрузиться в пучины безумия, увеличивая урон от заклинаний на 10%, а также повышая уровень создаваемой вами угрозы на 10 сек. (10 Мин Восстановление)"},
[211504] = {name = "[q3]Цепь сумеречного мстителя", additional_info = "Становится персональным при поднятии\n{Грудь} {Кольчуга}\nБроня: 218\n+9 к силе\n+6 к ловкости\n+8 к выносливости\nПрочность: 120 / 120\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 4 ед.\n\n[q]Кольчуга мстителя из Непроглядной Пучины (0/3)\n[q0]Сапоги сумеречного мстителя\nЦепь сумеречного мстителя\nШлем сумеречного мстителя\n[q0](2) Набор : Увеличивает силу атаки на 12.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211505] = {name = "[q0]Шлем сумеречного мстителя", additional_info = "Становится персональным при поднятии\n{Голова} {Кольчуга}\nБроня: 176\n+9 к силе\n+11 к ловкости\n+3 к выносливости\nПрочность: 70 / 70\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 4 ед.\n\n[q]Кольчуга мстителя из Непроглядной Пучины (0/3)\n[q0]Сапоги сумеречного мстителя\nЦепь сумеречного мстителя\nШлем сумеречного мстителя\n[q0](2) Набор : Увеличивает силу атаки на 12.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211506] = {name = "[q3]Сапоги сумеречного мстителя", additional_info = "Становится персональным при поднятии\n{Ступни} {Кольчуга}\nБроня: 150\n+10 к силе\n+5 к выносливости\nПрочность: 60 / 60\nТребуется 25-й ур.\n\n[q]Кольчуга мстителя из Непроглядной Пучины (0/3)\n[q0]Сапоги сумеречного мстителя\nЦепь сумеречного мстителя\nШлем сумеречного мстителя\n[q0](2) Набор : Увеличивает силу атаки на 12.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211507] = {name = "[q3]Клобук сумеречного повелителя стихий", additional_info = "Становится персональным при поднятии\n{Голова} {Кожа}\nБроня: 84\n+9 к выносливости\n+10 к интеллекту\nПрочность: 60 / 60\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 8 ед.\n\n[q]Покровы повелителя стихий из Непроглядной Пучины (0/3)\n[q0]Клобук сумеречного повелителя стихий\nСапоги сумеречного повелителя стихий\nОдеяния сумеречного повелителя стихий\n[q0](2) Набор : Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 12 ед.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211508] = {name = "[q3]Сапоги сумеречного повелителя стихий", additional_info = "Становится персональным при поднятии\n{Ступни} {Кожа}\nБроня: 71\n+5 к ловкости\n+7 к интеллекту\n+7 к духу\nПрочность: 55 / 55\nТребуется 25-й ур.\n\n[q]Покровы повелителя стихий из Непроглядной Пучины (0/3)\n[q0]Клобук сумеречного повелителя стихий\nСапоги сумеречного повелителя стихий\nОдеяния сумеречного повелителя стихий\n[q0](2) Набор : Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 12 ед.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211509] = {name = "[q0]Одеяния сумеречного повелителя стихий", additional_info = "Становится персональным при поднятии\n{Грудь} {Кожа}\nБроня: 103\n+10 к выносливости\n+10 к интеллекту\nПрочность: 100 / 100\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 7 ед.\n\n[q]Покровы повелителя стихий из Непроглядной Пучины (0/3)\n[q0]Клобук сумеречного повелителя стихий\nСапоги сумеречного повелителя стихий\nОдеяния сумеречного повелителя стихий\n[q0](2) Набор : Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 12 ед.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211510] = {name = "[q3]Клобук сумеречного убийцы", additional_info = "Становится персональным при поднятии\n{Голова} {Кожа}\nБроня: 84\n+10 к ловкости\n+9 к выносливости\nПрочность: 60 / 60\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 14.\n\n[q]Кожаный доспех убийцы из Непроглядной Пучины (0/3)\n[q0]Клобук сумеречного убийцы\nСапоги сумеречного убийцы\nМундир сумеречного убийцы\n[q0](2) Набор : Увеличивает силу атаки на 12.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211511] = {name = "[q3]Сапоги сумеречного убийцы", additional_info = "Становится персональным при поднятии\n{Ступни} {Кожа}\nБроня: 71\n+5 к силе\n+7 к ловкости\n+7 к выносливости\nПрочность: 55 / 55\nТребуется 25-й ур.\n\n[q]Кожаный доспех убийцы из Непроглядной Пучины (0/3)\n[q0]Клобук сумеречного убийцы\nСапоги сумеречного убийцы\nМундир сумеречного убийцы\n[q0](2) Набор : Увеличивает силу атаки на 12.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211512] = {name = "[q0]Мундир сумеречного убийцы", additional_info = "Становится персональным при поднятии\n{Грудь} {Кожа}\nБроня: 103\n+13 к ловкости\n+9 к выносливости\nПрочность: 100 / 100\nТребуется 25-й ур.\n\n[q]Кожаный доспех убийцы из Непроглядной Пучины (0/3)\n[q0]Клобук сумеречного убийцы\nСапоги сумеречного убийцы\nМундир сумеречного убийцы\n[q0](2) Набор : Увеличивает силу атаки на 12.\n(3) Набор : Повышает вероятность попадания атак и заклинаний на 1%."},
[211514] = {name = "[q2]Заметки о заклинании: массовая регенерация", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Выгравировать на поножах руну \"Массовая регенерация\":\n\n\nИсцеляет цель и участников ее группы или рейда в радиусе 43.5 м, восполняя [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] ед. здоровья за 3 сек. Исцеленные игроки получают эффект \"Темпоральный маяк\" на 15 сек.\n\n Темпоральный маяк\n\nЗапоминает положение цели в пространстве-времени. 70% наносимого вами урона от тайной магии преобразуется в темпоральное исцеление и применяется к каждой текущей цели \"Темпорального маяка\". Вы получаете на 50% меньше исцеления из этого источника. Заклинания тайной магии, наносящие урон нескольким целям, дают на 80% меньше чародейского исцеления.\n[q]\"Обучает новой способности гравировки.\""},
[211527] = {name = "[q3]Уютный спальный мешок", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Разложить спальный мешок. Отдохнув в нем по меньшей мере минуту, можно получить бонус к получаемому опыту. Эффект суммируется до 3 раз. (1 Час Восстановление)\n[q]\"Старый, но еще вполне пригодный.\""},
[211528] = {name = "Темное озарение", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Использование: Помедитировать рядом с определенной уединенной могилой в Сумеречном лесу, чтобы получить пророчество."},
[211530] = {name = "[q2]Пророчество о граде порабощенном", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на наручах руну \"Слово Силы: Барьер\":\n\n\nОкружает участников группы в области действия священным барьером на 10 сек. Барьер уменьшает получаемый урон на 25% и предотвращает задержку применения заклинаний при получении урона.\n[q2]Использование: Сосредоточиться на пророчестве, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о двух духовных тайнах Азерота."},
[211531] = {name = "[q2]Пророчество о семи гостях", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Выгравировать на нагруднике или мантии руну \"Сила души\":\n\n\n\"Малое исцеление\", \"Исцеление\", \"Большее исцеление\" и \"Быстрое исцеление\" сокращают время действия \"Ослабленной души\" на целях на 2 сек. Кроме того, цели, на которые действует ваше \"Слово силы: Щит\", накапливают ярость даже при поглощении полученного урона, а поглощение урона вашим \"Словом силы: Щит\" учитывается для срабатывания \"Праведного неистовства\" как исцеление.\n[q2]Использование: Сосредоточиться на пророчестве, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о двух духовных тайнах Азерота."},
[211534] = {name = "Первозданное озарение", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Жрец\n[q2]Использование: Помедитировать рядом с ловцом снов племени Колючего Меха, чтобы получить пророчество."},
[211691] = {name = "[q2]Заметки о заклинаниях: чародейская вспышка", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Маг\n[q2]Выгравировать на перчатках руну \"Чародейская вспышка\":\n\n\nПоражает противника зарядом энергии, нанося ему [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 453 / 100]-[(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 527 / 100] ед. урона от тайной магии. Каждая \"Чародейская вспышка\" увеличивает затраты маны на следующее применение \"Чародейской вспышки\" на 175%, при этом урон других заклинаний тайной магии увеличивается на 15%. Эффект суммируется до 4 раз. Время действия – 6 сек. или до применения другого заклинания тайной магии.\n[q]\"Обучает новой способности гравировки.\""},
[211777] = {name = "Манускрипт наги", additional_info = "Становится персональным при поднятии\nКлассы: Маг\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[211779] = {name = "Заклятье понимания", additional_info = "Становится персональным при поднятии\nКлассы: Маг\n[q]\"Помогает переводить свитки и заметки о заклинаниях\""},
[211780] = {name = "Свиток: КВИЖИБО", additional_info = "Классы: Маг\n[q2]Использование: Расшифровать свиток с помощью заклятья понимания. Кто знает, какая магия заключена в этом свитке?"},
