[211789] = {name = "[q3]Клобук Артемиды", additional_info = "Становится персональным при поднятии\n{Голова} {Кожа}\nБроня: 84\n+7 к ловкости\n+6 к выносливости\nПрочность: 60 / 60\nТребуется 25-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 24."},
[211799] = {name = "Сумка с похищенными припасами", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q]\"Скорее всего, Ада выкрала их из собора, когда сбежала.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[211800] = {name = "Свиток возвращения", additional_info = "Классы: Маг\nТребуется 12-й ур.\n[q2]Использование: Возвращает погибшего игрока к жизни с 15% запаса здоровья и маны. Не действует в бою."},
[211809] = {name = "\"Введение в науку понимания\"", additional_info = "Предмет, необходимый для задания\nКлассы: Маг\n[q]\"Помогает переводить простейшие заметки о заклинаниях.\""},
[211813] = {name = "[q2]Оберег часового Среброкрылых", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\n[q]\"Ваш трофей из битвы с часовым Среброкрылых. Возможно, заинтересует провидца.\""},
[211814] = {name = "[q2]Знак всадника из клана Песни Войны", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\n[q]\"Ваш трофей из битвы со всадником Песни Войны. Возможно, заинтересует жрицу луны.\""},
