[217299] = {name = "[q3]Иллюзорный жезл", additional_info = "Становится персональным при поднятии\n{Двуручное} {Посох}\n{Урон: 94-142 } {Скорость 3.40}\n(34.71 ед. урона в секунду)\n+7 к выносливости\n+15 к интеллекту\nПрочность: 100 / 100\nТребуется 34-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 12 ед."},
[217300] = {name = "[q3]Шляпка Вайтмейн", additional_info = "Становится персональным при поднятии\n{Голова} {Ткань}\nБроня: 52\n+14 к интеллекту\n+14 к духу\nПрочность: 50 / 50\nТребуется 39-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 11 ед."},
[217301] = {name = "[q3]Амулет Тройного союза", additional_info = "Становится персональным при поднятии\nШея\n+7 к выносливости\n+7 к интеллекту\nТребуется 39-й ур.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 15 ед."},
[217302] = {name = "[q3]Мощь Могрейна", additional_info = "Становится персональным при поднятии\n{Двуручное} {Дробящее}\n{Урон: 100-149 } {Скорость 3.20}\n(38.91 ед. урона в секунду)\n+17 к силе\nПрочность: 100 / 100\nТребуется 39-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 19 ед."},
[217303] = {name = "[q3]Поножи Камнеткача", additional_info = "Становится персональным при поднятии\n{Ноги} {Ткань}\nБроня: 51\n+9 к выносливости\n+15 к интеллекту\nПрочность: 65 / 65\nТребуется 35-й ур.\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 18 ед."},
[217304] = {name = "[q3]Перчатки Ревелоша", additional_info = "Становится персональным при поднятии\n{Кисти рук} {Ткань}\nБроня: 36\n+11 к выносливости\n+12 к интеллекту\nПрочность: 30 / 30\nТребуется 35-й ур."},
[217305] = {name = "[q3]Боевые наручи Ревелоша", additional_info = "Становится персональным при поднятии\n{Запястья} {Кольчуга}\nБроня: 111\n+9 к ловкости\n+8 к интеллекту\nПрочность: 40 / 40\nТребуется 35-й ур."},
[217306] = {name = "[q3]Сапоги Ревелоша", additional_info = "Становится персональным при поднятии\n{Ступни} {Латы}\nБроня: 227\n+12 к силе\n+11 к выносливости\nПрочность: 65 / 65\nТребуется 40-й ур."},
[217307] = {name = "[q3]Наплеч Ревелоша", additional_info = "Становится персональным при поднятии\n{Плечо} {Кожа}\nБроня: 93\n+12 к ловкости\n+11 к выносливости\nПрочность: 60 / 60\nТребуется 36-й ур."},
[217308] = {name = "[q2]Зачарованная печать: изобретательность", additional_info = "Становится персональным при поднятии\nУникальный (5)\nТребуется 40-й ур.\nТребует Наложение чар (225)\n[q2]Использование: Зачарованная печать изобретательности увеличивает урон и силу исцеления ваших заклинаний на 20 ед. и повышает силу атаки на на 20. Время действия – 30 мин. Применяется только вне боя. (30 Мин Восстановление)"},
[217314] = {name = "[q2]Лунная винтовка", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Огнестрельное}\n{Урон: 13-25 } {Скорость 1.70}\n(11.18 ед. урона в секунду)\nПрочность: 65 / 65\nТребуется 23-й ур."},
[217315] = {name = "[q2]Точный лук", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Лук}\n{Урон: 20-37 } {Скорость 2.60}\n(10.96 ед. урона в секунду)\nПрочность: 60 / 60\nТребуется 23-й ур."},
[217336] = {name = "[q0]Монстр – инкуб, кнут, одноручная булава", additional_info = "{Одноручное} {Дробящее}"},
[217337] = {name = "[q2]Партия припасов", additional_info = "Становится персональным при поднятии\n[q]\"Доставьте эти припасы интенданту, чтобы получить щедрую награду.\""},
[217338] = {name = "[q2]Партия припасов", additional_info = "Становится персональным при поднятии\n[q]\"Доставьте эти припасы интенданту, чтобы получить щедрую награду.\""},
[217339] = {name = "[q2]Партия припасов", additional_info = "Становится персональным при поднятии\n[q]\"Доставьте эти припасы интенданту, чтобы получить щедрую награду.\""},
[217345] = {name = "Подкожный яд", additional_info = "Классы: Разбойник\nТребуется 60-й ур.\n[q2]Использование: Покрывает оружие ядом, действующим 30 мин.\n Каждый удар с вероятностью 30% отравляет противника, ослабляя его броню на 1700 ед. на 15 сек.\n\n \"Подкожный яд\" взаимодействует с талантом \"Улучшенное ослабление доспеха\". (Вероятность срабатывания: 30%)"},
[217346] = {name = "Замедляющий яд", additional_info = "Классы: Разбойник\nТребуется 60-й ур.\n[q2]Использование: Покрывает оружие ядом, действующим 30 мин.\n Каждый удар с вероятностью 30% отравляет противника, продлевая время между его атаками ближнего боя на 20% на 15 сек. (Вероятность срабатывания: 30%)"},
[217347] = {name = "Атрофический яд", additional_info = "Классы: Разбойник\nТребуется 60-й ур.\n[q2]Использование: Покрывает оружие ядом, действующим 30 мин.\n Каждый удар с вероятностью 30% отравляет противника, уменьшая силу атак ближнего боя на 205% на 15 сек. (Вероятность срабатывания: 30%)"},
[217350] = {name = "[q4]Инженерные заметки Термоштепселя", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 40-й ур.\n[q]\"В этой потрепанной книжечке собраны чертежи пугающего количества смертоносного оружия. Надо как можно скорее отнести ее королю Меггакруту.\""},
[217351] = {name = "[q4]Инженерные заметки Термоштепселя", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 40-й ур.\n[q]\"В этой потрепанной книжечке собраны чертежи пугающего количества смертоносного оружия. Ноггу будет интересно взглянуть.\""},
[217398] = {name = "Слабый чародейский эликсир", additional_info = "Требуется 28-й ур.\n[q2]Использование: Увеличивает урон от заклинаний максимум на 14 на 30 мин. (3 Сек Восстановление)"},
[217399] = {name = "[q2]Рецепт: слабый чародейский эликсир", additional_info = "Становится персональным при поднятии\nТребует Алхимия (190)\n[q2]Использование: Обучает приготовлению слабого чародейского эликсира.\nСлабый чародейский эликсир\nТребуется 28-й ур.\n[q2]Использование: Увеличивает урон от заклинаний максимум на 14 на 30 мин. (3 Сек Восстановление)\nТребуется: Королевская кровь , Златошип , Хрустальная колба"},
[217495] = {name = "Свиток морозной глыбы", additional_info = "Классы: Маг\nТребуется 26-й ур.\n[q2]Использование: Наносит 183 в 247 ед. урона от магии льда в радиусе 5 м. (1 Мин Восстановление)"},
[217496] = {name = "[q3]Свиток клинка", additional_info = "Становится персональным при поднятии\nКлассы: Маг\nТребуется 30-й ур.\n[q2]Использование: Зачаровывает гипнотический клинок и создает мощное оружие."},
[217497] = {name = "[q3]Меч Нарпас", additional_info = "Становится персональным при поднятии\n{Правая рука} {Меч}\n{Урон: 40-75 } {Скорость 2.00}\n(28.75 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется 34-й ур.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 15 ед."},
[217609] = {name = "Каздорский талисман", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Талисман сделан в виде лица, полного сильнейшей злобы. Вам кажется, что к нему лучше не приглядываться.\""},
[217693] = {name = "Зелье невидимости", additional_info = "Предмет, необходимый для задания\n[q2]Использование: Делает выпившего невидимым на 30 сек. (2 Мин Восстановление)"},
[217704] = {name = "[q3]Окованная железом дубина", additional_info = "Становится персональным при поднятии\n{Двуручное} {Посох}\n{Урон: 68-106 } {Скорость 2.50}\n(34.80 ед. урона в секунду)\n+8 к силе\n+20 к выносливости\nПрочность: 100 / 100\nТребуется 37-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 36 в облике кошки, медведя и лютого медведя."},
[217717] = {name = "Пустая эмблема", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Насытить пустую эмблему сущностью магии крови."},
[217718] = {name = "Эмблема магии крови", additional_info = "Становится персональным при поднятии\nУникальный"},
[217719] = {name = "Сущность магии крови", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Насытить пустую эмблему сущностью магии крови."},
[217720] = {name = "Жертвенная плоть", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Совмещает жертвенную плоть и жертвенные кости."},
[217721] = {name = "Жертвенные кости", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Совмещает жертвенную плоть и жертвенные кости."},
[217727] = {name = "Оберег мертвых", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\n[q2]Если на персонаже: Обнаруживает могилу, в которой спрятано подношение."},
[217736] = {name = "[q2]Руна банды", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на шлеме руну \"Воровская честь\":\n\n\nКогда любой игрок в вашей группе наносит критический урон способностью или заклинанием, длина вашей серии приемов против текущей цели увеличивается на один прием. Срабатывает не чаще одного раза в секунду.\n[q]\"Обучает новой способности гравировки.\""},
[217737] = {name = "Измененный талисман", additional_info = "Становится персональным при поднятии\nУникальный"},
[218083] = {name = "[q4]Хвост Эраникуса", additional_info = "Становится персональным при поднятии\n{Двуручное} {Меч}\n{Урон: 176-264 } {Скорость 3.40}\n(64.71 ед. урона в секунду)\n+42 к силе\nПрочность: 120 / 120\nТребуется 50-й ур.\n[q2]Если на персонаже: Двуручные мечи +8."},
[219021] = {name = "[q3]Увесистая сумка курьера", additional_info = "Становится персональным при поднятии\nУникальный\nСумка (ячеек: 16)"},
[219022] = {name = "[q2]Кольцо погрузчика", additional_info = "Связан с учетной записью\nУникальный\nПалец\n+2 к силе\n+2 к выносливости"},
[219023] = {name = "[q2]Кольцо клерка", additional_info = "Связан с учетной записью\nУникальный\nПалец\n+2 к выносливости\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 2 ед."},
[219024] = {name = "[q2]Кольцо посыльного", additional_info = "Связан с учетной записью\nУникальный\nПалец\n+2 к ловкости\n+2 к выносливости"},
[219135] = {name = "[q3]Подвеска любопытства", additional_info = "Связан с учетной записью\nШея\n+4 к выносливости\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 4 ед."},
[219136] = {name = "[q3]Подвеска упорства", additional_info = "Связан с учетной записью\nШея\n+4 к силе\n+4 к выносливости"},
[219137] = {name = "[q3]Подвеска инициативы", additional_info = "Связан с учетной записью\nШея\n+4 к ловкости\n+4 к выносливости"},
[219147] = {name = "[q2]Руна благоволения", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Паладин\n[q2]Выгравировать на наручах руну \"Благоволение Света\":\n\n\n\"Свет небес\" сокращает время произнесения следующего \"Света небес\" на 0.5,1 сек. Время действия – 15 сек.\n[q]\"Обучает новой способности гравировки.\""},
[219223] = {name = "[q3]Ярость Мастера Клинка", additional_info = "Становится персональным при поднятии\n{Двуручное} {Меч}\n{Урон: 104-157 } {Скорость 3.00}\n(43.50 ед. урона в секунду)\n+17 к силе\n+10 к выносливости\nПрочность: 100 / 100\nТребуется 50-й ур.\n[q2]Использование: Атакует до 4 целей в радиусе 8 м, нанося каждому противнику урон от оружия, и восстанавливает \"Вихрь\". (2 Мин Восстановление)"},
[219326] = {name = "[q3]Семя обновления", additional_info = "Становится персональным при поднятии\nАксессуар\nТребуется 50-й ур.\n[q2]Если на персонаже: Ваши заклинания и способности с некоторой вероятностью заражают семенем враждебных гуманоидов, зверей и драконов. Если цель погибает в течение 30 сек. после заражения, из ее тела вырастает целительный цветок. (Вероятность срабатывания: 40%, Восстановление: 2мин)"},
[219343] = {name = "[q3]Клобук жулика", additional_info = "Становится персональным при поднятии\nСпина\nБроня: 36\n+11 к ловкости\nТребуется 50-й ур.\n[q2]Если на персонаже: Повышает эффективность незаметности на 3. Увеличивает дальность действия \"Обезвреживания ловушки\" и \"Обшаривания карманов\" на 2 м, а дальность действия \"Отвлечения\" – на 5 м."},
[219345] = {name = "[q3]Пламенное лассо", additional_info = "Становится персональным при поднятии\nАксессуар\nТребуется 50-й ур.\n[q2]Использование: Обездвиживает выбранного демона или зверя и наносит 200 ед. урона от огня за 24 сек. Урон может прервать действие эффекта. Пойманных в лассо гончих Недр можно приручить. (1 Мин Восстановление)"},
[219399] = {name = "Кошмарный мох", additional_info = "[q]\"Эфемерный и нестабильный предмет.\""},
[219401] = {name = "Руда холодного железа", additional_info = "[q]\"Эфемерный и нестабильный предмет.\""},
[219402] = {name = "Усиленная Сном чешуя дракона", additional_info = "[q]\"Эфемерный и нестабильный предмет.\""},
[219404] = {name = "Теневая коса", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Эфемерный отголосок одного из могущественных утерянных артефактов Элуны.\""},
[219405] = {name = "Записи огра-мага", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Не поддающиеся расшифровке записки безумца.\""},
[219406] = {name = "Непроклюнувшееся яйцо зеленого дракона", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Яйцо зеленого дракона в отличном состоянии. Энергия Сна создает на его поверхности необычные переливы.\""},
[219414] = {name = "Раздробленная яичная скорлупа", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Кошмар поглотил жизнь, которая когда-то зарождалась в этом яйце.\""},
[219444] = {name = "Сон-корень", additional_info = "[q]\"Эфемерный и нестабильный предмет.\""},
[219445] = {name = "[q2]Пыль из ложного золота", additional_info = "[q]\"Эфемерный и нестабильный предмет.\""},
[219446] = {name = "Насыщенная Сном чешуя дракона", additional_info = "[q]\"Эфемерный и нестабильный предмет.\""},
[219447] = {name = "Усиленное Сном яйцо дракона", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Сияющее яйцо зеленого дракона.\""},
[219448] = {name = "Машина снов", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Устройство для создания кошмаров.\""},
[219449] = {name = "Азшарское пророчество", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Древнее пророчество, записанное на хрупком свитке.\""},
[219454] = {name = "Звездный лотос", additional_info = "[q]\"Эфемерный и нестабильный предмет.\""},
[219486] = {name = "[q2]Руда звездного серебра", additional_info = "[q]\"Эфемерный и нестабильный предмет.\""},
