[221307] = {name = "[q4]Карта Новолуния: гниение", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nТребуется 50-й ур.\n[q2]Если на персонаже: Заклинания и атаки иногда похищают у цели 40 ед. здоровья и применяют один эффект \"Гниение\". При накоплении 5 эффектов цель получает 225 в 375 ед. урона. (Восстановление: 3с)"},
[221308] = {name = "[q4]Карта Новолуния: разрастание", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nТребуется 50-й ур.\n[q2]Если на персонаже: Заклинания прямого исцеления и восполняющие здоровье такты периодического исцеления с некоторой вероятностью восполняют цели 8 ед. энергии, 1% маны или 4 ед. ярости. (Вероятность срабатывания: 10%)"},
[221309] = {name = "[q4]Карта Новолуния: песчаная буря", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nТребуется 50-й ур.\n[q2]Если на персонаже: Заклинания и атаки с некоторой вероятностью призывают песчаную бурю, кружащую вокруг вас и наносящую 50 в 100 ед. урона от сил природы целям на своем пути. (Вероятность срабатывания: 30%, Восстановление: 8с)"},
[221310] = {name = "[q4]Карта Новолуния: мучение", additional_info = "Становится персональным при поднятии\nУникальный\nАксессуар\nТребуется 50-й ур.\n[q2]Если на персонаже: Атаки и заклинания владельца с некоторой вероятностью истязают цель, заставляя ее бесцельно бродить в течение 3 сек. (Вероятность срабатывания: 5%, Восстановление: 15с)"},
[221311] = {name = "[q2]Живительное колдунство Атал'ай", additional_info = "Становится персональным при поднятии\nУникальный (2)\nТребуется 50-й ур.\n[q2]Использование: Повышает силу исцеления на 45 ед., а скорость восполнения маны на 11 ед. за 5 сек. Ваши исцеляющие заклинания с некоторой вероятностью восполняют 8 ед. энергии, 1% маны или 4 ед. ярости. Одновременно может действовать только одно зелье Атал'ай. Действует только в Затонувшем храме. (Вероятность срабатывания: 25%, Восстановление: 20с) (3 Сек Восстановление)\n[q]\"От сосуда исходит насыщенное синее свечение. Настой будто требует, чтобы вы его выпили.\""},
[221312] = {name = "[q2]Настой атал'айского колдунства", additional_info = "[q]\"Самое сильное колдунство троллей Атал'ай.\""},
[221313] = {name = "[q3]Настой кошмарного колдунства", additional_info = "[q]\"В сосуде переливается магический атал'айский напиток, насыщенный энергиями кошмара.\""},
[221314] = {name = "Объявление \"Разыскивается\"", additional_info = "Предмет, необходимый для задания\nУникальный\n[q]\"Грубый набросок дворфа из клана Черного Железа.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[221315] = {name = "[q3]Генератор радуги", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Сила радуги! (30 Мин Восстановление)"},
[221316] = {name = "Требовательная форма Примо", additional_info = "Становится персональным при поднятии\nУникальный\nРубашка\n[q2]Использование: Концентрируется."},
[221317] = {name = "Силовой кристалл Фераласа", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Использовать 4 силовых кристалла, чтобы настроиться на Азерот и обучиться новой способности."},
[221318] = {name = "Силовой кристалл Азшары", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Использовать 4 силовых кристалла, чтобы настроиться на Азерот и обучиться новой способности."},
[221319] = {name = "Силовой кристалл Черной горы", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Использовать 4 силовых кристалла, чтобы настроиться на Азерот и обучиться новой способности."},
[221320] = {name = "Силовой кристалл Внутренних земель", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Использовать 4 силовых кристалла, чтобы настроиться на Азерот и обучиться новой способности."},
[221321] = {name = "[q3]Перстень могущества Атал'ай", additional_info = "Становится персональным при поднятии\nТребуется 50-й ур.\n[q2]Использование: Применяет к наплечникам постоянные чары, повышающие силу атаки на 15."},
[221322] = {name = "[q3]Магический перстень Атал'ай", additional_info = "Становится персональным при поднятии\nТребуется 50-й ур.\n[q2]Использование: Применяет к наплечникам постоянные чары, увеличивающие урон и силу исцеления от магических заклинаний и эффектов на 9 ед."},
[221323] = {name = "[q3]Перстень безмятежности Атал'ай", additional_info = "Становится персональным при поднятии\nТребуется 50-й ур.\n[q2]Использование: Применяет к наплечникам постоянные чары, повышающие силу исцеления от заклинаний и эффектов максимум на 18 ед."},
[221324] = {name = "Хрупкий ключ Тенегорна", additional_info = "Предмет, необходимый для задания\nУникальный\nДлительность: 15 мин\n[q]\"Настолько ломкий, что к связке его прикрепить невозможно.\""},
[221325] = {name = "Динамит \"Про-100-взрыв\"", additional_info = "Становится персональным при поднятии\nДлительность: 15 мин\n[q2]Использование: Открывает сложные запертые двери.\n[q]\"Фитиль уже горит!\""},
[221326] = {name = "Сердце священного оленя", additional_info = "Становится персональным при поднятии\n[q2]Использование: Вы приносите подношение в святилище чудовища."},
[221327] = {name = "[q2]Схема: уменьшающий луч гномов", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nУменьшающий луч гномов\nСтановится персональным при надевании\nАксессуар\nТребует Инженерное дело (205)\n[q2]Использование: Уменьшение цели и снижение силы ее атаки на 250 ед. По крайней мере, так обычно бывает... (5 Мин Восстановление)\nТребуется: Мифриловая труба , Нестабильное пусковое устройство , Мифриловый слиток (4), Настой колдунства (4), Нефрит (2)"},
[221328] = {name = "[q2]Схема: гномьи очки", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\n[q2]Гномьи очки\nСтановится персональным при поднятии\n{Голова} {Ткань}\nБроня: 45\n+9 к ловкости\n+9 к выносливости\n+9 к духу\nПрочность: 45 / 45\nТребует Инженерное дело (210)\nТребуется: Огненные очки , Мифриловая труба , Золотое силовое ядро (2), Настой колдунства (2), Толстая кожа (2)"},
[221329] = {name = "[q2]Схема: гномий сетестрел", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nСетемет гномов\nСтановится персональным при надевании\nАксессуар\nТребует Инженерное дело (210)\n[q2]Использование: Цель запутывается в сети на 10 сек. Однако у этой сети много крючков, и порой она может зацепиться за одежду пользователя. (10 Мин Восстановление)\nТребуется: Мифриловая труба , Тенешелк (2), Плотная паутина (4), Твердое взрывчатое вещество (2), Мифриловый слиток (4)"},
[221330] = {name = "[q2]Схема: пояс гномов, хранящий от вреда", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\n[q2]Пояс гномов, хранящий от вреда\nСтановится персональным при надевании\n{Пояс} {Кожа}\nБроня: 66\n+6 к выносливости\nПрочность: 30 / 30\nТребует Инженерное дело (215)\n[q2]Использование: Защита силовым щитом, в течение 10 мин позволяющим поглотить 500 ед. урона. ВНИМАНИЕ: силовое поле может перегрузиться от удара, на время лишив носящего защиты. (Вероятность срабатывания: 5%) (1 Час Восстановление)\nТребуется: Мглистый пояс , Мифриловый слиток (4), Слиток истинного серебра (2), Нестабильное пусковое устройство , Аквамарин (2)"},
[221331] = {name = "[q2]Схема: гномьи реактивные сапоги", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\n[q2]Гномьи реактивные сапоги\nСтановится персональным при надевании\n{Ступни} {Ткань}\nБроня: 41\nПрочность: 35 / 35\nТребует Инженерное дело (225)\n[q2]Использование: Эти сапоги значительно увеличат скорость вашего бега на 20 сек. ВНИМАНИЕ! Источник энергии и гироскоп не всегда функционируют как полагается. (30 Мин Восстановление)\nТребуется: Черные сапоги из магической ткани , Мифриловая труба (2), Толстая кожа (4), Твердое взрывчатое вещество (8), Гирохронатом (4)"},
[221332] = {name = "[q2]Схема: боевой цыпленок гномов", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nБоевой цыпленок гномов\nСтановится персональным при поднятии\nАксессуар\nТребует Инженерное дело (230)\n[q2]Использование: Создание боевого цыпленка, который будет сражаться на вашей стороне в течение 1.50 мин., либо пока не будет уничтожен. (30 Мин Восстановление)\nТребуется: Мифриловая обшивка , Слиток истинного серебра (6), Мифриловый слиток (6), Инкрустированный мифриловый цилиндр (2), Золотое силовое ядро , Нефрит (2)"},
[221333] = {name = "[q2]Схема: гномья шапка контроля над разумом", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\n[q2]Гномья шапка контроля над разумом\nСтановится персональным при надевании\n{Голова} {Ткань}\nБроня: 50\n+14 к духу\nПрочность: 45 / 45\nТребует Инженерное дело (215)\n[q2]Использование: Вступление в ментальное сражение с целью-гуманоидом в попытке получить над ней контроль. В случае успеха контроль над созданием длится 20 сек. (30 Мин Восстановление)\nТребуется: Мифриловый слиток (10), Слиток истинного серебра (4), Золотое силовое ядро , Звездный рубин (2), Магическая ткань (4)"},
[221334] = {name = "[q2]Схема: смертоносный луч гномов", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nСмертоносный луч гномов\nСтановится персональным при поднятии\nАксессуар\n[q2]Использование: Устройство постепенно заряжается, используя вашу жизненную силу, а потом выстреливает во врага лучом энергии. (5 Мин Восстановление)\n[q]\"Может привести к смерти или серьезному ранению\"\nТребуется: Мифриловая труба (2), Нестабильное пусковое устройство , Субстанция Нежити , Лимфа нежити (4), Инкрустированный мифриловый цилиндр"},
[221335] = {name = "[q2]Схема: шлем гоблинской конструкции", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\n[q2]Шлем гоблинской конструкции\nСтановится персональным при поднятии\n{Голова} {Ткань}\nБроня: 44\nУстойчивость: +15 Огонь\nПрочность: 45 / 45\nТребует Инженерное дело (205)\n[q2]Использование: Поглощение 300 в 500 ед. урона от огня. Время действия – 1 мин. (1 Час Восстановление)\nТребуется: Мифриловый слиток (8), Цитрин , Первородный огонь (4)"},
[221336] = {name = "[q2]Схема: шахтерская гоблинская каска", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\n[q2]Шахтерская гоблинская каска\nСтановится персональным при поднятии\n{Голова} {Кольчуга}\nБроня: 190\n+15 к выносливости\nПрочность: 60 / 60\nТребует Инженерное дело (205)\n[q2]Если на персонаже: +5 к навыку горного дела\nТребуется: Мифриловый слиток (8), Цитрин , Первородная земля (4)"},
[221337] = {name = "[q2]Схема: гоблинская мортира", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nГоблинская мортира\nСтановится персональным при надевании\nАксессуар\nТребует Инженерное дело (205)\n[q2]Использование: Нанесение 383 в 517 ед. урона от огня и оглушение целей в радиусе 5 м. на 3 сек. (10 Мин Восстановление)\n6 зарядов\nТребуется: Мифриловая труба (2), Мифриловый слиток (4), Твердое взрывчатое вещество (5), Золотое силовое ядро , Первородный огонь"},
[221338] = {name = "[q2]Схема: гоблинская мина", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nГоблинский саперный заряд\nТребует Инженерное дело (205)\n[q2]Использование: При инициации происходит взрыв, наносящий 450 в 750 ед. урона от огня всем ближайшим противникам и 375 в 625 ед. урона вам. (5 Мин Восстановление)\nТребуется: Магическая ткань , Твердое взрывчатое вещество (3), Нестабильное пусковое устройство"},
[221339] = {name = "[q2]Схема: гоблинские реактивные сапоги", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\n[q2]Гоблинские реактивные сапоги\nСтановится персональным при надевании\n{Ступни} {Ткань}\nБроня: 41\nПрочность: 35 / 35\n[q2]Использование: Эти опасные с виду ботинки значительно увеличат вашу скорость бега на 20 сек. Однако они взрывоопасны, так что будьте осторожны. (5 Мин Восстановление)\nТребуется: Черные сапоги из магической ткани , Мифриловая труба (2), Толстая кожа (4), Гоблинское ракетное топливо (2), Нестабильное пусковое устройство"},
[221340] = {name = "[q2]Схема: гоблинский бомбомет", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nГоблинский бомбомет\nСтановится персональным при поднятии\nАксессуар\nТребует Инженерное дело (230)\n[q2]Использование: Создает самоходную бомбу, подрывающую ближайшего противника, нанося урон от огня в размере 315 в 385. (30 Мин Восстановление)\nТребуется: Мифриловая обшивка (2), Твердое взрывчатое вещество (4), Слиток истинного серебра (6), Нестабильное пусковое устройство , Точный прицел (2)"},
[221341] = {name = "[q2]Схема: Великан", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nВеликан\nТребует Инженерное дело (225)\n[q2]Использование: Нанесение 340 в 460 ед. урона от огня и оглушение целей на 5 сек. в радиусе 10 м. Любой нанесенный урон прекратит действие эффекта. (1 Мин Восстановление)\nТребуется: Мифриловая обшивка , Гоблинское ракетное топливо , Плотный динамит (6), Нестабильное пусковое устройство"},
[221342] = {name = "[q2]Схема: гоблинское драконье ружье", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\nГоблинское драконье ружье\nСтановится персональным при поднятии\nАксессуар\n[q2]Использование: Нанесение 61 в 69 ед. урона от огня в течение 10 сек. всем целям в конусе поражения впереди инженера, использующего это оружие. Если оно, конечно, не взорвется... (5 Мин Восстановление)\nТребуется: Мифриловая труба (2), Гоблинское ракетное топливо (4), Мифриловый слиток (6), Слиток истинного серебра (6), Нестабильное пусковое устройство"},
[221343] = {name = "[q2]Схема: гоблинский реактивный шлем", additional_info = "Становится персональным при поднятии\nТребует Инженерное дело (205)\n[q2]Использование:\n\n\n[q2]Гоблинский реактивный шлем\nСтановится персональным при надевании\n{Голова} {Ткань}\nБроня: 50\n+15 к выносливости\nПрочность: 45 / 45\nТребует Инженерное дело (235)\n[q2]Использование: Бросается к противнику, выводя его из строя на 30 сек. Вы также падаете, оглушаясь на короткое время. Нанесенный урон приводит цель в себя. (20 Мин Восстановление)\nТребуется: Шлем гоблинской конструкции , Гоблинское ракетное топливо (4), Мифриловый слиток (4), Нестабильное пусковое устройство"},
[221344] = {name = "[q3]Персональная книга заклинаний", additional_info = "Становится персональным при поднятии\nУникальный\nЛевая рука\nКлассы: Маг\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 21 ед.\n[q2]Использование: Создает 5 заклятья:заклятий понимания. (4 Ч Восстановление)"},
[221345] = {name = "[q3]Оскверненная кровь Эраникуса", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 50-й ур."},
[221346] = {name = "[q4]Лопаточная кость мертвого божества", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 50-й ур.\n[q]\"Чистая и поистине великолепная лопаточная кость. Ее форма идеальна и, как вы ни стараетесь, вы не находите ни единого следа повреждений.\""},
[221347] = {name = "Мутная сапта огня", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Шаман получает возможность видеть духов стихий."},
[221348] = {name = "Мутная сапта воды", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Шаман получает возможность видеть духов стихий."},
[221349] = {name = "Мутная сапта земли", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Шаман получает возможность видеть духов стихий."},
[221350] = {name = "Обгоревшие записки шамана", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nКлассы: Шаман\n[q]\"Бумага обгорела, и прочитать уже ничего не выйдет. Кажется, в страницы что-то завернуто.\""},
[221351] = {name = "Отсыревшие записки шамана", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nКлассы: Шаман\n[q]\"Вода окончательно растворила чернила. Кажется, в страницы что-то завернуто.\""},
[221352] = {name = "Испачканные записки шамана", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nКлассы: Шаман\n[q]\"Время и грязь не пощадили записи: теперь их невозможно разобрать. Кажется, в страницы что-то завернуто.\""},
[221353] = {name = "Частица огня", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить фрагмент огня с сущностями стихий. Это может помочь вам найти оскверненный алтарь."},
[221354] = {name = "Частица воды", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить фрагмент воды с сущностями стихий. Это может помочь вам найти оскверненный алтарь."},
[221355] = {name = "Частица земли", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]Использование: Объединить фрагмент земли с сущностями стихий. Это может помочь вам найти оскверненный алтарь."},
[221356] = {name = "Сияющая частица огня", additional_info = "Становится персональным при поднятии\nУникальный"},
[221357] = {name = "Сияющая частица воды", additional_info = "Становится персональным при поднятии\nУникальный"},
[221358] = {name = "Сияющая частица земли", additional_info = "Становится персональным при поднятии\nУникальный"},
[221359] = {name = "Чистое перо совуха", additional_info = "Становится персональным при поднятии"},
[221360] = {name = "Фарракский папирус", additional_info = "Становится персональным при поднятии"},
[221361] = {name = "Смола Зукк'аш", additional_info = "Становится персональным при поднятии"},
[221362] = {name = "Тряпочка для чистки оружия", additional_info = "Требуется: Дружелюбие (Изумрудные Стражи\n)\n[q2]Использование: Чистит ваше оружие, снимает все временные чары и приводит его в идеальное состояние!"},
[221363] = {name = "[q4]Лопаточная кость мертвого божества", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 50-й ур.\n[q]\"Чистая и поистине великолепная лопаточная кость. Ее форма идеальна и, как вы ни стараетесь, вы не находите ни единого следа повреждений.\""},
[221364] = {name = "[q2]Медная монета резни", additional_info = "Становится персональным при поднятии\n[q2]Использование: Преобразует 100 медных монет резни в 1 серебряную монету резни.\n[q]\"Малый символ служения лоа крови.\""},
[221365] = {name = "[q3]Серебряная монета резни", additional_info = "Становится персональным при поднятии\n[q2]Использование: Преобразует 100 серебряных монет резни в 1 золотую монету резни.\n[q]\"Символ служения лоа крови.\""},
[221366] = {name = "[q4]Золотая монета резни", additional_info = "Становится персональным при поднятии\n[q]\"Большой символ служения лоа крови.\""},
[221367] = {name = "Мешочек медных монет резни", additional_info = "Становится персональным при поднятии\n[q]\"Содержит 100 медных монет резни.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[221368] = {name = "Мешочек серебряных монет резни", additional_info = "Становится персональным при поднятии\n[q]\"Содержит 100 серебряных монет резни.\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[221369] = {name = "[q3]Сифон Кошмара", additional_info = "Становится персональным при поднятии\nАксессуар\nТребуется 20-й ур.\nТребуется: Дружелюбие (Изумрудные Стражи\n)\n[q2]Если на персонаже: Восполняет 150 ед. здоровья и маны при убийстве цели, за которую вы получаете опыт или честь. Эффект срабатывает не чаще раза в 10 сек. (Восстановление: 10с)"},
[221370] = {name = "Драгоценный медальон", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"На обратной стороне вы видите надпись: \"Джабби + Эни\"\""},
[221371] = {name = "Кошелек похитителя", additional_info = "Становится персональным при поднятии\nУникальный\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[221372] = {name = "[q0]Изодранный кошелек", additional_info = "[q]\"Содержимое, скорее всего, пострадало в бою.\""},
[221374] = {name = "[q3]Страдания Сна", additional_info = "Становится персональным при поднятии\nАксессуар\nТребуется 30-й ур.\nТребуется: Дружелюбие (Изумрудные Стражи\n)\n[q2]Если на персонаже: Увеличивает урон или силу исцеления следующей атаки, способности или заклинания на 40 при убийстве цели, за которую вы получаете опыт или честь. Эффект срабатывает не чаще раза в 10 сек. (Восстановление: 10с)"},
