[227387] = {name = "Комплект шлема и нагрудника целителя", additional_info = "Становится персональным при поднятии\n[q]\" Головной убор буйного сердца и покров буйного сердца (специализация на исцелении)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227388] = {name = "Комплект шлема и нагрудника преследователя", additional_info = "Становится персональным при поднятии\n[q]\" Шапка повелителя зверей и мундир повелителя зверей (специализация на дальнем бое)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227389] = {name = "Комплект шлема и нагрудника хищника", additional_info = "Становится персональным при поднятии\n[q]\" Боевой капюшон повелителя зверей и цепь повелителя зверей (специализация на ближнем бое)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227390] = {name = "Комплект шлема и нагрудника милосердия", additional_info = "Становится персональным при поднятии\n[q]\" Корона Закаленного духа и покров Закаленного духа (специализация на светлой магии)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227391] = {name = "Комплект сияющего шлема и нагрудника", additional_info = "Становится персональным при поднятии\n[q]\" Великий шлем Закаленного духа и кираса Закаленного духа (специализация на воздаянии)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227392] = {name = "Комплект шлема и нагрудника божественной воли", additional_info = "Становится персональным при поднятии\n[q]\" Большой шлем Закаленного духа и нагрудный доспех Закаленного духа (специализация на защите)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227393] = {name = "Комплект шлема и нагрудника рассвета", additional_info = "Становится персональным при поднятии\n[q]\" Корона добродетели и одеяние добродетели (специализация – лекарь)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227394] = {name = "Комплект сумеречного шлема и нагрудника", additional_info = "Становится персональным при поднятии\n[q]\" Клобук добродетели и платье добродетели (специализация на темной магии)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227395] = {name = "Комплект шлема и нагрудника азарта", additional_info = "Становится персональным при поднятии\n[q]\" Накидка Покрова Тьмы и мундир Покрова Тьмы (специализация на ближнем бое)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227396] = {name = "Комплект шлема и нагрудника битвы", additional_info = "Становится персональным при поднятии\n[q]\" Большой шлем Покрова Тьмы и доспехи Покрова Тьмы (специализация – танк)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227397] = {name = "Комплект шлема и нагрудника избавления от боли", additional_info = "Становится персональным при поднятии\n[q]\" Корона Пяти Громов и туника Пяти Громов (специализация на исцелении)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227398] = {name = "Комплект шлема и нагрудника извержения", additional_info = "Становится персональным при поднятии\n[q]\" Клобук Пяти Громов и жилет Пяти Громов (специализация на стихиях)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227399] = {name = "Комплект шлема и нагрудника стычки", additional_info = "Становится персональным при поднятии\n[q]\" Лик Пяти Громов и цепь Пяти Громов (специализация на совершенствовании – нанесение урона)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227400] = {name = "Комплект шлема и нагрудника решимости", additional_info = "Становится персональным при поднятии\n[q]\" Головной убор Пяти Громов и нагрудный доспех Пяти Громов (специализация на совершенствовании – танк)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227401] = {name = "Комплект оскверненного шлема и нагрудника", additional_info = "Становится персональным при поднятии\n[q]\" Маска Тумана смерти и одеяние Тумана смерти (специализация на дальнем бое)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227402] = {name = "Комплект зловещего шлема и нагрудника", additional_info = "Становится персональным при поднятии\n[q]\" Капюшон Тумана смерти и покров Тумана смерти (специализация – танк)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227403] = {name = "Комплект шлема и нагрудника непоколебимости", additional_info = "Становится персональным при поднятии\n[q]\" Большой шлем героизма и нагрудный доспех героизма (специализация на защите)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227404] = {name = "Комплект шлема и нагрудника неудержимости", additional_info = "Становится персональным при поднятии\n[q]\" Корона героизма и кираса героизма (специализация на ближнем бое)\"\n[q2]<Щелкните правой кнопкой мыши, чтобы открыть.>"},
[227444] = {name = "[q2]Идол охотницы", additional_info = "Становится персональным при поднятии\nУникальный\n{Реликвия} {Идол}\nКлассы: Друид\n[q2]Выгравировать на плаще руну \"Улучшенный размах\":\n\n\nКогда вы находитесь в облике кошки, ваш \"Размах\" превращается в \"Размах (кошка)\". Когда вы находитесь в облике медведя, \"Размах\" поражает до 7 дополнительных целей.\n\n \"Размах (кошка)\"\n\nАтакует ближайших противников, нанося им 250% урона от оружия и продлевая серию приемов для текущей цели на 1.\n[q]\"Обучает новой способности после того, как вы убьете 5 спящих целей в облике кошки.\""},
[227451] = {name = "Передающий знак", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"На краях высечены символы >, v, ^ и <.\""},
[227454] = {name = "[q4]Кольцо приливов", additional_info = "Становится персональным при поднятии\nПалец\n+8 к выносливости\nУстойчивость: +20 Огонь\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 13 ед."},
[227455] = {name = "[q4]Океанский Ветер", additional_info = "Становится персональным при поднятии\nПалец\n+8 к выносливости\nУстойчивость: +20 Огонь\n[q2]Если на персонаже: Увеличивает силу атаки на 22."},
[227456] = {name = "[q2]Руна кровавого вихря", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Разбойник\n[q2]Выгравировать на плаще руну \"Кровавый вихрь\":\n\n\nЗавершающий прием, который с размаху бьет противников в радиусе 8 м и вызывает у них кровотечение. Время действия и урон увеличиваются с длиной серии.\n\n 1 прием: (Сила атаки * 0.30) ед. урона за 4 сек.\n 2 приема: (Сила атаки * 0.45) ед. урона за 6 сек.\n 3 приема: (Сила атаки * 0.60) ед. урона за 8 сек.\n 4 приема: (Сила атаки * 0.75) ед. урона за 10 сек.\n 5 приемов: (Сила атаки * 0.90) ед. урона за 12 сек.\n\n \"Кровавый вихрь\" взаимодействует с теми же талантами и эффектами, что и \"Рваная рана\".\n[q]\"Обучает новой способности гравировки.\""},
[227530] = {name = "[q4]Раскаленный пояс", additional_info = "Становится персональным при поднятии\nКлассы: Жрец , Маг , Чернокнижник\nТребуется 60-й ур."},
[227531] = {name = "[q4]Раскаленные путы", additional_info = "Становится персональным при поднятии\nКлассы: Жрец , Маг , Чернокнижник\nТребуется 60-й ур."},
[227532] = {name = "[q4]Раскаленный капюшон", additional_info = "Становится персональным при поднятии\nКлассы: Жрец , Маг , Чернокнижник\nТребуется 60-й ур."},
[227533] = {name = "[q4]Раскаленные перчатки", additional_info = "Становится персональным при поднятии\nКлассы: Жрец , Маг , Чернокнижник\nТребуется 60-й ур."},
[227534] = {name = "[q4]Раскаленные поножи", additional_info = "Становится персональным при поднятии\nКлассы: Жрец , Маг , Чернокнижник\nТребуется 60-й ур."},
[227535] = {name = "[q4]Раскаленное одеяние", additional_info = "Становится персональным при поднятии\nКлассы: Жрец , Маг , Чернокнижник\nТребуется 60-й ур."},
[227536] = {name = "[q4]Раскаленные сапоги", additional_info = "Становится персональным при поднятии\nКлассы: Жрец , Маг , Чернокнижник\nТребуется 60-й ур."},
[227537] = {name = "[q4]Раскаленные наплечники", additional_info = "Становится персональным при поднятии\nКлассы: Жрец , Маг , Чернокнижник\nТребуется 60-й ур."},
[227549] = {name = "Обрывок пергамента", additional_info = "Становится персональным при поднятии\nКлассы: Разбойник\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[227552] = {name = "[q0]Изорванный пергамент", additional_info = "Становится персональным при поднятии\nУникальный\n[q]\"Похоже, он был поврежден во время боя.\""},
[227658] = {name = "[q2]Записка Приверженцев Тени", additional_info = "Становится персональным при поднятии\nКлассы: Чернокнижник\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[227683] = {name = "[q5]Сальфарас, Рука Рагнароса", additional_info = "Становится персональным при поднятии\nУникальный\n{Двуручное} {Дробящее}\n{Урон: 229-382 } {Скорость 3.80}\n(80.39 ед. урона в секунду)\n+12 к силе\n+12 к выносливости\nУстойчивость: +32 Огонь\nПрочность: 145 / 145\nТребуется 60-й ур.\n[q2]Если на персонаже: Увеличивает силу атаки на 358 ед. в облике кошки, медведя и лютого медведя.\n[q2]Возможный эффект при попадании: Выпускает огненный шар, наносящий 273 в 333 ед. урона от огня сразу и еще 75 ед. урона за 10 сек. Кроме того, очищает душу цели, увеличивая получаемый ею урон от огня и светлой магии максимум на 30 ед.\n[q2]Если на персонаже: Когда вас атакуют в ближнем бою, вы с вероятностью 20% наносите 25 ед. урона от огня ближайшим противникам. (Вероятность срабатывания: 20%)"},
[227684] = {name = "[q4]Сульфуронский молот", additional_info = "Становится персональным при надевании\n{Двуручное} {Дробящее}\n{Урон: 181-303 } {Скорость 3.80}\n(63.68 ед. урона в секунду)\n+10 к силе\n+10 к выносливости\nУстойчивость: +30 Огонь\nПрочность: 120 / 120\nТребуется 60-й ур.\n[q2]Возможный эффект при попадании: Бросок огненного шара, который наносит 83 в 101 ед. урона от огня единовременно и 16 ед. урона от огня в течение 8 сек.\n[q2]Если на персонаже: Нанесение 5 ед. урона от огня любому, кто нападает на вас в ближнем бою.\n[q2]Если на персонаже: Увеличивает силу атаки на 124 ед. в облике кошки, медведя и лютого медведя."},
[227685] = {name = "Измененный теневой скальпель", additional_info = "Предмет, необходимый для задания\n[q2]Использование: Направить измененный теневой скальпель на Арконоса Проклятого, чтобы рассеять защищающий его барьер.\n[q]\"Катберт усилил это орудие последним благословением Далтона. Оно должно рассеять барьер, защищающий Арконоса.\""},
[227686] = {name = "Боевой молот с узорами", additional_info = "Предмет, необходимый для задания\nУникальный"},
[227687] = {name = "[q2]Любимый золотой зуб Ортаса", additional_info = "Становится персональным при поднятии\n[q2]Использование: Потереть зуб Ортаса. Какая гадость. (2 Мин Восстановление)\n[q]\"Пахнет отвратительно.\""},
[227688] = {name = "Кровавый Вой", additional_info = "Становится персональным при поднятии\n{Двуручное} {Топор}"},
[227689] = {name = "Частично переваренные латные доспехи", additional_info = "Предмет, необходимый для задания\nУникальный"},
[227690] = {name = "Некротический рунный камень", additional_info = "Предмет, необходимый для задания\n[q]\"Касаясь этого камня голыми руками, вы сразу чувствуете прилив тошноты.\""},
[227691] = {name = "[q4]Клинок Ханны", additional_info = "Становится персональным при надевании\nУникальный\n{Двуручное} {Меч}\n{Урон: 101-152 } {Скорость 2.10}\n(60.24 ед. урона в секунду)\n+11 к силе\n+11 к ловкости\n+11 к выносливости\n+11 к интеллекту\n+11 к духу\nПрочность: 120 / 120\nТребуется 59-й ур."},
[227724] = {name = "[q0]Окровавленный рекомендательный жетон", additional_info = "Становится персональным при поднятии\nТребуется 30-й ур.\n[q]\"Сейчас он покрыт толстой коркой высохшей крови, но когда-то его выдали в награду за героизм, проявленный в битве. Хотя владелец жетона давно погиб, сам жетон все еще служит символом чести.\""},
[227727] = {name = "[q4]Чертеж: сульфуронский молот", additional_info = "Уникальный\nТребует Кузнечное дело (300)\n[q2]Использование: Обучает изготовлению сульфуронского молота.\n[q4]Сульфуронский молот\nСтановится персональным при надевании\n{Двуручное} {Дробящее}\n{Урон: 181-303 } {Скорость 3.80}\n(63.68 ед. урона в секунду)\n+10 к силе\n+10 к выносливости\nУстойчивость: +30 Огонь\nПрочность: 120 / 120\nТребуется 60-й ур.\n[q2]Возможный эффект при попадании: Бросок огненного шара, который наносит 83 в 101 ед. урона от огня единовременно и 16 ед. урона от огня в течение 8 сек.\n[q2]Если на персонаже: Нанесение 5 ед. урона от огня любому, кто нападает на вас в ближнем бою.\n[q2]Если на персонаже: Увеличивает силу атаки на 124 ед. в облике кошки, медведя и лютого медведя.\nТребуется: Сульфуронский слиток (8), Слиток черного железа (20), Арканитовый слиток (50), Субстанция Огня (25), Кровь Горы (10), Ядро лавы (10), Огненное ядро (10)"},
[227728] = {name = "[q5]Глаз Сульфураса", additional_info = "Становится персональным при поднятии\n[q2]Использование: Око Сульфураса можно соединить с сульфуронским молотом, чтобы создать Сульфурас, легендарный молот Рагнароса."},
[227730] = {name = "[q4]Контракт Братства Тория", additional_info = "Становится персональным при поднятии\nУникальный\nЭтот предмет позволяет получить задание.\nТребуется 60-й ур.\n[q]\"Оплетено колючей проволокой Черного Железа.\""},
[227743] = {name = "Обсидиановый энергетический сердечник", additional_info = "Предмет, необходимый для задания"},
[227745] = {name = "Семейная реликвия", additional_info = "Становится персональным при поднятии\nУникальный"},
[227746] = {name = "[q2]Руна Древа Жизни", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на плаще руну \"Древо жизни\":\n\n\nВы принимаете облик древа жизни. В этом облике вы повышаете эффективность исцеления, получаемого участниками группы в радиусе 45 м, на 10%. Эффективность исцеления \"Буйного роста\" повышается на 60%. Затраты маны на заклинания периодического исцеления снижаются на 20%. Ваш дух повышается на 25%, ваша броня усиливается на 200%, и вы не можете применять наносящие урон заклинания.\n\n Смена облика снимает с вас превращение и ограничивающие передвижение эффекты.\n[q]\"Обучает новой способности гравировки.\""},
[227747] = {name = "Семейные записи", additional_info = "Становится персональным при поднятии\nУникальный"},
[227748] = {name = "Дневник выжившего", additional_info = "Предмет, необходимый для задания\nУникальный\n[q2]<Щелкните правой кнопкой мыши, чтобы прочитать.>"},
[227749] = {name = "[q2]Руна падающей звезды", additional_info = "Становится персональным при поднятии\nУникальный\nКлассы: Друид\n[q2]Выгравировать на плаще руну \"Звездопад\":\n\n\nВы на 10 сек. обрушиваете на цели в радиусе 30 м от вас град звезд, каждая из которых наносит [46 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]-[54 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от тайной магии цели и [8 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от тайной магии другим противникам в радиусе 5 м. Максимальное количество звезд – 20.\n\n Принятие облика зверя или вызов средства передвижения прекращает действие эффекта. Эффекты, вызывающие потерю контроля над вашим персонажем, прерывают действие \"Звездопада\".\n\n Большая часть эффектов и талантов, которые активируются \"Лунным огнем\" или усиливают эту способность, также взаимодействует со \"Звездопадом\".\n[q]\"Обучает новой способности гравировки.\""},
