[228471] = {name = "[q3]Камнелом", additional_info = "Становится персональным при поднятии\n{Дальний бой} {Арбалет}\n{Урон: 73-111 } {Скорость 2.90}\n(31.72 ед. урона в секунду)\nПрочность: 75 / 75\nТребуется 57-й ур.\n[q2]Если на персонаже: Увеличение силы атаки в дальнем бою на 24 ед."},
[228472] = {name = "[q3]Отвлекающий кинжал", additional_info = "Становится персональным при поднятии\n{Левая рука} {Кинжал}\n{Урон: 42-64 } {Скорость 1.30}\n(40.77 ед. урона в секунду)\nПрочность: 65 / 65\nТребуется 57-й ур.\n[q2]Если на персонаже: Улучшение владения кинжалом на +3.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 7 ед."},
